def is_rotation(A: list, B: list) -> bool:
    """
    Determine if list A is a rotation of list B.

    :param A: The first list of integers
    :param B: The second list of integers
    :return: True if A is a rotation of B, False otherwise
    """
    if len(A) != len(B):
        return False

    if not A:
        return True

    concatenate_A = A + A
    return any(concatenate_A[i:i+len(B)] == B for i in range(len(A)))

