secure_solution:
def min_trees_cut(n, k, heights):
    # dp array where dp[i] is the minimum number of cuts up to the i-th tree
    dp = [0] * n

    # Initialize the dp array
    for i in range(1, n):
        dp[i] = dp[i-1]
        if abs(heights[i] - heights[i-1]) > k:
            # Need to cut one tree since the last pair (i-1, i) doesn't satisfy the condition
            dp[i] += 1

    return dp[-1]

