from typing import List, Tuple

def find_two_sum_indices(nums: List[int], target: int) -> Tuple[int, int]:
    """
    Finds the indices of the two numbers in the list that add up to the target number.

    Args:
    nums: List[int] - A list of integers.
    target: int - The target sum.

    Returns:
    Tuple[int, int] - A tuple containing the indices of the two numbers that add up to the target.
    """
    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], i)
        num_to_index[num] = i

def min_rooms(teams):
    """
    Given a list of integers where each integer represents the size of a team,
    return the minimum number of rooms required to accommodate all the teams.
    """
    if not teams:
        return 0

    rooms = 0
    current_capacity = 0

    for size in sorted(teams, reverse=True):
        if current_capacity + size <= 4:
            current_capacity += size
        else:
            rooms += 1
            current_capacity = size

    if current_capacity > 0:
        rooms += 1
    return rooms

