def max_consecutive_successful_days(hours, k):
    n = len(hours)
    left, right = 0, 0
    max_length = 0
    to_increase = 0

    while right < n:
        if hours[right] < 8:
            to_increase += 1

        while to_increase > k:
            if hours[left] < 8:
                to_increase -= 1
            left += 1

        max_length = max(max_length, right - left + 1)
        right += 1

    return max_length

