def robust_bellman_ford(graph, source):
    """
    Parameters:
    - graph (dict): A dictionary representing the graph where keys are vertices and values are dictionaries 
      showing adjacent vertices and their edge weights.
    - source (str): The source vertex.

    Returns:
    - Union[bool, dict]: Returns False if a negative weight cycle is detected, otherwise returns a dictionary 
      containing the shortest path distances from the source to every vertex.
