def evaluateExpression(s):
    """
    Evaluates an arithmetic expression containing integers, '+' and '*' operators.
    The '*' operator has higher precedence over the '+' operator.
    """
    if not s:
        return 0

    num = 0
    stack = []
    sign = '+'

    for i, char in enumerate(s):
        if char.isdigit():
            num = num * 10 + int(char)

        if char in '+*' or i == len(s) - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '*':
                stack[-1] *= num
            sign = char
            num = 0

    return sum(stack)

