def countSquares(matrix):
    """
    Count the number of square submatrices with all 1s.

    Parameters:
    matrix (List[List[int]]): The m x n matrix of zeros and ones.

    Returns:
    int: The total number of square submatrices with all 1s.
    """
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])
    dp = [[0] * n for _ in range(m)]  # dp table to store the size of the largest square ending at each cell
    count = 0

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1  # Top row or left column
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                count += dp[i][j]

    return count

def uniquePathsWithObstacles(grid, n, m):
    """
    Function to find the number of unique paths from top-left to bottom-right
    avoiding obstacles on the grid.

    Parameters:
    grid (List[List[int]]): 2D list representing the grid with obstacles
    n (int): number of rows
    m (int): number of columns

    Returns:
    int: number of unique paths
    """
    if not grid or grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return 0

    dp = [[0] * m for _ in range(n)]

    dp[0][0] = 1  # Starting point

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1]

