def longest_subconsecutive_sequence(nums):
    """
    Return the length of the longest subconsecutive sequence of integers in nums.
    """
    if not nums:
        return 0

    nums = list(set(nums))  # Remove duplicates
    nums.sort()

    longest_streak = 1
    current_streak = 1

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1] + 1:
            current_streak += 1
        else:
            longest_streak = max(longest_streak, current_streak)
            current_streak = 1

    return max(longest_streak, current_streak)

