def decrypt_string(s):
    """
    Decrypts the encrypted string where:
        - all alphabetical characters are shifted by 1 position in the alphabet.
        - all digits are reversed (0 becomes 9, 1 becomes 8, ..., 9 becomes 0).
        - spaces and special characters remain unchanged.

    :param s: encrypted string
    :return: decrypted string
    """
    decrypted = []

    for char in s:
        if 'a' <= char <= 'z':
            decrypted.append(chr((ord(char) - ord('a') - 1) % 26 + ord('a')))
        elif 'A' <= char <= 'Z':
            decrypted.append(chr((ord(char) - ord('A') - 1) % 26 + ord('A')))
        elif '0' <= char <= '9':
            decrypted.append(str(9 - int(char)))
        else:
            decrypted.append(char)

    return ''.join(decrypted)

