from typing import List

def find_substring_indices(text: str, word: str) -> List[int]:
    if not text or not word:
        return []

    n, m = len(text), len(word)
    if m > n:
        return []

    base = 256  # Larger base to avoid collisions
    mod = 101  # Prime number for modulus operation

    word_hash = 0
    text_hash = 0
    h = 1  # The value of base^(m-1)

    for i in range(m-1):
        h = (h * base) % mod

    for i in range(m):
        word_hash = (base * word_hash + ord(word[i])) % mod
        text_hash = (base * text_hash + ord(text[i])) % mod

    result = []

    for i in range(n - m + 1):
        if word_hash == text_hash:
            if text[i:i+m] == word:
                result.append(i)

        if i < n - m:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + m])) % mod
            if text_hash < 0:
                text_hash += mod

    return result

