def longest_subarray(arr):
    """
    Returns the length of the longest subarray in which the absolute difference
    between any two consecutive elements is at most 1.
    """
    if not arr:
        return 0

    max_len = 1
    cur_len = 1

    for i in range(1, len(arr)):
        if abs(arr[i] - arr[i - 1]) <= 1:
            cur_len += 1
            max_len = max(max_len, cur_len)
        else:
            cur_len = 1

    return max_len

