def can_partition_with_diff_k(n, k, array):
    total_sum = sum(array)

    if (total_sum - k) % 2 != 0:
        return "NO", [], []

    target = (total_sum - k) // 2

    dp = [False] * (target + 1)
    dp[0] = True

    for num in array:
        for j in range(target, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]

    if not dp[target]:
        return "NO", [], []

    subset1 = []
    subset2 = []
    current_sum = target
    for num in reversed(array):
        if current_sum >= num and dp[current_sum - num]:
            subset1.append(num)
            current_sum -= num
        else:
            subset2.append(num)

    return "YES", subset1, subset2

