def steps_to_one(n):
    """
    Returns the number of steps required for n to reach 1
    following the sequence rules.
    """
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

