def count_divisible_pairs(nums, k):
    """
    Returns the number of unique pairs (i, j) where i < j and
    nums[i] + nums[j] is divisible by k.
    """
    count = 0
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if (nums[i] + nums[j]) % k == 0:
                count += 1
    return count

