def process_operations(operations):
    """
    Processes a series of stack operations and returns the sum of elements in the stack after all operations.

    Parameters:
    - operations: List of operations as strings.

    Returns:
    - An integer representing the sum of elements in the stack after processing all operations.
    """
    stack = []

    for operation in operations:
        parts = operation.split()
        if parts[0] == "PUSH":
            stack.append(int(parts[1]))
        elif parts[0] == "POP":
            if stack:
                stack.pop()
        elif parts[0] == "INC":
            K = int(parts[1])
            V = int(parts[2])
            for i in range(min(K, len(stack))):
                stack[i] += V

    return sum(stack)

