def longest_even_sum_subsequence(arr):
    """
    Returns the length of the longest subsequence whose sum is even.
    """
    total_sum = sum(arr)

    # If the total sum is already even, return the length of the whole array
    if total_sum % 2 == 0:
        return len(arr)

    # If the total sum is odd, find the smallest odd number in the array to remove
    min_odd = float('inf')
    for num in arr:
        if num % 2 != 0:
            min_odd = min(min_odd, num)

    # If there is no odd number, the array is full of even numbers and sum will be even already
    if min_odd == float('inf'):
        return len(arr)

    # Calculate the new length if we remove one of the smallest odd number
    return len(arr) - 1

