def parse_command(command: str) -> dict:
    """
    Parses a command string and returns a structured dictionary with keys action, direction, and item
    as applicable.
    """
    command = command.lower().strip()
    words = command.split()

    if len(words) == 0:
        return {}

    action = words[0]
    valid_actions = ["go", "take", "drop", "save", "load"]
    directions = ["north", "south", "east", "west"]

    if action not in valid_actions:
        return {}

    result = {"action": action}

    if action == "go":
        if len(words) == 2 and words[1] in directions:
            result["direction"] = words[1]
        else:
            return {}
    elif action == "take" or action == "drop":
        if len(words) == 2:
            result["item"] = words[1]
        else:
            return {}

    return result

