def calculate_student_averages(students):
    if not isinstance(students, list) or not all(isinstance(student, dict) for student in students):
        return "Invalid input"

    results = []
    for student in students:
        name = student.pop("name", None)
        if name is None or not student:
            continue
        total_score = sum(student.values())
        num_subjects = len(student)
        average_score = total_score // num_subjects
        results.append((name, average_score))

    return results

