from typing import List

def detect_spike(timestamps: List[int], window_size: int) -> int:
    n = len(timestamps)
    if n == 0:
        return -1

    max_count = 0
    max_start_time = timestamps[0]

    left = 0
    for right in range(n):
        while timestamps[right] - timestamps[left] >= window_size:
            left += 1

        current_count = right - left + 1
        if current_count > max_count:
            max_count = current_count
            max_start_time = timestamps[left]

    return max_start_time

