from collections import Counter
from typing import List, Tuple

def predict_next_item(sequences: List[List[int]], window_size: int) -> List[Tuple[List[int], int]]:
    result = []
    for sequence in sequences:
        if len(sequence) < window_size:
            continue  # skip sequences shorter than the window size
        for i in range(len(sequence) - window_size + 1):
            window = sequence[i:i + window_size]
            most_common_item = Counter(window).most_common(1)[0][0]
            result.append((window, most_common_item))
    return result

