def smallest_lexicographical_string(s, k):
    """
    Function to return the lexicographically smallest string possible after exactly k deletions.
    """
    stack = []
    for i, ch in enumerate(s):
        # Remove characters from stack if they make the string lexicographically larger and we still have deletions left
        while k > 0 and stack and stack[-1] > ch:
            stack.pop()
            k -= 1
        stack.append(ch)

    # if k is still greater than 0 after the main loop, it means we need to remove remaining elements from the end
    while k > 0:
        stack.pop()
        k -= 1

    return ''.join(stack)

