def subarrays_div_by_k(nums, k):
    """
    Returns the number of non-empty subarrays that have a sum divisible by k.
    """
    prefix_sum = 0
    prefix_sums_count = {0: 1}
    subarray_count = 0

    for num in nums:
        prefix_sum += num
        remainder = prefix_sum % k

        # Adjust negative remainders to be positive within a range of 0 to k-1
        if remainder < 0:
            remainder += k

        if remainder in prefix_sums_count:
            subarray_count += prefix_sums_count[remainder]

        # Count the number of times each remainder appears
        if remainder in prefix_sums_count:
            prefix_sums_count[remainder] += 1
        else:
            prefix_sums_count[remainder] = 1

    return subarray_count

