def can_sum_to_target(nums, target):
    """
    Returns True if a non-empty sequence of the elements in `nums` sums exactly to `target`, 
    maintaining the relative order of the elements. Returns False otherwise.
    """
    n = len(nums)
    # Create a 2D DP array where dp[i][j] means whether a subset of nums[:i] can sum up to j
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    # There is always a way to sum to 0 by taking an empty subset
    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if nums[i - 1] <= j:
                # Include nums[i-1] or not
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
            else:
                # Can't include nums[i-1]
                dp[i][j] = dp[i - 1][j]

    return dp[n][target]

