def positions_before_last_move(position):
    """
    Returns the positions of the balls just before the last move is made.
    If the game cannot be started, return an empty list.
    """
    position.sort()
    n = len(position)

    if n == 0 or n == 1:
        return []

    for i in range(1, n):
        if position[i] - position[i-1] > 1:
            return position

    return []

