def longest_subsequence(arr):
    if not arr:
        return 0

    # DP table to keep the longest subsequence length ending at each position
    dp = [1] * len(arr)

    # Iterate through the array to fill the dp table
    for i in range(1, len(arr)):
        for j in range(i):
            if abs(arr[i] - arr[j]) == 1:
                dp[i] = max(dp[i], dp[j] + 1)

    # The result will be the maximum value in the dp table
    return max(dp)

