def longestZigZag(arr):
    n = len(arr)

    # Edge case: If the array has less than 2 elements, the longest zigzag is itself
    if n < 2:
        return (n, arr)

    up = [1] * n
    down = [1] * n
    up_seq = [[] for _ in range(n)]
    down_seq = [[] for _ in range(n)]

    for i in range(n):
        up_seq[i] = down_seq[i] = [arr[i]]

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and up[i] < down[j] + 1:
                up[i] = down[j] + 1
                up_seq[i] = down_seq[j] + [arr[i]]
            elif arr[i] < arr[j] and down[i] < up[j] + 1:
                down[i] = up[j] + 1
                down_seq[i] = up_seq[j] + [arr[i]]

    if max(up) > max(down):
        max_length = max(up)
        zigzag_sequence = up_seq[up.index(max_length)]
    else:
        max_length = max(down)
        zigzag_sequence = down_seq[down.index(max_length)]

    return (max_length, zigzag_sequence)

