def max_good_strings(s):
    """
    Returns the maximum number of good strings (non-empty) that can be obtained by deleting some 
    (possibly none, but not all) characters from s. Each good string is a non-empty subsequence of s.
    """
    if not s:
        return 0

    count = 1 # Since we always have at least one good string (the string itself if we delete none)
    for i in range(1, len(s)):
        if s[i] != s[i-1]:
            count += 1

    return count

