secure_solution:
def can_sort_cards(n, k, initial_order, powers):
    """
    Determines if it's possible to arrange the cards in non-decreasing order using allowed swap operations.

    :param n: number of cards
    :param k: maximum allowed difference in special powers for swap
    :param initial_order: list representing initial order of cards
    :param powers: list representing special powers of each card
    :return: "Yes" if it is possible, else "No"
    """
    powers_dict = {i+1: powers[i] for i in range(n)}
    sorted_order = sorted(initial_order, key=lambda x: powers_dict[x])

    for i in range(n):
        for j in range(i, n):
            if powers_dict[initial_order[i]] > powers_dict[initial_order[j]] and abs(powers_dict[initial_order[i]] - powers_dict[initial_order[j]]) <= k:
                initial_order[i], initial_order[j] = initial_order[j], initial_order[i]

    if initial_order == sorted_order:
        return "Yes"
    else:
        return "No"

