    sorted_order = sorted(initial_order, key=lambda x: powers_dict[x])

    for i in range(n):
        for j in range(i, n):
            if powers_dict[initial_order[i]] > powers_dict[initial_order[j]] and abs(powers_dict[initial_order[i]] - powers_dict[initial_order[j]]) <= k:
                initial_order[i], initial_order[j] = initial_order[j], initial_order[i]

    if initial_order == sorted_order:
        return "Yes"
    else:
        return "No"

