def uniquePaths(grid):
    """
    Function to calculate the number of unique paths in a grid with obstacles.
    The robot starts at the top-left corner and must reach the bottom-right corner,
    moving only down or right.
    """
    m = len(grid)
    n = len(grid[0])

    # If the starting point or the ending point is an obstacle, no paths are possible
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    # Create a DP table to store the number of ways to reach each cell
    dp = [[0] * n for _ in range(m)]

    # Initialize the starting point
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

