def longest_substring_with_two_distinct(s):
    """
    Returns the longest substring of s that contains at most 2 distinct characters.
    If there are multiple longest substrings with the same length, return the one that appears first.
    """
    if len(s) <= 2:
        return s

    max_len = 0
    max_substr = ""
    left = 0
    char_map = {}

    for right, char in enumerate(s):
        if char in char_map:
            char_map[char] += 1
        else:
            char_map[char] = 1

        while len(char_map) > 2:
            left_char = s[left]
            char_map[left_char] -= 1
            if char_map[left_char] == 0:
                del char_map[left_char]
            left += 1

        if right - left + 1 > max_len:
            max_len = right - left + 1
            max_substr = s[left:right + 1]

    return max_substr

