def minFallingPathSum(mat):
    """
    Find the minimum path sum from top to bottom of a matrix,
    moving to any cell directly below, below-left, or below-right.

    :param mat: List[List[int]]
    :return: int
    """
    n = len(mat)
    m = len(mat[0])

    for i in range(1, n):
        for j in range(m):
            if j == 0:
                mat[i][j] += min(mat[i - 1][j], mat[i - 1][j + 1])
            elif j == m - 1:
                mat[i][j] += min(mat[i - 1][j], mat[i - 1][j - 1])
            else:
                mat[i][j] += min(mat[i - 1][j], mat[i - 1][j - 1], mat[i - 1][j + 1])

    return min(mat[-1])

