def three_sum_zero(nums):
    """
    Determine if there exist three distinct elements in the list that sum up to zero.

    :param nums: List of integers
    :return: "YES" or "NO"
    """
    nums.sort()
    n = len(nums)
    for i in range(n-2):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        left, right = i+1, n-1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                return "YES"
            elif total < 0:
                left += 1
            else:
                right -= 1
    return "NO"

