def longest_sequence(target):
    """
    Finds the longest sequence of consecutive integers that sum up to a given target.
    """

    sequence = []
    for start in range(1, abs(target) + 1):
        sum_val = 0
        current_sequence = []
        for num in range(start, abs(target) + 1):
            sum_val += num
            current_sequence.append(num)
            if sum_val == target:
                if len(current_sequence) > len(sequence) or not sequence:
                    sequence = current_sequence
                break
            elif sum_val > target:
                break

    return sequence

