def unique_paths_with_obstacles(obstacle_grid):
    """
    Calculate the number of unique paths from the top-left corner to the bottom-right corner of a grid
    with obstacles, where 1 indicates an obstacle and 0 indicates an empty space.
    """
    if not obstacle_grid or obstacle_grid[0][0] == 1:
        return 0

    m, n = len(obstacle_grid), len(obstacle_grid[0])

    # Initialize a 2D dp array dp[i][j] to store the number of unique paths to cell (i, j).
    dp = [[0] * n for _ in range(m)]

    # Start point
    dp[0][0] = 1

    # Fill the dp array
    for i in range(m):
        for j in range(n):
            if obstacle_grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

