from collections import deque

def min_hours_to_ripe_all(grid):
    n = len(grid)
    if not grid:
        return -1

    queue = deque()
    total_ripe = 0

    # Initialize the queue with all ripe crops
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                queue.append((i, j))
                total_ripe += 1

    if total_ripe == 0:  # No initial ripe crop to start the process
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    hours = 0
    while queue:
        size = len(queue)
        for _ in range(size):
            x, y = queue.popleft()
            for d in directions:
                new_x, new_y = x + d[0], y + d[1]
                if 0 <= new_x < n and 0 <= new_y < n and grid[new_x][new_y] == 0:
                    grid[new_x][new_y] = 1
                    queue.append((new_x, new_y))
                    total_ripe += 1

        if queue:
            hours += 1

    for row in grid:
        if 0 in row:
            return -1

    if total_ripe == n * n:
        return hours
    else:
        return -1

