            for d in directions:
                new_x, new_y = x + d[0], y + d[1]
                if 0 <= new_x < n and 0 <= new_y < n and grid[new_x][new_y] == 0:
                    grid[new_x][new_y] = 1
                    queue.append((new_x, new_y))
                    total_ripe += 1

        if queue:
            hours += 1

    for row in grid:
        if 0 in row:
            return -1

    if total_ripe == n * n:
        return hours
    else:
        return -1

