def can_place_books_on_shelves(T, test_cases):
    results = []
    for i in range(T):
        M, N = test_cases[i][:2]
        capacities = sorted(test_cases[i][2:2+M], reverse=True)
        books = sorted(test_cases[i][2+M:], reverse=True)

        if len(capacities) < len(books):
            results.append("NO")
            continue

        possible = True
        for book in books:
            placed = False
            for j in range(len(capacities)):
                if capacities[j] >= book:
                    capacities[j] -= book
                    placed = True
                    break
            if not placed:
                possible = False
                break

        results.append("YES" if possible else "NO")

    return results

