def count_subsequences(planets, glider_sequence):
    """
    Returns the number of different subsequences in the planet list that match the glider sequence.
    """
    n, m = len(planets), len(glider_sequence)
    dp = [0] * (m + 1)
    dp[0] = 1

    for planet in planets:
        for j in range(m - 1, -1, -1):
            if planet == glider_sequence[j]:
                dp[j + 1] += dp[j]

    return dp[m]

