def min_moves_to_reach_destination(n, s_x, s_y, e_x, e_y, intersections):
    if (s_x, s_y) == (e_x, e_y):
        return 0

    queue = deque([(s_x, s_y, 0)])  # (x, y, distance)
    visited = set()
    visited.add((s_x, s_y))

    while queue:
        x, y, dist = queue.popleft()

        for i in range(n):
            i_x, i_y = intersections[i]

            if ((x == i_x and y != i_y) or (y == i_y and x != i_x)):
