def closest_pair(arr, target):
    """
    Returns a pair of integers from arr whose sum is closest to the target.
    """
    if len(arr) < 2:
        return []

    arr = list(set(arr)) # Unique values only
    arr.sort()

    closest_sum = float('inf')  # Initialize with an infinitely large number
    result_pair = []

    left, right = 0, len(arr) - 1

    while left < right:
        current_sum = arr[left] + arr[right]
        if abs(target - current_sum) < abs(target - closest_sum):
            closest_sum = current_sum
            result_pair = [arr[left], arr[right]]
        elif abs(target - current_sum) == abs(target - closest_sum):
            if current_sum < closest_sum:
                closest_sum = current_sum
                result_pair = [arr[left], arr[right]]

        if current_sum < target:
            left += 1
        else:
            right -= 1

    return result_pair

