def find_max_average(arr, k):
    if len(arr) < k:
        raise ValueError("The length of the array must be greater than or equal to k.")

    # Initial window sum
    max_sum = sum(arr[:k])
    window_sum = max_sum

    # Sliding window to find the maximum sum
    for i in range(k, len(arr)):
        window_sum = window_sum - arr[i - k] + arr[i]
        if window_sum > max_sum:
            max_sum = window_sum

    # Calculate the maximum average
    max_average = max_sum / k
    return round(max_average, 5)

