def min_trucks(n, C, weights):
    """
    Determine the minimum number of trucks required to transport all the crates.
    """
    weights.sort(reverse=True)
    trucks = 0
    while weights:
        capacity = C
        i = 0
        while i < len(weights):
            if weights[i] <= capacity:
                capacity -= weights.pop(i)
            else:
                i += 1
        trucks += 1
    return trucks

