import itertools
import math

def is_permutation_a_square(N):
    str_N = str(N)
    permutations = itertools.permutations(str_N)
    seen = set()
    for perm in permutations:
        num = int(''.join(perm))
        if num not in seen:
            seen.add(num)
            if num == int(math.isqrt(num)) ** 2:
                return "YES"
    return "NO"

