def min_removals_for_lexicographical_order(n, books):
    """
    Returns the minimal number of books that need to be removed so that the remaining books are in lexicographical order.
    """
    from bisect import bisect_left

    # This will store the longest increasing subsequence
    lis = []

    # Iterate through each book
    for book in books:
        pos = bisect_left(lis, book)
        if pos == len(lis):
            lis.append(book)
        else:
            lis[pos] = book

    # The number of removals needed
    return n - len(lis)

from collections import deque

def shortest_path(grid):
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return -1

    m, n = len(grid), len(grid[0])
    queue = deque([(0, 0, 0)])  # (row, col, steps)
    visited = set((0, 0))
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while queue:
        x, y, steps = queue.popleft()
        if x == m - 1 and y == n - 1:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny] == 0:
                visited.add((nx, ny))
                queue.append((nx, ny, steps + 1))

    return -1

