def sum_of_adjacent(nums):
    """
    Given an integer array `nums`, return an array where each element is replaced by the sum of its adjacent elements.

    Parameters:
        nums (list): A list of integers.

    Returns:
        list: A list of integers where each element is the sum of its adjacent elements.
    """
    if not nums:
        return []

    n = len(nums)

    # Special case for single element array
    if n == 1:
        return nums

    result = [0] * n
    for i in range(n):
        if i == 0:
            result[i] = nums[i + 1]
        elif i == n - 1:
            result[i] = nums[i - 1]
        else:
            result[i] = nums[i - 1] + nums[i + 1]

    return result

