from collections import Counter

def count_distinct_permutations(s, words):
    """
    Returns the count of all distinct permutations of `s` that appear as a substring
    in any of the strings in `words`.
    """
    s_len = len(s)
    s_counter = Counter(s)
    permutations = set()

    for word in words:
        word_len = len(word)
        for i in range(word_len - s_len + 1):
            substring = word[i:i+s_len]
            if Counter(substring) == s_counter:
                permutations.add((word, i))

    return len(permutations)

