def longest_contiguous_substring(data):
    """
    Returns the longest contiguous substring containing only letters or only digits.
    If there are multiple longest substrings of the same length, return the first one.
    If the input string is empty, return an empty string.
    """
    if not data:
        return ""

    longest_substring = ""
    current_substring = data[0]

    for char in data[1:]:
        if char.isdigit() and current_substring[-1].isdigit():
            current_substring += char
        elif char.isalpha() and current_substring[-1].isalpha():
            current_substring += char
        else:
            if len(current_substring) > len(longest_substring):
                longest_substring = current_substring
            current_substring = char

    if len(current_substring) > len(longest_substring):
        longest_substring = current_substring

    return longest_substring

