def min_time_to_complete_tasks(tasks, cooldown):
    from collections import defaultdict

    # Dictionary to store the last execution time of each task
    last_execution_time = defaultdict(lambda: -float('inf'))
    current_time = 0

    for task in tasks:
        if current_time - last_execution_time[task] <= cooldown:
            current_time = last_execution_time[task] + cooldown + 1
        else:
            current_time += 1
        last_execution_time[task] = current_time

    return current_time

