def manage_inventory(N, M, shipments, orders):
    # Initialize inventory with zeros
    inventory = [0] * N
    fulfilled_days = 0

    for day in range(M):
        # Add shipment items to inventory
        for i in range(N):
            inventory[i] += shipments[day][i]

        # Check if orders can be fulfilled
        can_fulfill = True
        for i in range(N):
            if inventory[i] < orders[day][i]:
                can_fulfill = False
                break

        if can_fulfill:
            # Fulfill the orders
            for i in range(N):
                inventory[i] -= orders[day][i]
            fulfilled_days += 1
        else:
            break

    return fulfilled_days

