def minimum_swaps_to_sort(arr):
    """
    Returns the minimum number of adjacent swaps required to sort the array.
    """
    n = len(arr)
    swaps = 0
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swaps += 1
    return swaps

