from typing import List

def max_contiguous_subsequence_sum(arr: List[int]) -> int:
    if not arr:
        return 0

    max_sum = arr[0]
    current_sum = arr[0]

    for num in arr[1:]:
        current_sum = max(num, current_sum + num)
        max_sum = max(max_sum, current_sum)

    return max_sum

def search_sorted_matrix(matrix, target):
    """
    Searches for the target in a 2D sorted matrix (rows and columns sorted).
    Returns the position (row_index, column_index) if found, else (-1, -1).
    """
    if not matrix or not matrix[0]:
        return (-1, -1)

    rows = len(matrix)
    cols = len(matrix[0])

    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == target:
                return (i, j)

    return (-1, -1)

