def remove_backspaces(s):
    """
    Process a string `s` containing '#' characters that act as backspaces, 
    removing each '#' and the character preceding it.

    Args:
    s (str): Input string containing lowercase letters and '#' characters.

    Returns:
    str: The resulting string after processing all backspaces.
    """
    stack = []
    for char in s:
        if char == '#':
            if stack:
                stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

