        if required_number in range(1, n + 1):
            print("YES")
            for i in range(1, n):
                print(f"{i} + {i + 1} = {i + i + 1}")
            return

    sequence_sum = (1 + n) * n // 2

    # Calculate the first few terms of the arithmetic progression
