def count_increasing_triplets(arr):
    n = len(arr)
    count = 0

    # Iterate through each possible j for the middle of the triplet
    for j in range(1, n-1):
        count_i = 0
        count_k = 0

        # Count elements less than arr[j] before index j
        for i in range(j):
            if arr[i] < arr[j]:
                count_i += 1

        # Count elements greater than arr[j] after index j
        for k in range(j+1, n):
            if arr[k] > arr[j]:
                count_k += 1

        count += count_i * count_k

