def min_operations_to_make_equal(s1, s2):
    """
    Determines the minimum number of operations required to make s1 equal to s2.
    An operation is defined as an insertion, deletion, or substitution of a character.

    Uses the Levenshtein distance (edit distance) algorithm to find the solution.
    """
    if s1 == s2:
        return 0

    len_s1, len_s2 = len(s1), len(s2)

    # Create a 2D array to store the distance
    dp = [[0] * (len_s2 + 1) for _ in range(len_s1 + 1)]

    for i in range(len_s1 + 1):
        for j in range(len_s2 + 1):
            if i == 0:
                dp[i][j] = j  # Insert all s2's characters to s1
            elif j == 0:
                dp[i][j] = i  # Delete all s1's characters
            elif s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]  # Characters are the same, no operation needed
            else:
                dp[i][j] = 1 + min(
                    dp[i-1][j],    # Deletion
                    dp[i][j-1],    # Insertion
                    dp[i-1][j-1]   # Substitution
                )

    return dp[len_s1][len_s2]

