def count_ways(N):
    MOD = 1000000007
    ways = [0] * (N + 1)
    ways[0] = 1  # There's one way to arrange 0 plants
    for i in range(1, N + 1):
        for j in range(i, N + 1):
            ways[j] = (ways[j] + ways[j - i]) % MOD

    return ways[N]

