def minimumCardPickup(cards):
    """
    Returns the minimum distance between pairs of indices (i, j) such that cards[i] == cards[j].
    If no such pairs exist, returns -1.
    """
    last_seen = {}
    min_distance = float('inf')

    for i, card in enumerate(cards):
        if card in last_seen:
            min_distance = min(min_distance, i - last_seen[card])
        last_seen[card] = i

    return min_distance if min_distance != float('inf') else -1

