def can_form_palindrome_with_k_modifications(n, q, s, queries):
    results = []

    for l, r, k in queries:
        substr = s[l-1:r]
        frequency = {}

        for char in substr:
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1

        odd_count = sum(1 for count in frequency.values() if count % 2 != 0)
        # To make odd_count number of characters occurrences to even, we need (odd_count // 2) modifications
        modifications_required = odd_count // 2

        if modifications_required <= k:
            results.append("YES")
        else:
            results.append("NO")

    return results

