def find_pair(l, target_sum):
    """
    Determines if there are any two distinct numbers in the list that add up to the target sum.
    If such a pair exists, return a tuple containing the two numbers.
    If no such pair exists, return None.
    """
    seen = set()
    for number in l:
        complement = target_sum - number
        if complement in seen:
            return (complement, number)
        seen.add(number)
    return None

