def closest_sum_to_target(n, target, weights):
    """
    Returns the closest sum to the target weight without exceeding it.

    :param n: int, number of weights
    :param target: int, target weight
    :param weights: list of int, weights of objects
    :return: int, closest sum to the target weight
    """
    possible_sums = {0}

    for weight in weights:
        new_sums = set()
        for s in possible_sums:
            if s + weight <= target:
                new_sums.add(s + weight)
        possible_sums.update(new_sums)

    return max(possible_sums)

