def max_sum_subgrid(grid):
    """
    Returns the largest sum of any subgrid in the given grid.
    """
    n = len(grid)
    m = len(grid[0])
    max_sum = float('-inf')

    # Precompute prefix sums
    prefix_sum = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            prefix_sum[i + 1][j + 1] = grid[i][j] + prefix_sum[i + 1][j] + prefix_sum[i][j + 1] - prefix_sum[i][j]

    # Find the max sum of any subgrid using prefix sums
    for i1 in range(1, n + 1):
        for j1 in range(1, m + 1):
            for i2 in range(i1, n + 1):
                for j2 in range(j1, m + 1):
                    curr_sum = prefix_sum[i2][j2] - prefix_sum[i1 - 1][j2] - prefix_sum[i2][j1 - 1] + prefix_sum[i1 - 1][j1 - 1]
                    max_sum = max(max_sum, curr_sum)

    return max_sum

