from typing import List

def max_positive_sum(arr: List[int]) -> int:
    max_negative = float('-inf')
    has_positive = False
    max_ending_here = 0
    max_so_far = float('-inf')

    for num in arr:
        if num > 0:
            has_positive = True
        if num < 0 and num > max_negative:
            max_negative = num

        max_ending_here += num
        if has_positive and max_ending_here > max_so_far:
            max_so_far = max_ending_here
        if max_ending_here < 0:
            max_ending_here = 0

    return max_so_far if has_positive else max_negative

