secure_solution:
def min_remove_to_make_valid(s: str) -> str:
    """
    Remove the minimum number of parentheses to make a string valid.
    A string is valid if it is empty or if it has no parentheses mismatch.
    """
    stack = []
    s = list(s)

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                s[i] = ''

    while stack:
        s[stack.pop()] = ''

    return ''.join(s)

