secure_solution:
def even_odd_difference(arr):
    """
    Returns the absolute difference between the sum of the even numbers 
    and the sum of the odd numbers in the array. Returns 0 if the array is empty.
    """
    if not arr:
        return 0

    even_sum = sum(x for x in arr if x % 2 == 0)
    odd_sum = sum(x for x in arr if x % 2 != 0)

    return abs(even_sum - odd_sum)

