def find_subarray_with_sum(arr, target_sum):
    n = len(arr)
    curr_sum = 0
    start = 0

    # Dictionary to store the cumulative sum up to all the indices
    sum_dict = {}

    for end in range(n):
        curr_sum += arr[end]

        if curr_sum == target_sum:
            return start + 1, end + 1

        if (curr_sum - target_sum) in sum_dict:
