def max_unique_chars_partition(s, k):
    """
    Return the maximum number of unique characters that can be achieved by 
    partitioning the string `s` into `k` non-empty substrings.
    """
    if k > len(s):
        return -1

    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    unique_chars = list(freq.keys())
    partitions_needed = min(k, len(unique_chars))

    if partitions_needed < k:
        return -1

    return len(unique_chars)

