def optimized_combination(n: int, r: int) -> int:
    """
    Calculate the number of ways to choose r objects from n objects (nCr).
    """
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1

    # Initialize a table to store intermediate results
    C = [[0 for _ in range(r+1)] for _ in range(n+1)]

    # Calculate binomial coefficients using bottom-up approach
    for i in range(n+1):
        for j in range(min(i, r) + 1):
            # Base cases
            if j == 0 or j == i:
                C[i][j] = 1
            # Calculate value using previously stored values
            else:
                C[i][j] = C[i-1][j-1] + C[i-1][j]

    return C[n][r]

