def min_travel_costs(n, m, k, p, roads, airport_cities):
    inf = 10**9 + 1  # A large number to represent infinity.

    # Initialize the cost matrix with infinity.
    costs = [[inf] * n for _ in range(n)]

    # The cost of traveling to the same city is 0.
    for i in range(n):
        costs[i][i] = 0

    # Fill in the direct road costs.
    for u, v, c in roads:
        costs[u-1][v-1] = min(costs[u-1][v-1], c)
        costs[v-1][u-1] = min(costs[v-1][u-1], c)

    # Apply the reduced cost for traveling between cities with airports.
    for i in range(k):
        for j in range(i + 1, k):
            u = airport_cities[i] - 1
            v = airport_cities[j] - 1
            costs[u][v] = min(costs[u][v], p)
            costs[v][u] = min(costs[v][u], p)

    # Floyd-Warshall algorithm to find all-pairs shortest paths.
    for k in range(n):
        for i in range(n):
            for j in range(n):
                costs[i][j] = min(costs[i][j], costs[i][k] + costs[k][j])

    return costs

