def maxRectangleArea(M: List[List[int]]) -> int:
    if not M:
        return 0

    r, c = len(M), len(M[0])
    height = [0] * (c + 1)
    max_area = 0

    for row in M:
        for i in range(c):
            if row[i] == 0:
                height[i] = 0
            else:
                height[i] += 1

        stack = [-1]
        for i in range(c + 1):
            while height[i] < height[stack[-1]]:
                h = height[stack.pop()]
                w = i - stack[-1] - 1
                max_area = max(max_area, h * w)
            stack.append(i)

    return max_area

