from collections import deque

def find_transformation_sequence(start_word, end_word, dictionary):
    """
    Finds the shortest transformation sequence from start_word to end_word
    by changing one letter at a time, using words from the given dictionary.
    """
    if start_word == end_word:
        return [start_word]

    word_set = set(dictionary)
    if end_word not in word_set:
        return []

    queue = deque([(start_word, [start_word])])

    while queue:
        current_word, path = queue.popleft()
        for i in range(len(current_word)):
            for char in 'abcdefghijklmnopqrstuvwxyz':
                next_word = current_word[:i] + char + current_word[i+1:]
                if next_word == end_word:
                    return path + [end_word]
                if next_word in word_set:
                    queue.append((next_word, path + [next_word]))
                    word_set.remove(next_word)  # Mark word as visited
    return []

