def top_student_per_subject(students: List[Dict[str, Union[str, int]]]) -> Dict[str, Union[List[str], str]]:
    """
    Returns the top student or students per each subject.

    Parameters:
    students (List[Dict[str, Union[str, int]]]): A list of dictionaries, each containing a student's name
                                                 and their scores in various subjects.

    Returns:
    Dict[str, Union[List[str], str]]: A dictionary where the keys are subject names and the values are the 
                                      names of the students who scored the highest in that subject. If multiple 
                                      students have the highest score, their names are listed in a list.
    """
    if not students:
        return {}

    top_students = {}

    # Assuming all keys except 'name' are subject names
    subjects = students[0].keys() - {'name'}

    for subject in subjects:
        max_score = -float('inf')
        top_scorers = []

        for student in students:
            score = student[subject]
            if score > max_score:
                max_score = score
                top_scorers = [student['name']]
            elif score == max_score:
                top_scorers.append(student['name'])

        if len(top_scorers) == 1:
            top_students[subject] = top_scorers[0]
        else:
            top_students[subject] = top_scorers

    return top_students

