def construct_array(n, S):
    if n == 1:
        return [S]
    elif S < n:
        return -1
    else:
        # To make the sum S with n elements such that GCD is 1, initialize array with all ones
        array = [1] * (n - 1)
        remaining_sum = S - (n - 1)

        if remaining_sum == 1:
            if n == 2:
                return -1
            # Shift one of the ones to 2, to avoid remaining_sum being 1
            array[-2] += 1
            remaining_sum -= 1

        array.append(remaining_sum)
        return array

