def sum_of_products_of_pairs(N, numbers):
    """
    Returns the sum of the products of every possible pair of distinct integers from the list.
    """
    total_sum = 0
    for i in range(N):
        for j in range(i+1, N):
            total_sum += numbers[i] * numbers[j]
    return total_sum

