def two_sum(array, target):
    """
    Finds two distinct indices such that their values sum up to the target.

    Parameters:
    - array: List[int] : List of unique integers
    - target: int : Target sum

    Returns:
    - Tuple[int, int] : Tuple of two indices
    """
    value_to_index = {}

    for i, num in enumerate(array):
        complement = target - num
        if complement in value_to_index:
            return (value_to_index[complement], i)
        value_to_index[num] = i

