from typing import List

def minimum_subset_difference(weights: List[int]) -> int:
    """
    Finds the minimum difference between the sum of elements in any two non-empty subsets.
    """
    total_weight = sum(weights)
    n = len(weights)
    dp = [[False] * (total_weight // 2 + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(total_weight // 2 + 1):
            if j >= weights[i - 1]:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - weights[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    min_diff = float('inf')
    for j in range(total_weight // 2 + 1):
        if dp[n][j]:
            min_diff = min(min_diff, total_weight - 2 * j)

    return min_diff

