def max_candies(grid):
    n = len(grid)
    m = len(grid[0])

    # Create a DP table to store the maximum candies collectable at each cell
    dp = [[0] * m for _ in range(n)]

    # Initialize the dp table with the values of the first row
    for j in range(m):
        dp[0][j] = grid[0][j]

    # Fill the dp table row by row
    for i in range(1, n):
        for j in range(m):
            # Get the maximum candies collectable from the possible previous cells
            max_candies_from_previous = dp[i-1][j]  # Directly above
            if j > 0:
                max_candies_from_previous = max(max_candies_from_previous, dp[i-1][j-1])  # Diagonally left
            if j < m - 1:
                max_candies_from_previous = max(max_candies_from_previous, dp[i-1][j+1])  # Diagonally right

            dp[i][j] = grid[i][j] + max_candies_from_previous

    # The result is the maximum value in the last row of the dp table
    return max(dp[-1])

