def transform_array(n, k, array, operations):
    """
    Apply specified operations to transform the array.
    """
    for operation in operations:
        if operation[0] == 1:
            # Increase the element at position li by xi
            _, li, xi = operation
            array[li - 1] += xi
        elif operation[0] == 2:
            # Set all elements from position li to ri to the minimum value found in that subarray
            _, li, ri = operation[:3]
            subarray_min = min(array[li - 1:ri])
            for i in range(li - 1, ri):
                array[i] = subarray_min
    return array

def find_pair_indices(nums, target):
    """
    Returns the indices of the two numbers that add up to the target.
    If no such pair exists, returns -1.
    """
    num_to_index = {}

    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], index)
        num_to_index[num] = index

    return -1

