def super_digit(n: str) -> int:
    """
    Returns the super digit of the given large integer represented as a string.

    :param n: A large integer represented as a string.
    :return: The super digit of n.
    """
    if len(n) == 1:
        return int(n)

    digit_sum = sum(int(digit) for digit in n)

    return super_digit(str(digit_sum))

