def count_sentences(s: str, dictionaries: set) -> int:
    """
    Returns the number of ways the string s can be split into a sequence of words from dictionaries.
    """
    # Using dynamic programming to count number of ways to split s
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # base case: there's one way to split an empty string

    for i in range(1, n + 1):
        for word in dictionaries:
            if i >= len(word) and s[i-len(word):i] == word:
                dp[i] += dp[i-len(word)]

    return dp[n]

