def is_wiggle_sequence(n, sequence):
    """
    Determines if the given sequence is a wiggle sequence.

    Parameters:
    n (int): number of elements in the sequence
    sequence (list of int): the sequence of elements

    Returns:
    str: "YES" if the sequence is a wiggle sequence, "NO" otherwise
    """
    if n < 2:
        return "YES"

    diffs = []
    for i in range(1, n):
        diff = sequence[i] - sequence[i - 1]
        if diff != 0:
            diffs.append(diff)

    if len(diffs) == 0:
        return "NO"

    for i in range(1, len(diffs)):
        if diffs[i] * diffs[i - 1] >= 0:
            return "NO"

    return "YES"

