from collections import defaultdict

def find_frequent_elements(array: List[int], threshold: int) -> Dict[int, int]:
    """
    Uses the Misra-Gries algorithm to find elements in the array 
    which appear at least `threshold` number of times.
    """
    if len(array) < threshold:
        return {}

    # Step 1: Apply the Misra-Gries algorithm to narrow candidates
    k = threshold
    counter = defaultdict(int)

    for num in array:
        if num in counter:
            counter[num] += 1
        elif len(counter) < k - 1:
            counter[num] = 1
        else:
            keys_to_delete = []
            for key in counter:
                counter[key] -= 1
                if counter[key] == 0:
                    keys_to_delete.append(key)
            for key in keys_to_delete:
                del counter[key]

    # Step 2: Verify the candidates to get true frequent element counts
    result = defaultdict(int)
    for num in array:
        if num in counter:
            result[num] += 1

    # Step 3: Filter out candidates that do not meet the threshold
    frequent_elements = {num: count for num, count in result.items() if count >= threshold}

    return frequent_elements

