def max_machines_operating(logs):
    events = []
    for start, end in logs:
        events.append((start, 'start'))
        events.append((end, 'end'))

    events.sort()

    max_machines = 0
    current_machines = 0

    for event in events:
        if event[1] == 'start':
            current_machines += 1
            max_machines = max(max_machines, current_machines)
        else:
            current_machines -= 1

    return max_machines

