def min_difference(n, values):
    """
    Returns the minimum possible absolute difference between the sum of the values of the two groups.
    """
    total_sum = sum(values)
    target = total_sum // 2

    dp = [0] * (target + 1)

    for value in values:
        for i in range(target, value - 1, -1):
            dp[i] = max(dp[i], dp[i - value] + value)

    best_split_sum = dp[target]
    return abs((total_sum - best_split_sum) - best_split_sum)

