from collections import defaultdict

def rearrange_words(words):
    """
    Rearranges the words such that no two adjacent words have the same length.
    Returns an empty list if not possible.
    """
    length_dict = defaultdict(list)
    # Group words by their length
    for word in words:
        length_dict[len(word)].append(word)

    # Sort the lengths
    sorted_lengths = sorted(length_dict.keys())

    # Try to rearrange the words by alternating lengths
    rearranged_words = []
    while sorted_lengths:
        cycle = sorted_lengths.copy()
        for length in cycle:
            if length_dict[length]:
                rearranged_words.append(length_dict[length].pop())
            if not length_dict[length]:
                sorted_lengths.remove(length)

    # Check if the arrangement is valid
    for i in range(1, len(rearranged_words)):
        if len(rearranged_words[i]) == len(rearranged_words[i-1]):
            return []

    return rearranged_words

