def find_subsequence_with_sum(n, s, sequence):
    """
    Finds the start and end indices of the contiguous subsequence that sums to s.
    If no such subsequence exists, returns -1.
    """
    for start in range(n):
        curr_sum = 0
        for end in range(start, n):
            curr_sum += sequence[end]
            if curr_sum == s:
                return start + 1, end + 1
    return -1

