def min_subset_diff(arr):
    """
    Returns the minimum difference possible between the sums of two subsets of arr.
    """
    total_sum = sum(arr)
    n = len(arr)
    half_sum = total_sum // 2

    dp = [[False] * (half_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(0, half_sum + 1):
            if j >= arr[i-1]:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-arr[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    for j in range(half_sum, -1, -1):
        if dp[n][j]:
            return (total_sum - 2*j)

    return total_sum  # In worst case, the total sum difference is the total sum itself

