def combinationSum4(nums, target):
    """
    Returns the number of combinations that add up to target using the numbers in nums.
    You may use each number in nums as many times as needed.
    """
    dp = [0] * (target + 1)
    dp[0] = 1

    for i in range(1, target + 1):
        for num in nums:
            if i >= num:
                dp[i] += dp[i - num]

    return dp[target]

