def longest_distinct_substring(s):
    """
    Returns the longest substring of `s` that consists of distinct characters.
    """
    last_seen = {}
    start = 0
    max_length = 0
    start_index_of_max = 0

    for end in range(len(s)):
        if s[end] in last_seen:
            start = max(start, last_seen[s[end]] + 1)

        last_seen[s[end]] = end

        if end - start + 1 > max_length:
            max_length = end - start + 1
            start_index_of_max = start

    return s[start_index_of_max:start_index_of_max + max_length]

