def longest_unique_substring(s):
    """
    Returns the length of the longest substring with unique characters.
    """
    max_length = 0
    start = 0
    seen = {}

    for end in range(len(s)):
        if s[end] in seen and seen[s[end]] >= start:
            start = seen[s[end]] + 1
        seen[s[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

