from typing import List

def find_triplet_sum_zero(nums: List[int]) -> List[int]:
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                return [nums[i], nums[left], nums[right]]
            elif total < 0:
                left += 1
            else:
                right -= 1
    return []

