from collections import defaultdict, deque

def max_sum_to_leaf(n, node_values, edges):
    if n == 1:
        return node_values[0]

    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # Perform a BFS to calculate the maximum sum from root to any leaf
    max_sum = float('-inf')
    queue = deque([(1, node_values[0])]) # (current node, current path sum)
    visited = set([1])

    while queue:
        current_node, current_sum = queue.popleft()
        is_leaf = True

        for neighbor in tree[current_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, current_sum + node_values[neighbor - 1]))
                is_leaf = False

        if is_leaf:
            max_sum = max(max_sum, current_sum)

    return max_sum

