def max_golden_fruits(n, fruits):
    fruits.sort(reverse=True)
    total_pickable = 0

    for i in range(n):
        if i == 0: 
            # The most number of fruits we can pick will be from the tree with the most fruits
            total_pickable += fruits[i]
            continue

        max_fruits_possible = 2 * fruits[i]

        # If the current number of fruits on tree `i-1` is more than twice the current tree, return the max harvestable fruits
        if fruits[i-1] > max_fruits_possible:
            return total_pickable

    return total_pickable

