def longest_substring_with_two_distinct_characters(s):
    """
    Returns the longest substring of the input string s that contains at most 
    two distinct characters. If there are multiple such substrings, returns the 
    one that appears first.
    """

    if len(s) == 0:
        return ""

    start = 0
    max_length = 0
    max_substr_start = 0
    char_map = {}

    for end in range(len(s)):
        if s[end] in char_map:
            char_map[s[end]] += 1
        else:
            char_map[s[end]] = 1

        while len(char_map) > 2:
            char_map[s[start]] -= 1
            if char_map[s[start]] == 0:
                del char_map[s[start]]
            start += 1

        if end - start + 1 > max_length:
            max_length = end - start + 1
            max_substr_start = start

    return s[max_substr_start:max_substr_start + max_length]

