def find_subarray_sum(arr, target_sum):
    """
    Finds the starting and ending indices of the subarray that adds up to the target_sum.
    If no such subarray exists, returns None.
    """
    cum_sum = 0
    sum_indices = {}

    # Iterate over the array to find the subarray with the given sum
    for i, num in enumerate(arr):
        cum_sum += num

        # Check if the cumulative sum equals the target
        if cum_sum == target_sum:
            return (0, i)

        # Check if there is a subarray (0 to j) such that cum_sum - target_sum was seen before
        if cum_sum - target_sum in sum_indices:
            return (sum_indices[cum_sum - target_sum] + 1, i)

        # Store the cumulative sum with its corresponding index
        sum_indices[cum_sum] = i

    # Return None if no such subarray is found
    return None

