def smallest_contiguous_subarray_sum(arr):
    """
    Returns the smallest sum of any contiguous subarray in the list.
    """ 
    min_current = min_global = arr[0]
    for num in arr[1:]:
        min_current = min(num, min_current + num)
        if min_current < min_global:
            min_global = min_current
    return min_global

