secure_solution:
MOD = 10**9 + 7

def find_nth_element(n):
    """
    Returns the n-th element of the sequence A, modulo 10^9 + 7.
    """
    if n == 0:
        return 1
    elif n == 1:
        return 2

    a0, a1 = 1, 2
    for i in range(2, n + 1):
        a0, a1 = a1, (a1 + 2 * a0) % MOD

    return a1

