def rank_participants(scores):
    """
    Given a list of participant scores, return their ranks.
    """
    sorted_scores = sorted(enumerate(scores), key=lambda x: x[1], reverse=True)

    ranks = [0] * len(scores)
    current_rank = 1

    for i, (index, score) in enumerate(sorted_scores):
        if i == 0:
            ranks[index] = current_rank
        else:
            if score == sorted_scores[i-1][1]:
                ranks[index] = current_rank
            else:
                current_rank = i + 1
                ranks[index] = current_rank

    return ranks

