def max_unique_substrings(s: str, k: int) -> int:
    """
    Returns the maximum number of unique substrings of length k in the given string s.
    """
    if k > len(s) or k <= 0:
        return 0

    unique_substrings = set()

    for i in range(len(s) - k + 1):
        substring = s[i:i+k]
        unique_substrings.add(substring)

    return len(unique_substrings)

