import heapq

def min_toll(n, roads, start, end):
    """
    Returns the minimum toll fee to travel from start to end.
    """
    graph = {i: [] for i in range(n)}
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    min_heap = [(0, start)]  # (toll, town)
    visited = set()
    min_toll = {i: float('inf') for i in range(n)}
    min_toll[start] = 0

    while min_heap:
        toll, town = heapq.heappop(min_heap)
        if town in visited:
            continue

        visited.add(town)

        if town == end:
            return toll

        for neighbor, weight in graph[town]:
            if neighbor not in visited:
                new_toll = toll + weight
                if new_toll < min_toll[neighbor]:
                    min_toll[neighbor] = new_toll
                    heapq.heappush(min_heap, (new_toll, neighbor))

    return -1

