def max_participants_present(test_cases):
    results = []
    for n, intervals in test_cases:
        times = []
        for start, end in intervals:
            times.append((start, 1))  # Participant joins
            times.append((end + 1, -1))  # Participant leaves

        times.sort()

        current_participants = 0
        max_participants = 0

        for time, change in times:
            current_participants += change
            if current_participants > max_participants:
                max_participants = current_participants

        results.append(max_participants)
    return results

