    Returns the total number of fluctuations in the sequence of steps.
    """
    if not steps:
        return 0

    fluctuations = 0
    for i in range(1, len(steps)):
        if (steps[i-1] > 0 and steps[i] <= 0) or (steps[i-1] < 0 and steps[i] >= 0) or (steps[i-1] == 0 and steps[i] != 0):
