    """
    Determine if it's possible to partition each sequence according to the problem statement.
    """
    results = []

    for t in range(T):
        N, K = test_cases[t][0]
        sequence = test_cases[t][1]

        if K == N:
            results.append("YES")
        else:
            # For each possible partition, we need to check the sums of max and min in subarrays
            unique_sums = set()
            for i in range(N):
                subarray_sum = sequence[i] * 2
                unique_sums.add(subarray_sum)

            if len(unique_sums) <= K:
                results.append("YES")
            else:
                results.append("NO")

    return results

