            pos = int(op[2])
            document.insert(pos, char)
            stack.append(("insert", char, pos))
        elif op[0] == "remove":
            pos = int(op[1])
            char = document.pop(pos)
            stack.append(("remove", char, pos))
        elif op[0] == "undo":
            if stack:
