def make_diverse(s):
    """
    Converts the input string into a diverse string where no characters appear
    more than once consecutively by inserting the minimum number of characters.

    :param s: Input string of lowercase letters
    :return: A diverse string
    """
    if not s:
        return ""

    result = [s[0]]
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            alternative_char = 'a'
            while alternative_char == s[i] or (result and alternative_char == result[-1]):
                alternative_char = chr(ord(alternative_char) + 1)
            result.append(alternative_char)
        result.append(s[i])

    return ''.join(result)

