def min_swaps_to_maximize_interesting_subsequences(n, volumes, status):
    filled = [(volumes[i], i) for i in range(n) if status[i] == 'F']
    if len(filled) < 2:
        return 0

    filled.sort()
    swaps = 0
    last_index = filled[0][1]

    for i in range(1, len(filled)):
        if filled[i][1] < last_index:
            swaps += 1
        last_index = max(last_index, filled[i][1])

    return swaps

def count_unique_pairs(nums, target):
    """
    Returns the number of unique pairs (a, b) in the array such that a + b == target.
    """
    nums_sorted = sorted(nums)
    seen = set()
    unique_pairs = set()

    for num in nums_sorted:
        complement = target - num
        if complement in seen:
            unique_pairs.add((min(num, complement), max(num, complement)))
        seen.add(num)

    return len(unique_pairs)

