def min_trucks_required(routes):
    # First, sort the routes by their start time
    routes.sort(key=lambda x: x[0])

    # Use a heap to keep track of end times of trucks' current routes
    import heapq
    heap = []

    for route in routes:
        start, end = route

        # If heap is not empty and the earliest ending route ends before the current route starts
        if heap and heap[0] <= start:
            heapq.heapreplace(heap, end)
        else:
            heapq.heappush(heap, end)

    # The number of trucks needed is the size of the heap
    return len(heap)

