from typing import List

def find_triplet(nums: List[int], S: int) -> bool:
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == S:
                return True
            elif current_sum < S:
                left += 1
            else:
                right -= 1

    return False

