from collections import Counter

def arrange_students(n, heights):
    counter = Counter(heights)

    max_height = max(counter.values())
    if max_height > (n + 1) // 2:
        return "NO"

    sorted_heights = sorted(counter.items(), key=lambda x: -x[1])
    result = [0] * n
    index = 0

    for height, count in sorted_heights:
        for _ in range(count):
            result[index] = height
            index += 2
            if index >= n:
                index = 1

    return result

