    Returns the number of subarrays whose sum equals k modulo 10^9 + 7.
    """
    MOD = 10**9 + 7
    sum_count = {0: 1}
    current_sum = 0
    result = 0

    for num in nums:
        current_sum += num
        if current_sum - k in sum_count:
            result += sum_count[current_sum - k]
        if current_sum in sum_count:
            sum_count[current_sum] += 1
        else:
            sum_count[current_sum] = 1

    return result % MOD

