def countPeaks(arr):
    """
    Returns the count of peak skyscrapers in the given array.
    A skyscraper is considered a peak if it is greater than both its neighbors.
    """
    count = 0
    for i in range(1, len(arr) - 1):
        if arr[i] > arr[i - 1] and arr[i] > arr[i + 1]:
            count += 1
    return count

