    if not s:
        return ""

    encoded_str = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            encoded_str.append(s[i - 1] + str(count))
            count = 1

    encoded_str.append(s[-1] + str(count)) # Add the last run

    return "".join(encoded_str)

