def longest_double_subsequence(arr):
    """
    Function to find the length of the longest subsequence where 
    each element is at least double its predecessor.
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n  # Initialize dp array with 1, as a single element is a valid subsequence

    for i in range(1, n):
        for j in range(i):
            if arr[i] >= 2 * arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

