def find_longest_unique_substring(s: str) -> (int, str):
    """
    Finds the length of the longest substring without repeating characters and the substring itself.

    Parameters:
    s (str): The input string

    Returns:
    Tuple: A tuple containing the length of the longest substring and the substring itself
    """
    if not s:
        return (0, "")

    char_map = {}
    start = 0
    max_length = 0
    longest_substr = ""

    for end in range(len(s)):
        if s[end] in char_map:
            # Update start to max of the current start or the next index to the previous occurrence
            # to ensure the substring remains unique.
            start = max(start, char_map[s[end]] + 1)

        char_map[s[end]] = end
        current_length = end - start + 1

        if current_length > max_length:
            max_length = current_length
            longest_substr = s[start:end+1]

    return (max_length, longest_substr)

