def zigzag_array(n, arr):
    """
    Rearranges the array such that it forms a zigzag sequence.

    Parameters:
    n (int): Number of elements in the array
    arr (list of int): The array of elements

    Returns:
    list of int: The array rearranged in zigzag sequence
    """
    for i in range(1, n, 2):
        if i+1 < n:
            if arr[i-1] > arr[i]:
                arr[i-1], arr[i] = arr[i], arr[i-1]
            if arr[i] < arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]
        else: # when i+1 == n and it's the last element
            if arr[i-1] > arr[i]:
                arr[i-1], arr[i] = arr[i], arr[i-1]

    return arr

