def longest_balanced_substring(S):
    """
    Returns the length of the longest balanced substring (with equal number of 'a' and 'b') in the given string S.
    """
    max_length = 0
    n = len(S)

    # Iterate through all possible starting points of substrings
    for i in range(n):
        count_a = 0
        count_b = 0

        # Iterate through the substring starting from i to the end of the string
        for j in range(i, n):
            if S[j] == 'a':
                count_a += 1
            else:
                count_b += 1

            # If counts are equal, we have a balanced substring
            if count_a == count_b:
                max_length = max(max_length, j - i + 1)

    return max_length

def calculate_combination(n: int, r: int) -> int:
    if r > n:
        return 0

    # Memoization table
    memo = [[0 for _ in range(r+1)] for _ in range(n+1)]

    # Bottom up dp approach to fill this table
    for i in range(n+1):
        for k in range(min(i, r)+1):
            if k == 0 or k == i:
                memo[i][k] = 1
            else:
                memo[i][k] = memo[i-1][k-1] + memo[i-1][k]

    return memo[n][r]

