def find_triplet(n, arr, x):
    """
    Returns True if there exist three distinct indices i, j, and k such that arr[i] + arr[j] + arr[k] = x, otherwise False.
    """
    arr.sort()
    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == x:
                return True
            elif current_sum < x:
                left += 1
            else:
                right -= 1
    return False

