def subset_sum(n, S, arr):
    """
    Returns "YES" if there exists a subset of the array with sum equal to S,
    otherwise returns "NO".
    """
    dp = [False] * (S + 1)
    dp[0] = True

    for num in arr:
        for i in range(S, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return "YES" if dp[S] else "NO"

