def three_sum(nums, target):
    """
    Given a list of integers and a target integer, finds all unique triplets in the list
    that sum up to the target. Each triplet is sorted in a non-decreasing order.
    """
    nums.sort()
    result = []
    n = len(nums)

    for i in range(n):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # Skip same results
        left, right = i + 1, n - 1
        while left < right:
            sum_value = nums[i] + nums[left] + nums[right]
            if sum_value == target:
                result.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif sum_value < target:
                left += 1
            else:
                right -= 1

    return result

