import math
from typing import Union

def pythagoras(opposite: Union[float, str], adjacent: Union[float, str], hypotenuse: Union[float, str]) -> str:
    """
    Computes the length of the unknown side of a right-angled triangle using the Pythagorean theorem.

    Parameters:
    - opposite: length of the opposite side or "?" if unknown
    - adjacent: length of the adjacent side or "?" if unknown
    - hypotenuse: length of the hypotenuse or "?" if unknown

    Returns:
    - A string indicating the name and length of the unknown side.
    - If no side is unknown, returns "You already know the answer!".
    - Raises ValueError for invalid inputs.
    """

    if isinstance(opposite, str) and opposite == "?":
        if isinstance(adjacent, (int, float)) and isinstance(hypotenuse, (int, float)):
            if hypotenuse <= adjacent:
                raise ValueError("Hypotenuse must be greater than either side in a right-angled triangle.")
            opposite_value = math.sqrt(hypotenuse**2 - adjacent**2)
            return f"Opposite = {opposite_value}"

    elif isinstance(adjacent, str) and adjacent == "?":
        if isinstance(opposite, (int, float)) and isinstance(hypotenuse, (int, float)):
            if hypotenuse <= opposite:
                raise ValueError("Hypotenuse must be greater than either side in a right-angled triangle.")
            adjacent_value = math.sqrt(hypotenuse**2 - opposite**2)
            return f"Adjacent = {adjacent_value}"

    elif isinstance(hypotenuse, str) and hypotenuse == "?":
        if isinstance(opposite, (int, float)) and isinstance(adjacent, (int, float)):
            hypotenuse_value = math.sqrt(opposite**2 + adjacent**2)
            return f"Hypotenuse = {hypotenuse_value}"

    elif isinstance(opposite, (int, float)) and isinstance(adjacent, (int, float)) and isinstance(hypotenuse, (int, float)):
        if math.isclose(hypotenuse**2, opposite**2 + adjacent**2):
            return "You already know the answer!"
        else:
            raise ValueError("The provided sides do not form a right-angled triangle.")

    raise ValueError("Invalid input. Only one side can be unknown, and sides must be positive numbers.")

