def island_perimeter(grid):
    """
    Calculate the perimeter of the island in the given grid.

    :param grid: List[List[int]]: 2D grid representing the island, where 1 is land and 0 is water.
    :return: int: the perimeter of the island.
    """
    m, n = len(grid), len(grid[0])
    perimeter = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                # add 4 for the current land cell
                perimeter += 4
                # subtract 2 for each adjacent land cell (below and to the right)
                if i > 0 and grid[i-1][j] == 1:
                    perimeter -= 2
                if j > 0 and grid[i][j-1] == 1:
                    perimeter -= 2

    return perimeter

