        total_sum = sum(tasks)  # Total sum of all difficulties
        target = total_sum // 2  # Target sum for a person (we want to distribute as evenly as possible)

        dp = [False] * (target + 1)  # DP array to store which sums are possible
        dp[0] = True

        for task in tasks:
