def min_words_to_form_target(words, target):
    """
    Returns the minimum number of words that concatenate to form the target string.
    If it's impossible to form the target, returns -1.
    """
    from collections import deque

    # Initialize the queue with a starting point (current string, number of words used)
    queue = deque([(target, 0)])
    visited = set([target])

    while queue:
        current, steps = queue.popleft()

        if current == "":
            return steps

        for word in words:
            if current.startswith(word):
                new_target = current[len(word):]
                if new_target not in visited:
                    visited.add(new_target)
                    queue.append((new_target, steps + 1))

    return -1

