def longest_unique_substring(s: str) -> str:
    """
    This function returns the longest substring with unique characters from the given string s.
    """
    start = 0
    max_length = 0
    max_substr_start = 0
    seen = {}

    for i in range(len(s)):
        if s[i] in seen and seen[s[i]] >= start:
            start = seen[s[i]] + 1
        seen[s[i]] = i
        if i - start + 1 > max_length:
            max_length = i - start + 1
            max_substr_start = start

    return s[max_substr_start:max_substr_start + max_length]

