def caesar_cipher(s, k):
    """
    Encrypts the string `s` using a Caesar cipher with a shift of `k` positions.

    :param s: str : the string to be encrypted.
    :param k: int : the number of positions to shift.
    :return: str : the encrypted string.
    """
    encrypted = []
    k = k % 26  # handle large values of k by reducing it within the range of alphabet

    for char in s:
        if 'a' <= char <= 'z':
            # Rotate within the range of a-z
            encrypted.append(chr((ord(char) - ord('a') + k) % 26 + ord('a')))
        elif 'A' <= char <= 'Z':
            # Rotate within the range of A-Z
            encrypted.append(chr((ord(char) - ord('A') + k) % 26 + ord('A')))
        else:
            # Non-alphabetical characters remain unchanged
            encrypted.append(char)

    return ''.join(encrypted)

