    current_sum = 0
    for end in range(n):
        current_sum += arr[end]
        while current_sum > S and start <= end:
            current_sum -= arr[start]
            start += 1
        if current_sum == S:
            return start + 1, end + 1  # Converting to 1-based index
    return -1

