from typing import List

def delimited_frequency_filter(arr: List[int], N: int) -> List[int]:
    """
    Returns a new List where each number in the input List `arr` appears at most `N` times,
    maintaining the original order.
    """
    count = {}
    result = []

    for num in arr:
        if count.get(num, 0) < N:
            result.append(num)
            count[num] = count.get(num, 0) + 1

    return result

