def length_of_LIS(sequence):
    """
    Returns the length of the longest increasing subsequence in the given sequence.
    :param sequence: List of integers representing the yields.
    :return: An integer representing the length of the longest increasing subsequence.
    """
    if not sequence:
        return 0

    from bisect import bisect_left

    lis = []

    for yield_value in sequence:
        pos = bisect_left(lis, yield_value)
        if pos == len(lis):
            lis.append(yield_value)
        else:
            lis[pos] = yield_value

    return len(lis)

