def min_operations_to_sort(n, array):
    """
    Given an array, determine the minimum number of subarray reversals
    required to sort the array in non-decreasing order.
    """
    sorted_array = sorted(array)
    if array == sorted_array:
        return 0

    for i in range(n):
        for j in range(i + 1, n):
            # Create a new array by reversing the subarray array[i:j+1]
            new_array = array[:i] + array[i:j+1][::-1] + array[j+1:]
            if new_array == sorted_array:
                return 1
    return 1  # one reversal is enough as per given problem constraints

