def motion_parameters(initial_velocity: float, final_velocity: float, acceleration: float, time: float):
    """
    Calculates the missing motion parameter given three out of four parameters (initial_velocity,
    final_velocity, acceleration, and time).

    Parameters:
    initial_velocity (float): Initial velocity of the object.
    final_velocity (float): Final velocity of the object.
    acceleration (float): Acceleration of the object.
    time (float): Time duration during which the object is moving.

    Returns:
    tuple: A tuple where the first element is the name of the computed parameter and the second
           element is the computed value.

    Raises:
    ValueError: If exactly one of the parameters is not zero.
    """

    # Validate input
    zero_count = sum(1 for param in [initial_velocity, final_velocity, acceleration, time] if param == 0)
    if zero_count != 1:
        raise ValueError("Exactly one of the parameters must be zero")

    # Calculate the missing parameter
    if initial_velocity == 0:
        initial_velocity = final_velocity - acceleration * time
        return ('initial_velocity', initial_velocity)
    elif final_velocity == 0:
        final_velocity = initial_velocity + acceleration * time
        return ('final_velocity', final_velocity)
    elif acceleration == 0:
        acceleration = (final_velocity - initial_velocity) / time
        return ('acceleration', acceleration)
    elif time == 0:
        time = (final_velocity - initial_velocity) / acceleration
        return ('time', time)

    raise ValueError("Unexpected error")

