def find_increasing_subsequence(n, heights):
    """
    Finds a strictly increasing subsequence of length 3 or more in the list of heights.
    Returns the subsequence if found, otherwise returns "No such subsequence".
    """
    if n < 3:
        return "No such subsequence"

    # To track the subsequence
    subsequence = []

    for height in heights:
        if not subsequence or height > subsequence[-1]:
            subsequence.append(height)
        else:
            # Try to replace to maintain the smallest possible values
            for idx in range(len(subsequence)):
                if height <= subsequence[idx]:
                    subsequence[idx] = height
                    break

        if len(subsequence) >= 3:
            return subsequence[:3]

    return "No such subsequence"

# Example usage:
# n = 6
# heights = [5, 1, 5, 2, 3, 6]
# print(find_increasing_subsequence(n, heights)) # Output: [1, 2, 3]

