def replaceQuestionMarks(S):
    """
    Replace every occurrence of '?' with any lowercase English letter such that the resultant
    string does not contain any consecutive identical characters.
    """
    n = len(S)
    if n == 0:
        return ""

    res = list(S)
    for i in range(n):
        if res[i] == '?':
            for c in 'abc':  # Choose from 'a', 'b', 'c' to ensure no consecutive chars are the same.
                if (i > 0 and res[i - 1] == c) or (i < n - 1 and res[i + 1] == c):
                    continue
                res[i] = c
                break
    return ''.join(res)

