def process_queries(n, q, array, queries):
    # This function processes a list of queries and modifies/queries the array accordingly.
    results = []
    for query in queries:
        if query[0] == 1:
            # Type 1 query: Add X to the subarray A[L]...A[R]
            L, R, X = query[1] - 1, query[2] - 1, query[3]
            for i in range(L, R + 1):
                array[i] += X
        elif query[0] == 2:
            # Type 2 query: Compute the sum of the subarray A[L]...A[R]
            L, R = query[1] - 1, query[2] - 1
            results.append(sum(array[L:R + 1]))
    return results

