def compress_string(s: str) -> str:
    if not s:
        return s

    compressed = []
    count = 1
    prev_char = s[0]

    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            compressed.append(f"{prev_char}{count}")
            prev_char = char
            count = 1

    compressed.append(f"{prev_char}{count}")
    compressed_string = "".join(compressed)

    return compressed_string if len(compressed_string) < len(s) else s

