def max_staircase_students(heights):
    """
    Returns the maximum number of students that can form a "staircase".
    A "staircase" means every next student is taller than the previous one.

    :param heights: List[int] - List of students' heights.
    :return: int - Maximum number of students to form a "staircase".
    """
    if not heights:
        return 0

    n = len(heights)
    dp = [1] * n  # dp[i] will be the length of staircase ending with heights[i]

    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

