from collections import deque

def min_time_to_infect(grid):
    """
    Returns the minimum number of units of time required to infect all cells in the grid.
    If it is impossible to infect all cells, return -1.
    """
    if not grid or not grid[0]:
        return -1

    rows, cols = len(grid), len(grid[0])
    queue = deque()
    total_cells = rows * cols
    infected_count = 0

    # Find all initially infected cells and count them
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                queue.append((r, c))
                infected_count += 1

    if infected_count == total_cells:
        return 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    time_units = 0

    # BFS to spread infection
    while queue:
        for _ in range(len(queue)):
            r, c = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                    grid[nr][nc] = 1
                    queue.append((nr, nc))
                    infected_count += 1

        if queue:
            time_units += 1

    return time_units if infected_count == total_cells else -1

