def make_persistent(s):
    """
    Transforms the given string into a persistent string by removing consecutive 
    duplicate letters until no more consecutive duplicates can be found.

    Parameters:
    s (str): The input string consisting of lowercase English letters.

    Returns:
    str: The persistent string derived from the input string.
    """
    if not s:
        return ""

    result = []
    for char in s:
        if not result or result[-1] != char:
            result.append(char)
    return ''.join(result)

def uniquePaths(grid):
    """
    Returns the number of unique paths from the top-left to bottom-right corner of a 2D grid,
    avoiding blocked cells.
    """
    m = len(grid)
    n = len(grid[0])
    MOD = 1000000007

    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] = (dp[i][j] + dp[i-1][j]) % MOD
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD

    return dp[m-1][n-1]

