    """
    Returns a tuple of two distinct elements from the array whose sum is equal to k.
    If no such pair exists, returns None.
    """
    seen = {}

    for num in arr:
        complement = k - num

        if complement in seen:
            return (complement, num)

        if num in seen:
            seen[num] += 1
        else:
            seen[num] = 1

    return None

