from collections import deque

def min_steps_to_exit(n, m, grid):
    """
    This function finds the minimum number of steps required for the robot to reach the exit cell from the start cell in a n x m grid.
    If it is not possible to reach the exit, it returns -1.
    """
    # Find the starting and ending positions
    start = end = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            if grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS initialization
    queue = deque([(start[0], start[1], 0)])
    visited = set()
    visited.add(start)

    while queue:
        x, y, steps = queue.popleft()

        # If we reached the end cell
        if (x, y) == end:
            return steps

        # Explore all 4 directions
        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            # Check if the new position is within the grid and not blocked or visited
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '#' and (nx, ny) not in visited:
                queue.append((nx, ny, steps + 1))
                visited.add((nx, ny))

    # If we exhaust the queue without finding the end
    return -1

