    valleys = []

    for i in range(n):
        if i == 0:
            if heights[i] > heights[i + 1]:
                valleys.append(i + 1)
        elif i == n - 1:
            if heights[i] > heights[i - 1]:
                valleys.append(i + 1)
        else:
            if heights[i] > heights[i - 1] and heights[i] > heights[i + 1]:
                valleys.append(i + 1)

    if not valleys:
        return [-1]

    return valleys

