def maximize_element(matrix, n, k):
    """
    Maximize the value of the element at position (1, 1) after increasing 
    each element in a k x k sub-matrix by 1 exactly once.
    """
    max_value = matrix[0][0]
    for i in range(n - k + 1):
        for j in range(n - k + 1):
            new_value = matrix[0][0]
            if 0 <= i <= k-1 and 0 <= j <= k-1:
                new_value += 1
            max_value = max(max_value, new_value)
    return max_value

