def can_swap_to_equal(A, B):
    """
    Determines if string A can be made equal to string B by swapping at most one pair of characters in A.
    """
    if A == B:
        return "Yes"

    diff = [(a, b) for a, b in zip(A, B) if a != b]

    if len(diff) != 2:
        return "No"

    (a1, b1), (a2, b2) = diff
    if a1 == b2 and b1 == a2:
        return "Yes"

    return "No"

