    dp[0], dp[1] = 1, 1  # base initialization

    for i in range(2, n + 1):
        if encoded_message[i-1] != '0':
            dp[i] += dp[i-1]
        if encoded_message[i-2] == '1' or (encoded_message[i-2] == '2' and encoded_message[i-1] in '0123456'):
            dp[i] += dp[i-2]

    return dp[n]

