from collections import Counter
from heapq import heappop, heappush

def rearrange_string(S, K):
    if K == 0:
        return S  # No need to rearrange if K is 0

    counter = Counter(S)
    max_heap = []
    for char, freq in counter.items():
        heappush(max_heap, (-freq, char))

    wait_queue = []
    result = []
    while max_heap:
        freq, char = heappop(max_heap)
        result.append(char)
        wait_queue.append((freq + 1, char))  # Decrement frequency (stored as negative)

        if len(wait_queue) >= K:
            freq, char = wait_queue.pop(0)
            if -freq > 0:
                heappush(max_heap, (freq, char))

    return ''.join(result) if len(result) == len(S) else ""

