def schedule_robots(N, M, preferences):
    # Create an array to store the time slot assignment for each robot
    slots = [-1] * N

    # Create a dictionary to store the assigned slots for each station
    station_schedule = {i: [] for i in range(M)}

    for i in range(N):
        assigned = False
        for station in preferences[i]:
            potential_slot = len(station_schedule[station]) + 1
            conflicting_robot = next((r for r in station_schedule[station] if slots[r] == potential_slot), None)
            if conflicting_robot is None:
                slots[i] = potential_slot
                station_schedule[station].append(i)
                assigned = True
                break

        if not assigned:
            # Additional logic if no valid slot found (minimum slots approach can be made better)
            slot = 1
            while slot in (slots[r] for r in station_schedule[preferences[i][0]]):
                slot += 1
            slots[i] = slot
            station_schedule[preferences[i][0]].append(i)

    return slots

