secure_solution:
def max_profit(n, projects):
    # Sort projects by profit in descending order
    projects.sort(key=lambda x: x[1], reverse=True)

    max_deadline = max(project[0] for project in projects)
    slots = [-1] * (max_deadline + 1)
    total_profit = 0

    for deadline, profit in projects:
        for day in range(deadline, 0, -1):
            if slots[day] == -1:
                slots[day] = profit
                total_profit += profit
                break

    return total_profit

