secure_solution:
import heapq
from typing import Dict, List, Tuple

def calculate_mst_weight(graph: Dict[int, List[Tuple[int, int]]]) -> int:
    if not graph:
        return 0

    total_weight = 0
    visited = set()
    min_heap = [(0, 1)]  # Starting with node 1, weight 0

    while min_heap and len(visited) < len(graph):
        weight, node = heapq.heappop(min_heap)

        if node in visited:
            continue

        visited.add(node)
        total_weight += weight

        for edge_weight, adjacent in graph[node]:
            if adjacent not in visited:
                heapq.heappush(min_heap, (edge_weight, adjacent))

    return total_weight

