def rob(nums):
    """
    Function to determine the maximum amount of money that can be robbed without robbing two adjacent houses.
    :param nums: List of non-negative integers representing the amounts of money at each house.
    :return: Maximum amount of money that can be robbed.
    """
    if not nums:
        return 0
    if len(nums) <= 2:
        return max(nums)

    dp = [0] * len(nums)
    dp[0] = nums[0]
    dp[1] = max(nums[0], nums[1])

    for i in range(2, len(nums)):
        dp[i] = max(dp[i-1], nums[i] + dp[i-2])

    return dp[-1]

