from collections import deque

def word_ladder_length(start: str, end: str, word_dict: set) -> int:
    if end not in word_dict:
        return -1

    word_dict.add(end)
    queue = deque([(start, 1)])
    alphabet = 'abcdefghijklmnopqrstuvwxyz'

    while queue:
        current_word, steps = queue.popleft()

        if current_word == end:
            return steps

        for i in range(len(current_word)):
            prefix, suffix = current_word[:i], current_word[i+1:]
            for char in alphabet:
                if char != current_word[i]:
                    next_word = prefix + char + suffix
                    if next_word in word_dict:
                        queue.append((next_word, steps + 1))
                        word_dict.remove(next_word)

    return -1

