def can_form_arithmetic_progression(n, k, sequence):
    sequence.sort()
    for i in range(n - k + 1):
        possible = True
        d = sequence[i+1] - sequence[i]
        for j in range(2, k):
            if sequence[i+j] - sequence[i+j-1] != d:
                possible = False
                break
        if possible:
            return "YES"
    return "NO"

