    """
    Returns the number of continuous subarrays whose sum equals to the target.
    """
    total_count = 0
    prefix_sum = 0
    prefix_sum_counts = {0: 1}

    for num in nums:
        prefix_sum += num
        if prefix_sum - target in prefix_sum_counts:
            total_count += prefix_sum_counts[prefix_sum - target]
