def tic_tac_toe(moves):
    """
    Determines the result of a tic-tac-toe game based on a list of moves.

    :param moves: List of tuples representing the moves in the form (row, col, player).
                  Player is either 'X' or 'O'.
    :return: String representing the result of the game: 'X wins', 'O wins', or 'Draw'.
    """
    # Initialize a 3x3 game grid
    grid = [['' for _ in range(3)] for _ in range(3)]

    # Apply the moves to the grid
    for row, col, player in moves:
        grid[row][col] = player

    # Check all rows, columns, and two diagonals for a winner
    for player in ['X', 'O']:
        # Check rows
        for row in range(3):
            if grid[row][0] == grid[row][1] == grid[row][2] == player:
                return f"{player} wins"

        # Check columns
        for col in range(3):
            if grid[0][col] == grid[1][col] == grid[2][col] == player:
                return f"{player} wins"

        # Check diagonals
        if grid[0][0] == grid[1][1] == grid[2][2] == player:
            return f"{player} wins"
        if grid[0][2] == grid[1][1] == grid[2][0] == player:
            return f"{player} wins"

    # If no winner, check if the grid is full for a draw
    for row in grid:
        if '' in row:
            return "Draw"  # This line can also return 'None' until the game is meant to be complete
                          # if you want to enforce the requirement of 5-9 moves.
    return "Draw"

