def days_until_more_rainfall(n, rainfall):
    result = [0] * n
    stack = []

    for i in range(n):
        while stack and rainfall[i] > rainfall[stack[-1]]:
            prev_index = stack.pop()
            result[prev_index] = i - prev_index
        stack.append(i)

    return result

def find_subarray_with_sum(arr, x):
    """
    Finds a contiguous subarray with sum exactly x.

    Parameters:
    arr (list of int): List of integers representing the array.
    x (int): The target sum.

    Returns:
    tuple: A tuple containing the 1-based start and end indices of the subarray if found, else -1.
    """
    current_sum = 0
    start = 0
    sum_map = {}

    for end in range(len(arr)):
        current_sum += arr[end]

        if current_sum == x:
            return (start + 1, end + 1)

        if (current_sum - x) in sum_map:
            return (sum_map[current_sum - x] + 2, end + 1)

        sum_map[current_sum] = end

    return -1

