from itertools import combinations

def find_combination(n, t, arr):
    """
    Determine if there exists a combination of numbers in the list such that their sum equals the target sum.
    If such a combination exists, return the combination, otherwise return an empty list.

    :param n: Number of elements in the list
    :param t: Target sum
    :param arr: List of integers
    :return: List of integers that sum up to t if such a combination exists, otherwise an empty list
    """
    for i in range(1, n+1):
        for combo in combinations(arr, i):
            if sum(combo) == t:
                return sorted(combo)
    return []

