from itertools import combinations

def is_subset_sum_possible(n, m, k, arr):
    """
    Determine if there exists a subset of the array that has exactly k elements
    that add up to m. If such a subset exists, returns "POSSIBLE", otherwise "IMPOSSIBLE".
    """
    for subset in combinations(arr, k):
        if sum(subset) == m:
            return "POSSIBLE"
    return "IMPOSSIBLE"

