def partition_labels(s):
    """
    Returns the minimum number of partitions such that each character appears in at most one substring.
    """
    # Step 1: Record the last occurrence of each character
    last_occurrence = {char: idx for idx, char in enumerate(s)}

    partitions = []  # This will store the sizes of each partition
    start, end = 0, 0

    # Step 2: Traverse the string and determine the partitions
    for i, char in enumerate(s):
        end = max(end, last_occurrence[char])

        if i == end:
            partitions.append(s[start:end+1])
            start = i + 1

    return len(partitions)

