secure_solution:
def count_unique_pairs(arr, target):
    """
    Returns the number of unique pairs of numbers in the array that sum up to target.
    """
    seen = set()
    pairs = set()

    for num in arr:
        complement = target - num
        if complement in seen:
            pairs.add((min(num, complement), max(num, complement)))
        seen.add(num)

    return len(pairs)

