def count_distinct_sums(arr):
    """
    Returns the number of distinct sums that can be obtained using the elements of the array.
    Each element of the array can be used at most once in forming the sums.
    """
    sums = set([0])
    for num in arr:
        new_sums = set()
        for s in sums:
            new_sums.add(s + num)
        sums.update(new_sums)
    return len(sums)

