secure_solution:
def longest_even_sum_subarray(arr):
    """
    Returns the length of the longest subarray with an even sum.
    """
    total_sum = sum(arr)

    # If the total sum of the array is even, the whole array is valid.
    if total_sum % 2 == 0:
        return len(arr)

    # Find the minimum index removing which makes the total sum even
    for i in range(len(arr)):
        if arr[i] % 2 != 0:
            break

    for j in range(len(arr) - 1, -1, -1):
        if arr[j] % 2 != 0:
            break

    return len(arr) - min(i + 1, len(arr) - j)

