from typing import List, Tuple

def crout_matrix_decomposition(A: List[List[float]]) -> Tuple[List[List[float]], List[List[float]]]:
    n = len(A)
    L = [[0.0]*n for _ in range(n)]
    U = [[0.0]*n for _ in range(n)]

    for j in range(n):
        U[j][j] = 1.0
        for i in range(j, n):
            sum_l = sum(L[i][k] * U[k][j] for k in range(j))
            L[i][j] = A[i][j] - sum_l

        for i in range(j+1, n):
            sum_u = sum(L[j][k] * U[k][i] for k in range(j))
            if L[j][j] == 0:
                raise ZeroDivisionError("Matrix is singular, cannot perform decomposition.")
            U[j][i] = (A[j][i] - sum_u) / L[j][j]

    return L, U

from collections import deque, defaultdict

def num_buses_to_destination(start, destination, routes):
    if start == destination:
        return 0

    stop_to_routes = defaultdict(set)
    for i, route in enumerate(routes):
        for stop in route:
            stop_to_routes[stop].add(i)

    visited_stops = set()
    visited_routes = set()
    queue = deque([(start, 0)])

    while queue:
        current_stop, buses_taken = queue.popleft()

        if current_stop in visited_stops:
            continue

        visited_stops.add(current_stop)

        for route in stop_to_routes[current_stop]:
            if route in visited_routes:
                continue

            visited_routes.add(route)

            for stop in routes[route]:
                if stop == destination:
                    return buses_taken + 1
                queue.append((stop, buses_taken + 1))

    return -1

