def min_additional_braces(s):
    """
    Determines the minimum number of additional curly braces required to make the text valid and non-overlapping.

    Parameters:
    s (str): The input string containing curly braces and other characters.

    Returns:
    int: Minimum number of additional curly braces needed.
    """
    open_braces = 0
    close_braces = 0

    for char in s:
        if char == '{':
            open_braces += 1
        elif char == '}':
            if open_braces > 0:
                open_braces -= 1
            else:
                close_braces += 1

    return open_braces + close_braces

