def max_number_of_pairs(nums, target):
    """
    Returns the maximum number of pairs in the array nums that sum up to target.
    Each pair should be composed of two distinct indices.
    """
    counts = {}
    pairs = 0

    for num in nums:
        complement = target - num
        if counts.get(complement, 0) > 0:
            pairs += 1
            counts[complement] -= 1
        else:
            counts[num] = counts.get(num, 0) + 1

    return pairs

