from typing import List

def custom_cycle_sort(arr: List[int]) -> List[int]:
    n = len(arr)

    # Traverse the array to find cycles
    for start in range(n - 1):
        item = arr[start]

        # Find where to put the current item
        pos = start
        for i in range(start + 1, n):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position, continue
        if pos == start:
            continue

        # Otherwise, put the item to the correct position (skip duplicates)
        while item == arr[pos]:
            pos += 1

        arr[pos], item = item, arr[pos]

        # Rotate rest of the cycle
        while pos != start:
            pos = start
            for i in range(start + 1, n):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            arr[pos], item = item, arr[pos]

    return arr

