from typing import List

def highlight_symbols(words: List[str], symbols: List[str]) -> List[str]:
    # Sort symbols by their length in descending order.
    symbols = sorted(symbols, key=len, reverse=True)

    result = []

    for word in words:
        matched_symbol = None

        for symbol in symbols:
            if symbol in word:
                matched_symbol = symbol
                break

        if matched_symbol:
            word = word.replace(matched_symbol, f'[{matched_symbol}]', 1)

        result.append(word)

    return result

