def three_sum(nums, target):
    """
    Given an array of integers and a target integer, determine if there
    are three distinct indices such that the sum of the elements at these indices equals the target.
    """
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            sum_ = nums[i] + nums[left] + nums[right]
            if sum_ == target:
                return True
            elif sum_ < target:
                left += 1
            else:
                right -= 1
    return False

