def min_subset_difference(n, sweetness_levels):
    total_sum = sum(sweetness_levels)
    half_sum = total_sum // 2
    dp = [0] * (half_sum + 1)

    for sweetness in sweetness_levels:
        for i in range(half_sum, sweetness - 1, -1):
            dp[i] = max(dp[i], dp[i - sweetness] + sweetness)

    subset1_sum = dp[half_sum]
    subset2_sum = total_sum - subset1_sum
    return abs(subset2_sum - subset1_sum)

