from typing import List

def min_jumps_to_end(arr: List[int]) -> int:
    """
    Finds the minimum number of jumps required to reach the end of the array.
    """
    if len(arr) <= 1:
        return 0

    if arr[0] == 0:
        return -1

    jumps = 0
    max_reach = 0
    steps = 0

    for i in range(len(arr)):
        max_reach = max(max_reach, i + arr[i])

        if i == steps:
            jumps += 1
            steps = max_reach

        if steps >= len(arr) - 1:
            return jumps

    return -1 # if we never reach the end of the array

