def longest_increasing_subarray_length(nums):
    """
    Returns the length of the longest strictly increasing subarray in a given list of integers.
    """
    if not nums:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

