def most_frequent_character(s):
    """
    Determine the most frequent character in the string `s`.
    In case of a tie, return the alphabetically first character.
    """
    if not s:
        return ''

    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    max_frequency = max(char_count.values())
    most_frequent_chars = [char for char, count in char_count.items() if count == max_frequency]

    return min(most_frequent_chars)

