from collections import Counter

def second_most_frequent_quantity(quantities):
    """
    Returns the second most frequent quantity in the list.
    If there is no second most frequent quantity, returns None.
    """
    if len(set(quantities)) < 2:
        return None

    frequency_counter = Counter(quantities)
    most_common_quantities = frequency_counter.most_common()

    if len(most_common_quantities) < 2:
        return None

    return most_common_quantities[1][0]  # Second element in the most_common list (the quantity itself)

