def process_operations(n, operations):
    stack = []
    result = []

    for operation in operations:
        if operation.startswith('push'):
            _, x = operation.split()
            stack.append(int(x))
        elif operation == 'pop':
            if stack:
                stack.pop()
        elif operation.startswith('inc'):
            _, x, y = operation.split()
            for i in range(min(int(x), len(stack))):
                stack[i] += int(y)

        if stack:
            result.append(stack[-1])
        else:
            result.append("EMPTY")

    return result

