def max_satisfied_requests(m, books, n, requests):
    from collections import defaultdict

    book_count = defaultdict(int)
    for book, count in books:
        book_count[book] += count

    satisfied_requests = 0

    for request in requests:
        temp_count = book_count.copy()
        can_fulfill = True

        for book in request:
            if temp_count[book] > 0:
                temp_count[book] -= 1
            else:
                can_fulfill = False
                break

        if can_fulfill:
            satisfied_requests += 1
            book_count = temp_count

    return satisfied_requests

# Example Usage
# m = 3, books = [('book1', 2), ('book2', 1), ('book3', 5)], n = 4, 
# requests = [['book1', 'book2'], ['book1', 'book3', 'book2'], ['book3'], ['book1', 'book3']]
