    Returns the length of the longest common substring between s1 and s2.
    """
    if not s1 or not s2:
        return 0

    len_s1 = len(s1)
    len_s2 = len(s2)

    # Create a 2D array to store lengths of longest common suffixes of substrings.
    lcs_suffix = [[0] * (len_s2 + 1) for i in range(len_s1 + 1)]
    longest_length = 0  # store length of the longest common substring

    # Building the 2D array
    for i in range(1, len_s1 + 1):
        for j in range(1, len_s2 + 1):
            if s1[i-1] == s2[j-1]:
                lcs_suffix[i][j] = lcs_suffix[i-1][j-1] + 1
                longest_length = max(longest_length, lcs_suffix[i][j])
            else:
                lcs_suffix[i][j] = 0

    return longest_length

