def three_sum(nums, target):
    """
    Determines if there are any three integers in the list whose sum is equal to target.
    :param nums: List of integers
    :param target: The target sum to find triplets summing to
    :return: Boolean value, True if such a triplet exists, False otherwise
    """
    nums.sort()
    n = len(nums)
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # Skip duplicate elements
        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    return False

