def best_buy_sell_days(prices):
    """
    This function takes a list of stock prices and returns the best day to buy and the best day to sell
    to maximize the profit. If no profit can be made, it returns -1 -1.
    """
    if not prices or len(prices) < 2:
        return -1, -1

    min_price_index = 0
    max_profit = 0
    best_day_to_buy = -1
    best_day_to_sell = -1

    for i in range(1, len(prices)):
        if prices[i] - prices[min_price_index] > max_profit:
            max_profit = prices[i] - prices[min_price_index]
            best_day_to_buy = min_price_index
            best_day_to_sell = i
        if prices[i] < prices[min_price_index]:
            min_price_index = i

    if max_profit == 0:
        return -1, -1
    else:
        return best_day_to_buy, best_day_to_sell

