def maximalRectangle(matrix):
    if not matrix:
        return 0

    n, m = len(matrix), len(matrix[0])
    height = [0] * (m + 1)
    max_area = 0

    for i in range(n):
        for j in range(m):
            if matrix[i][j] == '1':
                height[j] += 1
            else:
                height[j] = 0

        stack = [-1]
        for j in range(m + 1):
            while height[j] < height[stack[-1]]:
                h = height[stack.pop()]
                w = j - stack[-1] - 1
                max_area = max(max_area, h * w)
            stack.append(j)

    return max_area

