def min_moves_to_rearrange_books(n, initial, target):
    # Create a map for the positions of the target arrangement
    target_positions = {target[i] : i for i in range(n)}

    index = 0
    moves = 0

    while index < n:
        current_book = initial[index]
        correct_position = target_positions[current_book]

        if correct_position == index:
            index += 1
        else:
            book_to_swap = initial[correct_position]
            initial[correct_position], initial[index] = initial[index], initial[correct_position]
            moves += 1

    return moves

