def unique_paths_with_obstacles(m, n, grid):
    MOD = 1000000007

    if grid[0][0] == '#' or grid[m-1][n-1] == '#':
        return 0

    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1  # Starting point

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

                dp[i][j] %= MOD

    return dp[m-1][n-1]

