def four_sum_exists(arr, k):
    n = len(arr)
    if n < 4:
        return "NO"

    sum_lookup = {}

    for i in range(n):
        for j in range(i + 1, n):
            s = arr[i] + arr[j]
            if s not in sum_lookup:
                sum_lookup[s] = []
            sum_lookup[s].append((i, j))

    for i in range(n):
