def maxVisibleStudents(heights):
    """
    Returns the maximum number of students visible from the front.
    """
    if not heights:
        return 0

    visible_count = 1  # The first student is always visible
    max_height = heights[0]

    for height in heights[1:]:
        if height > max_height:
            visible_count += 1
            max_height = height

    return visible_count

