from typing import List

def max_points(points: List[int]) -> int:
    if not points:
        return 0
    n = len(points)
    if n == 1:
        return points[0]

    dp = [0] * n
    dp[0] = points[0]
    dp[1] = max(points[0], points[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + points[i])

    return dp[-1]

