from typing import List

def max_profit(prices: List[int]) -> int:
    if not prices:
        return 0

    n = len(prices)
    if n < 2:
        return 0

    # dp[i][k][0] means the maximum profit at day i with at most k transactions holding 0 stock
    # dp[i][k][1] means the maximum profit at day i with at most k transactions holding 1 stock
    dp = [[[0, 0] for _ in range(3)] for _ in range(n)]

    for k in range(3):
        dp[0][k][0] = 0
        dp[0][k][1] = -prices[0]

    for i in range(1, n):
        for k in range(1, 3):
            dp[i][k][0] = max(dp[i-1][k][0], dp[i-1][k][1] + prices[i])
            dp[i][k][1] = max(dp[i-1][k][1], dp[i-1][k-1][0] - prices[i])

    return max(dp[n-1][1][0], dp[n-1][2][0])

