def uniquePaths(n, m, obstacles):
    MOD = 1000000007

    # Create a 2D dp array initialized with 0s
    dp = [[0]*m for _ in range(n)]

    # Mark the obstacles in the dp array
    for r, c in obstacles:
        dp[r-1][c-1] = -1

    # Initialize the dp array
    if dp[0][0] == -1:
        return 0

    dp[0][0] = 1

    # Fill the first row
    for j in range(1, m):
        if dp[0][j] == -1:
            dp[0][j] = 0
        else:
            dp[0][j] = dp[0][j-1]

    # Fill the first column
    for i in range(1, n):
        if dp[i][0] == -1:
            dp[i][0] = 0
        else:
            dp[i][0] = dp[i-1][0]

    # Fill the rest of the dp array
    for i in range(1, n):
        for j in range(1, m):
            if dp[i][j] == -1:
                dp[i][j] = 0
            else:
                if dp[i-1][j] != -1:
                    dp[i][j] += dp[i-1][j]
                if dp[i][j-1] != -1:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD

    return dp[n-1][m-1]

