def find_buildings_with_ocean_view(nums):
    """
    Returns the list of indices of buildings that can see the ocean.
    """
    n = len(nums)
    ocean_view_indices = []
    max_height_so_far = -1

    for i in range(n - 1, -1, -1):
        if nums[i] > max_height_so_far:
            ocean_view_indices.append(i)
            max_height_so_far = nums[i]

    return sorted(ocean_view_indices)

