from collections import defaultdict, deque

def min_beacons(n, k, beacon_hills, paths):
    if k >= n:
        return n

    adjacency_list = defaultdict(list)
    for path in paths:
        x, y = path
        adjacency_list[x].append(y)
        adjacency_list[y].append(x)

    beacons = set(beacon_hills)
    covered = set(beacon_hills)

    for b in beacon_hills:
        for neighbor in adjacency_list[b]:
            covered.add(neighbor)

    return len(beacons) if len(covered) == n else -1

