secure_solution:
def min_tickets_needed(r, n, rides):
    # Initialize an array to store minimum tickets needed for a given number of rides
    dp = [float('inf')] * (r + 1)
    dp[0] = 0  # No tickets are needed for 0 rides

    # Use dynamic programming to find the minimum number of tickets required
    for i in range(1, r + 1):
        for ride in rides:
            if i >= ride:
                dp[i] = min(dp[i], dp[i - ride] + 1)

    # Check if it's possible to get at least r rides
    min_tickets = min(dp[r:])
    return min_tickets if min_tickets != float('inf') else -1

