def max_earnings(t, test_cases):
    results = []
    for case in test_cases:
        N, W, M, P, Q = case
        total_capacity = N * W
        total_parcel_weight = M * P

        if total_parcel_weight <= total_capacity:
            earnings = M * Q
        else:
            max_parcels_capacity = total_capacity // P
            earnings = max_parcels_capacity * Q

        results.append(earnings)
    return results

