def find_lis(magnitudes: list[int]) -> int:
    """
    Function to compute the length of the longest increasing subsequence in the `magnitudes` list.
    """
    if not magnitudes:
        return 0

    n = len(magnitudes)
    lis = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if magnitudes[i] > magnitudes[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    return max(lis)

