import heapq
from typing import List, Tuple

def prims_algorithm(graph: List[List[float]]) -> List[Tuple[int, int, float]]:
    n = len(graph)
    visited = [False] * n
    edge_list = []
    min_heap = [(0, 0, -1)]  # (weight, to_node, from_node)

    while min_heap:
        weight, to_node, from_node = heapq.heappop(min_heap)
        if visited[to_node]:
            continue
        visited[to_node] = True
        if from_node != -1:
            edge_list.append((from_node, to_node, weight))

        for next_node in range(n):
            if not visited[next_node] and graph[to_node][next_node] != float('inf'):
                heapq.heappush(min_heap, (graph[to_node][next_node], next_node, to_node))

    return edge_list

