from typing import List

def maxProduct(N: int, arr: List[int]) -> int:
    """
    Returns the maximum product of any two distinct elements in the array.
    """
    if N < 2:
        return 0  # Not enough elements to form a pair

    # Initialize two max values and two min values
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    # Traverse the array to find the two largest and two smallest elements
    for num in arr:
        # Update the maximum numbers
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the minimum numbers
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Maximum product can be either from the two largest numbers or two smallest numbers (if negative)
    return max(max1 * max2, min1 * min2)

