from collections import Counter

def min_replacements_to_anagram(s, t):
    """
    Given two strings s and t, returns the minimum number of single-character 
    replacements needed to make s an anagram of t. Returns -1 if it's 
    not possible to transform s into an anagram of t.
    """
    if len(s) != len(t):
        return -1

    count_s = Counter(s)
    count_t = Counter(t)

    # Calculate the number of replacements needed.
    replacements = 0
    for char in count_t:
        if char in count_s:
            if count_t[char] > count_s[char]:
                replacements += count_t[char] - count_s[char]
        else:
            replacements += count_t[char]

    return replacements

