def max_stackable_boxes(n, boxes):
    # Sort the boxes based on height (primary) and width (secondary)
    boxes.sort(key=lambda x: (x[0], x[1]))

    # Initialize an array for dynamic programming
    dp = [1] * n

    # Apply the LIS-based logic on the sorted boxes
    for i in range(n):
        for j in range(i):
