def four_sum(nums, target):
    """
    Find all unique quadruplets in the array nums that sum up to target.

    Args:
    nums: List[int] - List of integers.
    target: int - The target sum of the quadruplets.

    Returns:
    List[List[int]] - List of unique quadruplets which sum up to the target.
    """
    nums.sort()
    n = len(nums)
    quadruplets = []

    for i in range(n - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # Skip duplicate number.
        for j in range(i + 1, n - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue  # Skip duplicate number.
            k, l = j + 1, n - 1
            while k < l:
                total = nums[i] + nums[j] + nums[k] + nums[l]
                if total == target:
                    quadruplets.append([nums[i], nums[j], nums[k], nums[l]])
                    while k < l and nums[k] == nums[k + 1]:
                        k += 1
                    while k < l and nums[l] == nums[l - 1]:
                        l -= 1
                    k += 1
                    l -= 1
                elif total < target:
                    k += 1
                else:
                    l -= 1

    return quadruplets

