from typing import List

def rotate_matrix_clockwise(matrix: List[List[int]]) -> List[List[int]]:
    if not matrix:
        return []

    n = len(matrix)
    m = max(len(row) for row in matrix)

    # Initialize the rotated matrix with None values
    rotated_matrix = [[None for _ in range(n)] for _ in range(m)]

    for row_idx in range(n):
        for col_idx in range(len(matrix[row_idx])):
            rotated_matrix[col_idx][n - row_idx - 1] = matrix[row_idx][col_idx]

    # Remove trailing None values in each row
    for row in rotated_matrix:
        while row and row[-1] is None:
            row.pop()

    return rotated_matrix

