def check_subarray_sum(nums, k):
    """
    Checks if there's a continuous subarray of size at least 2 that sums up to a multiple of k.
    """
    if not nums or len(nums) < 2:
        return False

    # Dictionary to store the remainder when sum up to current index is divided by k
    remainders = {0: -1}
    total_sum = 0

    for i, num in enumerate(nums):
        total_sum += num
        if k != 0:
            remainder = total_sum % k
        else:
            remainder = total_sum

        if remainder in remainders:
            if i - remainders[remainder] > 1:
                return True
        else:
            remainders[remainder] = i

    return False

