def min_difference_between_two_groups(N, weights):
    total_weight = sum(weights)
    # DP array to keep track of possible sums
    dp = [False] * (total_weight + 1)
    dp[0] = True

    for weight in weights:
        for j in range(total_weight, weight - 1, -1):
            if dp[j - weight]:
                dp[j] = True

    min_diff = float('inf')
    for i in range(total_weight // 2 + 1):
        if dp[i]:
            min_diff = min(min_diff, abs((total_weight - i) - i))

    return min_diff

