secure_solution:
def distinct_subsequences(s: str) -> int:
    MOD = 10**9 + 7
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # There is one way to have an empty subsequence

    last_occurrence = {}

    for i in range(1, n + 1):
        dp[i] = 2 * dp[i - 1] % MOD

        if s[i - 1] in last_occurrence:
            dp[i] = (dp[i] - dp[last_occurrence[s[i - 1]] - 1] + MOD) % MOD

        last_occurrence[s[i - 1]] = i

    return (dp[n] - 1 + MOD) % MOD  # Subtract 1 to exclude the empty subsequence

def findPaths(grid):
    """
    Returns the number of ways to reach the bottom-right corner of the grid from the top-left corner.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    n = len(grid)
    m = len(grid[0])

    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

