def is_subset_sum_possible(target, nums):
    """
    Determines if there exists a subset of the given list of non-negative integers
    such that the sum of the subset is equal to the target value.

    :param target: int, the target sum
    :param nums: List[int], list of non-negative integers
    :return: str, "YES" if such subset exists, otherwise "NO"
    """
    n = len(nums)
    subset = [[False for _ in range(target + 1)] for _ in range(n + 1)]

    for i in range(n + 1):
        subset[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if nums[i - 1] <= j:
                subset[i][j] = subset[i - 1][j] or subset[i - 1][j - nums[i - 1]]
            else:
                subset[i][j] = subset[i - 1][j]

    return "YES" if subset[n][target] else "NO"

