def max_parks(n):
    """
    Returns the maximum number of parks that can be built along the road of length n kilometers.
    Each park can occupy either one or two kilometers, but parks cannot be adjacent.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        # Calculate maximum parks using the rule that we can place parks with 1 empty km between them.
        return (n + 1) // 2

