def max_candy_robbed(n, candies):
    if n == 0:
        return 0
    elif n == 1:
        return candies[0]

    dp = [0] * n
    dp[0] = candies[0]
    dp[1] = max(candies[0], candies[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + candies[i])

    return dp[-1]

