def max_balanced_groups(heights, k):
    """
    Returns the maximum number of balanced groups that can be formed from the given heights
    with the condition that the absolute difference between the heights in any group is at most k.
    """
    if not heights:
        return 0

    groups = 1
    min_height = heights[0]
    max_height = heights[0]

    for height in heights[1:]:
        if height < min_height:
            min_height = height
        if height > max_height:
            max_height = height
        if max_height - min_height > k:
            groups += 1
            min_height = height
            max_height = height

    return groups

