def min_base_modules(n):
    """
    Determine the minimum number of base modules required to achieve the target LBU capacity.
    """
    if n == 1:
        return 1

    # We perform a binary search for efficient calculation
    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        if (mid * (mid + 1)) // 2 >= n:
            right = mid - 1
        else:
            left = mid + 1

    return left

