def min_max_time_to_complete_tasks(n, k, m, times):
    if n < k:
        return -1, -1

    max_time = -1
    min_time = float('inf')
    current_time_window = sum(times[:k])

    # Check the first window
    if current_time_window <= m:
        max_time = current_time_window
        min_time = current_time_window

    # Sliding window technique
    for i in range(1, n - k + 1):
        current_time_window = current_time_window - times[i - 1] + times[i + k - 1]
        if current_time_window <= m:
            if current_time_window > max_time:
                max_time = current_time_window
            if current_time_window < min_time:
                min_time = current_time_window

    if max_time == -1:  # If we didn't find any valid window
        return -1, -1
    else:
        return min_time, max_time

