def max_flowers(n, m, grid):
    # Initialize dp array where dp[i][j] means the maximum flowers can collect to reach cell (i, j)
    dp = [[0]*m for _ in range(n)]
    dp[0][0] = grid[0][0]  # Starting point

    # Fill the first row of the dp array
    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the first column of the dp array
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp array
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[n-1][m-1]

