def find_shortest_paths(graph, source):
    """
    Implements the Bellman-Ford algorithm to find the shortest path from the source node to all other nodes.
    If a negative cycle is detected, returns None.

    Parameters:
    graph (dict): A dictionary representing the graph where keys are node names and values are dictionaries of adjacent nodes with edge weights.
    source (str): The starting node.

    Returns:
    dict: A dictionary mapping each node to the shortest path weight from the source. Returns None if a negative cycle is detected.
    """
    # Initialize the distance to all nodes to infinity, and the distance to the source node to 0
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Relax edges up to |V|-1 times, where V is the number of vertices
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node].items():
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight

    # Check for negative-weight cycles
    for node in graph:
        for neighbor, weight in graph[node].items():
            if distances[node] + weight < distances[neighbor]:
                return None  # Negative cycle detected

    return distances

