def longest_increasing_subarray(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Step 1: Find the lengths of increasing subarrays
    inc_left = [1] * n
    for i in range(1, n):
        if arr[i] > arr[i - 1]:
            inc_left[i] = inc_left[i - 1] + 1

    inc_right = [1] * n
    for i in range(n - 2, -1, -1):
        if arr[i] < arr[i + 1]:
            inc_right[i] = inc_right[i + 1] + 1

    # Step 2: Find the maximum length considering at most one deletion
    max_length = max(inc_left)  # Length without any deletion

    for i in range(1, n - 1):
        if arr[i - 1] < arr[i + 1]:
            max_length = max(max_length, inc_left[i - 1] + inc_right[i + 1])

    return max_length

