def largest_lexicographical_string(test_cases):
    results = []

    for case in test_cases:
        S, k = case
        stack = []
        to_remove = k

        for char in S:
            while stack and to_remove > 0 and stack[-1] < char:
                stack.pop()
                to_remove -= 1
            stack.append(char)

        results.append(''.join(stack[:-to_remove] if to_remove else stack))

    return results

