def max_non_adjacent_sum(arr):
    """
    Returns the maximum sum of a subsequence with the constraint
    that no two numbers in the subsequence should be adjacent in the array.
    """
    if not arr:
        return 0
    if len(arr) == 1:
        return arr[0]

    incl = arr[0]
    excl = 0

    for i in range(1, len(arr)):
        new_excl = max(incl, excl)
        incl = excl + arr[i]
        excl = new_excl

    return max(incl, excl)

