def min_deletions_to_alternate(s):
    """
    This function returns the minimum number of deletions required to make the string alternating.

    Parameters:
    s (str): The input string containing only characters 'a' and 'b'.

    Returns:
    int: The minimum number of deletions required.
    """
    # We will calculate the deletions required to alternate starting with 'a' and starting with 'b'
    delete_start_a = 0  # Deletions if we start with 'a'
    delete_start_b = 0  # Deletions if we start with 'b'

    for i, char in enumerate(s):
        if i % 2 == 0:
            # Even index: start with 'a'
            if char != 'a':
                delete_start_a += 1
            # Even index: start with 'b'
            if char != 'b':
                delete_start_b += 1
        else:
            # Odd index: start with 'a'
            if char != 'b':
                delete_start_a += 1
            # Odd index: start with 'b'
            if char != 'a':
                delete_start_b += 1

    return min(delete_start_a, delete_start_b)

