def remove_duplicate_characters(s: str) -> str:
    """
    Removes duplicate characters from the input string, keeping 
    only the first occurrence of each character and preserving their order.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

