def cycle_sort(arr: List[int]) -> None:
    """
    Sort the input list arr using Cycle Sort algorithm.

    Args:
    arr (List[int]): The list of integers to be sorted.

    Returns:
    None: The function should sort the list in place.
    """
    n = len(arr)
    for start in range(0, n-1):
        item = arr[start]
        pos = start

        for i in range(start + 1, n):
            if arr[i] < item:
                pos += 1

        if pos == start:
            continue

        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]

        while pos != start:
            pos = start
            for i in range(start + 1, n):
                if arr[i] < item:
                    pos += 1
            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]

