def lexicographically_smallest_string(s, k):
    """
    Returns the lexicographically smallest string after at most one operation
    where you can move one of the first k characters to the end.
    """
    if k == 1:
        smallest_string = s
        for i in range(len(s)):
            rotated_string = s[i:] + s[:i]
            if rotated_string < smallest_string:
                smallest_string = rotated_string
        return smallest_string

    return ''.join(sorted(s))

