def first_non_repeating_character(text: str) -> int:
    """
    Finds the first non-repeating character in a given string and returns its index.
    If all characters are repeated or the string is empty, returns -1.
    """
    char_count = {}

    # First pass to count all characters
    for char in text:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass to find the first non-repeating character
    for index, char in enumerate(text):
        if char_count[char] == 1:
            return index

    return -1

