def schedule_meetings(N, employee_times, M, meetings):
    # Initialize the schedule to be empty
    schedule = []

    # Create a dictionary to store the earliest and latest times for each employee
    availability = {i + 1: (employee_times[i][0], employee_times[i][1]) for i in range(N)}

    # Initialize an array to track the last hour when a meeting ends for each employee
    last_meeting_end = {i + 1: 0 for i in range(N)}

    for meeting in meetings:
        meeting_label, duration, participants = meeting[0], meeting[1], meeting[2:]

        # Determine the earliest possible start time considering all participants
        earliest_start = max(availability[participant][0] for participant in participants)
        latest_end = min(availability[participant][1] for participant in participants) - duration + 1

        if earliest_start > latest_end:
            return "IMPOSSIBLE"

        start_time = None
        for time in range(earliest_start, latest_end + 1):
            if all(time >= last_meeting_end[participant] for participant in participants):
                start_time = time
                break

        if start_time is None:
            return "IMPOSSIBLE"

        # Update last meeting end times for the participants
        for participant in participants:
            last_meeting_end[participant] = start_time + duration

        # Add the meeting to the schedule
        schedule.append((meeting_label, start_time))

    return sorted(schedule, key=lambda x: x[1])

