def custom_fibonacci(n, a, b):
    """
    Returns the n-th term of a Fibonacci-like sequence where the first term is `a` and the second term is `b`.
    """
    if n == 1:
        return a
    elif n == 2:
        return b

    first, second = a, b
    for _ in range(3, n + 1):
        next_term = first + second
        first, second = second, next_term

    return second

