from collections import deque

def min_distance_to_fill_with_people(grid):
    """
    Returns the minimum distance required to fill all empty cells with people.
    If it is impossible to fill all empty cells, returns -1.
    """
    if not grid or not grid[0]:
        return -1

    m, n = len(grid), len(grid[0])
    queue = deque()
    empty_cells = 0

    # Initialize the queue with the positions of all people
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                queue.append((i, j, 0))  # Person's position with distance 0
            elif grid[i][j] == 0:
                empty_cells += 1

    if empty_cells == 0:
        return 0  # No empty cells to fill

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    max_dist = 0

    while queue:
        x, y, dist = queue.popleft()
        for d in directions:
            nx, ny = x + d[0], y + d[1]
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0:
                grid[nx][ny] = 1
                empty_cells -= 1
                queue.append((nx, ny, dist + 1))
                max_dist = max(max_dist, dist + 1)

    return max_dist if empty_cells == 0 else -1

def longest_common_subsequence(s1, s2):
    """
    Returns the length of the longest common subsequence (LCS) that can be obtained
    by deleting some characters from each string.
    """
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

