def min_adjacent_swaps(s, t):
    """
    Returns the minimum number of adjacent swaps required to transform string s into string t.
    """
    if sorted(s) != sorted(t):
        return -1

    swaps = 0
    s = list(s)

    for i in range(len(s)):
        if s[i] != t[i]:
            j = i
            while s[j] != t[i]:
                j += 1
            while j > i:
                s[j], s[j - 1] = s[j - 1], s[j]
                swaps += 1
                j -= 1

    return swaps

