def find_peaks(heights):
    """
    Returns a list of indices where the elevation at that point is a peak.
    A peak is defined as an element that is greater than its neighbors.
    """
    if len(heights) < 3:
        return []

    peaks = []
    for i in range(1, len(heights) - 1):
        if heights[i] > heights[i-1] and heights[i] > heights[i+1]:
            peaks.append(i)

    return peaks

def min_operations_to_zero_grid(n, m, grid):
    operations = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                operations += 1
                # Set all the cells part of this 1 to 0
                for k in range(i, n):
                    for l in range(j, m):
                        if grid[k][l] == 1:
                            grid[k][l] = 0
                        else:
                            break
    return operations

