def find_pairs(array, target):
    """
    Returns all unique pairs of integers from the array that sum up to the given target.
    Each pair is sorted in ascending order, and the result list is sorted lexicographically.
    """
    array.sort()
    pairs = set()
    lookup = {}

    for num in array:
        complement = target - num
        if complement in lookup:
            pairs.add((min(num, complement), max(num, complement)))
        lookup[num] = num

    return sorted(list(pairs))

