from typing import List

def max_coins(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    m = len(grid)
    n = len(grid[0])

    # Initialize dp table
    dp = [[0] * n for _ in range(m)]

    # Fill the first row of dp table with the values of grid's first row
    for j in range(n):
        dp[0][j] = grid[0][j]

    # Build the dp table row by row
    for i in range(1, m):
        for j in range(n):
            # For each cell, we consider the maximum coins we can get from the cell directly above,
            # and the two diagonally adjacent cells from the previous row
            max_coins_from_above = dp[i-1][j]
            if j > 0:
                max_coins_from_above = max(max_coins_from_above, dp[i-1][j-1])
            if j < n - 1:
                max_coins_from_above = max(max_coins_from_above, dp[i-1][j+1])

            dp[i][j] = grid[i][j] + max_coins_from_above

    # The answer will be the maximum value in the last row of dp table
    return max(dp[m-1])

