def longest_arith_seq_length(nums, difference):
    """
    Returns the length of the longest arithmetic sequence that can be formed with
    a given common difference.

    :param nums: List of positive integers
    :param difference: Integer, the common difference
    :return: Integer, length of the longest arithmetic sequence
    """
    if not nums:
        return 0

    dp = {}
    max_length = 0

    for num in nums:
        if num - difference in dp:
            dp[num] = dp[num - difference] + 1
        else:
            dp[num] = 1
        max_length = max(max_length, dp[num])

    return max_length

