def min_chars_to_form_target(words, target):
    from collections import Counter
    words_count = Counter(''.join(words))
    target_count = Counter(target)

    min_chars_needed = 0
    for char, count in target_count.items():
        if char not in words_count:
            return -1
        min_chars_needed += count

    return min_chars_needed

