def reformat(s):
    """
    Reformat the string such that no two adjacent characters are of the same type.
    If it's not possible, return an empty string.
    """
    letters = [c for c in s if c.isalpha()]
    digits = [c for c in s if c.isdigit()]

    if abs(len(letters) - len(digits)) > 1:
        return ""

    result = []
    if len(letters) > len(digits):
        longer, shorter = letters, digits
    else:
        longer, shorter = digits, letters

    for i in range(len(s)):
        if i % 2 == 0:
            result.append(longer.pop(0))
        else:
            result.append(shorter.pop(0))

    return "".join(result)

