def check_pair(arr, k, d):
    """
    Determines if there are two distinct indices i and j in the array such that:
    - arr[i] and arr[j] are both divisible by k
    - The absolute difference between i and j is at most d
    """
    divisible_indices = [i for i in range(len(arr)) if arr[i] % k == 0]

    for i in range(len(divisible_indices)):
        for j in range(i + 1, len(divisible_indices)):
            if abs(divisible_indices[i] - divisible_indices[j]) <= d:
                return True

    return False

