def unique_followers_count(n, m, follow_pairs):
    followers = {i: set() for i in range(1, n+1)}

    for u, v in follow_pairs:
        followers[v].add(u)

    result = [0] * n
    for i in range(1, n+1):
        result[i-1] = len(followers[i])

    return result

