from typing import List, Tuple, Dict

def calculate_revenue(transactions: List[Dict]) -> Tuple[Dict[str, float], str]:
    revenue_dict = {}

    for transaction in transactions:
        try:
            product = transaction['product']
            total_amount = transaction['total_amount']

            if total_amount < 0:
                continue

            if product in revenue_dict:
                revenue_dict[product] += total_amount
            else:
                revenue_dict[product] = total_amount

        except KeyError:
            continue

    highest_revenue_product = max(revenue_dict, key=revenue_dict.get, default=None)

    return revenue_dict, highest_revenue_product

