secure_solution:
def lexicographically_smallest_string(s, k):
    """
    Returns the lexicographically smallest string of length k constructed from the string s.
    """
    stack = []
    n = len(s)

    for i, char in enumerate(s):
        while stack and stack[-1] > char and len(stack) + n - i > k:
            stack.pop()
        if len(stack) < k:
            stack.append(char)
    return ''.join(stack)

