secure_solution:
def min_trees_for_fruit(t: int, test_cases: list):
    results = []

    for i in range(t):
        N = test_cases[i][0]
        a = test_cases[i][1]
        S = test_cases[i][2]

        min_length = N + 1
        current_sum = 0
        start = 0

        for end in range(N):
            current_sum += a[end]

            while current_sum >= S:
                min_length = min(min_length, end - start + 1)
                current_sum -= a[start]
                start += 1

        if min_length == N + 1:
            results.append(-1)
        else:
            results.append(min_length)

    return results

