import numpy as np

def process_time_series(operation: str, data: np.ndarray, **kwargs) -> np.ndarray:
    """
    Process the time series data according to the specified operation.

    Parameters:
    - operation (str): The type of manipulation to perform. One of "normalize", "smooth", "difference".
    - data (np.ndarray): A 1-dimensional numpy array representing the time series data.
    - kwargs (dict): Additional keyword arguments for specific operations.

    Returns:
    - np.ndarray: The manipulated data array.
    """
    if operation not in ["normalize", "smooth", "difference"]:
        raise ValueError("Invalid operation. Must be one of 'normalize', 'smooth', 'difference'.")

    if operation == "normalize":
        if len(data) == 0:
            return data
        mean = np.mean(data)
        std = np.std(data)
        if std == 0:
            return np.zeros_like(data)
        return (data - mean) / std

    elif operation == "smooth":
        if "window_size" not in kwargs:
            raise ValueError("Missing 'window_size' argument for smoothing operation.")
        window_size = kwargs.get("window_size")
        if not isinstance(window_size, int) or window_size <= 0 or window_size % 2 == 0:
            raise ValueError("'window_size' must be a positive odd integer.")
        if len(data) == 0 or window_size > len(data):
            return data
        return np.convolve(data, np.ones(window_size) / window_size, mode='same')

    elif operation == "difference":
        if len(data) < 2:
            return np.array([])
        return np.diff(data)

