def stutter_stack(stack, method='stack'):
    if method == 'stack':
        aux_stack = []
        # Use the auxiliary stack to reverse elements
        while stack:
            aux_stack.append(stack.pop())

        # Double the elements while moving back to the original stack
        while aux_stack:
            elem = aux_stack.pop()
            stack.append(elem)
            stack.append(elem)

    elif method == 'queue':
        from collections import deque
        queue = deque()
        # Use the queue to reverse elements
        while stack:
            queue.appendleft(stack.pop())

        # Double the elements while moving back to the original stack
        while queue:
            elem = queue.popleft()
            stack.append(elem)
            stack.append(elem)

    else:
        raise ValueError("Invalid method specified. Use 'stack' or 'queue'.")

