def walls_and_gates(rooms):
    """
    Fills each empty room (INF) with the distance to the nearest gate.
    If unreachable, the room stays as INF.
    """
    if not rooms or not rooms[0]:
        return

    m, n = len(rooms), len(rooms[0])
    queue = deque()

    for i in range(m):
        for j in range(n):
            if rooms[i][j] == 0:
                queue.append((i, j))

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and rooms[nx][ny] == INF:
                rooms[nx][ny] = rooms[x][y] + 1
                queue.append((nx, ny))

