def max_score_sum(scores, k):
    """
    Returns the maximum possible sum of the scores of the k selected students such that no two selected students are adjacent.
    """
    n = len(scores)
    if k == 0:
        return 0
    if k > (n + 1) // 2:
        return None  # not enough students to choose without selecting adjacent ones

    # dp[i][j] means the maximum sum we can get by selecting j students from the first i scores
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            # Option 1: Don't take the i-th student
            dp[i][j] = dp[i-1][j]
            if i > 1:
                # Option 2: Take the i-th student (ensure not taking the (i-1)th student)
                dp[i][j] = max(dp[i][j], dp[i-2][j-1] + scores[i-1])
            elif j == 1:
                dp[i][j] = max(dp[i][j], scores[i-1])

    return dp[n][k]

