def min_operations(t, testcases):
    results = []
    for i in range(t):
        n = testcases[i][0]
        initial_order = testcases[i][1]
        desired_order = testcases[i][2]

        # Check if reversing the initial order directly gives the desired order
        if initial_order == desired_order:
            results.append(0)
            continue
        elif initial_order[::-1] == desired_order:
            results.append(1)
            continue

        # Check how many elements are already in their desired positions
        count = 0
        for j in range(n):
            if initial_order[j] == desired_order[j]:
                count += 1

        # If all are in position, no operations needed.
        if count == n:
            results.append(0)
        # If there is no overlap between the positions, 1 swap or 1 reverse can solve it.
        elif count == 0:
            results.append(1)
        # Otherwise, we can consider we always need at most 2 operations:
        # A swap followed by a reverse can always achieve the desired order.
        else:
            results.append(2)

    return results

