def replace_asterisks(s):
    """
    Replaces every '*' in the input string `s` with a lowercase letter such that
    no two adjacent characters are the same.
    """
    s = list(s)
    n = len(s)

    for i in range(n):
        if s[i] == '*':
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if (i > 0 and s[i - 1] == c) or (i < n - 1 and s[i + 1] == c):
                    continue
                s[i] = c
                break

    return ''.join(s)

