def count_distinct_subsequences(s: str, t: str) -> int:
    m, n = len(t), len(s)
    if m > n:
        return 0

    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for j in range(n + 1):
        dp[0][j] = 1  # An empty t has 1 subsequence in any prefix of s.

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if t[i - 1] == s[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i][j - 1]
            else:
                dp[i][j] = dp[i][j - 1]

    return dp[m][n]

