def tribonacci(n):
    """
    Returns the nth Tribonacci number.
    """
    if n == 0:
        return 0
    elif n == 1 or n == 2:
        return 1

    t0, t1, t2 = 0, 1, 1
    for _ in range(n - 2):
        t_next = t0 + t1 + t2
        t0, t1, t2 = t1, t2, t_next

    return t2

