def robust_join_with_slash(base: str, suffix: str) -> str:
    """
    Concatenates a base URL or file path with a suffix ensuring proper slashes
    are added/removed appropriately.
    """
    # Strip any whitespace
    base = base.strip()
    suffix = suffix.strip()

    # Handle cases where either base or suffix is empty
    if not base and not suffix:
        return ""
    if not base:
        return suffix.lstrip('/')
    if not suffix:
        return base.rstrip('/')

    # Removing the trailing slash from base and leading slash from suffix
    return base.rstrip('/') + '/' + suffix.lstrip('/')

