def sum_of_prime_factors(number: int) -> int:
    if number <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    prime_factors = set()
    divisor = 2

    while number >= 2:
        if number % divisor == 0:
            prime_factors.add(divisor)
            while number % divisor == 0:
                number //= divisor
        divisor += 1

    return sum(prime_factors)

