def length_of_longest_substring_k_distinct(s, k):
    """
    Find the length of the longest substring that can be rearranged to form at most k distinct characters.
    """
    if k == 0:
        return 0

    n = len(s)
    if n == 0:
        return 0

    left, right = 0, 0
    char_count = {}
    max_len = 0

    while right < n:
        char_count[s[right]] = char_count.get(s[right], 0) + 1
        right += 1

        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_len = max(max_len, right - left)

    return max_len

