secure_solution:
def balance_parentheses(s):
    open_stack = []
    to_remove = set()
    for i, char in enumerate(s):
        if char == '(':
            open_stack.append(i)
        elif char == ')':
            if open_stack:
                open_stack.pop()
            else:
                to_remove.add(i)

    # Add any unmatched opening parentheses indices to the to_remove set
    to_remove = to_remove.union(set(open_stack))

    balanced_string = ''.join([char for i, char in enumerate(s) if i not in to_remove])
    return len(to_remove), balanced_string

