def contains_nearby_almost_duplicate(arr, x):
    """
    Determines if there exist two distinct indices i and j in the array such that
    |arr[i] - arr[j]| <= x and |i - j| <= x.

    :param arr: List of integers
    :param x: Integer threshold for both value difference and index difference
    :return: Boolean indicating if such indices exist
    """
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if abs(arr[i] - arr[j]) <= x and abs(i - j) <= x:
                return True
    return False

