import heapq

def shortest_path(n, edges, start, end):
    """
    Computes the shortest transmission time from start to end in a weighted, directed graph.

    :param n: Number of nodes (servers)
    :param edges: List of edges where each edge is represented as [ui, vi, weighti]
    :param start: Starting node
    :param end: Destination node
    :return: Shortest transmission time from start to end, or -1 if no such path exists
    """
    graph = {i: [] for i in range(n)}
    for ui, vi, weight in edges:
        graph[ui].append((vi, weight))

    pq = [(0, start)]  # Priority queue to hold (current_time, current_node)
    dist = {i: float('inf') for i in range(n)}
    dist[start] = 0

    while pq:
        current_time, current_node = heapq.heappop(pq)

        if current_node == end:
            return current_time

        if current_time > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            time = current_time + weight
            if time < dist[neighbor]:
                dist[neighbor] = time
                heapq.heappush(pq, (time, neighbor))

    return -1

