def max_subset_sum(n, k, nums):
    # Initialize a list to store the maximum possible sum for each value up to k
    dp = [0] * (k + 1)

    for num in nums:
        # Traverse the dp array from right to left so that each number is only used once
        for j in range(k, num - 1, -1):
            dp[j] = max(dp[j], dp[j - num] + num)

    # The maximum value in dp array is the answer
    return max(dp)

