from collections import deque

def is_path_exists(N, M, grid):
    # Find the starting position 'S' and the exit position 'E'
    start = None
    end = None
    for i in range(N):
        for j in range(M):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return "NO"

    # Directions for moving up, left, down, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS initialization
    queue = deque([start])
    visited = set()
    visited.add(start)

    while queue:
        x, y = queue.popleft()

        if (x, y) == end:
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and (nx, ny) not in visited and grid[nx][ny] != '1':
                queue.append((nx, ny))
                visited.add((nx, ny))

    return "NO"

