    queue = deque([start])
    visited = set()
    visited.add(start)

    while queue:
        x, y = queue.popleft()

        if (x, y) == end:
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and (nx, ny) not in visited and grid[nx][ny] != '1':
                queue.append((nx, ny))
                visited.add((nx, ny))

    return "NO"

