def calculate_total_penalty(parking_times: List[int], T: int, P: int, G: int) -> int:
    total_penalty = 0
    for time in parking_times:
        if time > T:
            over_time = time - T
            if over_time > G:
                penalty_time = over_time - G
                total_penalty += penalty_time * P
    return total_penalty

