def check_subarray_sum(arr, k):
    """
    Determines if there is a non-empty subarray whose sum is a multiple of k.

    Parameters:
        arr (list of int): The array of integers.
        k (int): The integer which the subarray sum should be a multiple of.

    Returns:
        bool: True if such a subarray exists, False otherwise.
    """
    if k == 0: 
        return any(arr[i] + arr[i - 1] == 0 for i in range(1, len(arr)))

    prefix_sums = {0: -1}
    current_sum = 0

    for i, num in enumerate(arr):
        current_sum += num
        mod = current_sum % k

        if mod in prefix_sums:
            if i - prefix_sums[mod] > 1:
                return True
        else:
            prefix_sums[mod] = i

    return False

