def min_operations_to_palindrome(n, s):
    """
    Returns the minimum number of operations required to transform the given string into a palindrome.
    If it is impossible to transform the string into a palindrome, returns -1.
    """
    changes_needed = 0

    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            changes_needed += 1

    return changes_needed

