def largest_full_binary_rectangle(matrix):
    m = len(matrix)
    n = len(matrix[0])

    if m == 0 or n == 0:
        return (0, 0)

    max_area = 0
    max_row_length = 0
    max_col_length = 0

    dp = [[0] * n for _ in range(m)]

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = (1, 1)
                else:
                    row_len = dp[i-1][j][0] + 1 if matrix[i-1][j] == 1 else 1
                    col_len = dp[i][j-1][1] + 1 if matrix[i][j-1] == 1 else 1
                    dp[i][j] = (row_len, col_len)

