def evaluate_expression(s):
    """
    Evaluates a mathematical expression with non-negative integers and operators '+' '-' '*'.
    """
    tokens = []
    num = 0
    op = '+'

    for char in s + '+':
        if char.isdigit():
            num = num * 10 + int(char)
        else:
            if op == '+':
                tokens.append(num)
            elif op == '-':
                tokens.append(-num)
            elif op == '*':
                tokens[-1] = tokens[-1] * num

            op = char
            num = 0

    return sum(tokens)

