secure_solution:
def can_sum_to_query(arr, queries):
    results = []
    seen = set()
    for number in arr:
        seen.add(number)

    for query in queries:
        found = False
        for number in arr:
            complement = query - number
            if complement in seen and complement != number:
                found = True
                break
        results.append("YES" if found else "NO")

    return results

