secure_solution:
def smallest_substring_length(s):
    """
    Given a string s, find the length of the smallest substring that contains 
    all the distinct characters of the original string at least once.
    """
    distinct_chars = set(s)
    required_chars = len(distinct_chars)

    char_count = {}
    min_length = float('inf')
    left = 0

    for right in range(len(s)):
        if s[right] in char_count:
            char_count[s[right]] += 1
        else:
            char_count[s[right]] = 1

        while len(char_count) == required_chars:
            min_length = min(min_length, right - left + 1)
            if char_count[s[left]] == 1:
                del char_count[s[left]]
            else:
                char_count[s[left]] -= 1
            left += 1

    return min_length

