def longestTrainingSegment(intensities: List[int]) -> int:
    if not intensities:
        return 0

    max_length = 1
    current_length = 1
    increasing = None

    for i in range(1, len(intensities)):
        if intensities[i] == intensities[i - 1]:
            current_length = 1
            increasing = None
        elif intensities[i] > intensities[i - 1]:
            if increasing is None or increasing:
                current_length += 1
            else:
                current_length = 2
            increasing = True
        else:
            if increasing is None or not increasing:
                current_length += 1
            else:
                current_length = 2
            increasing = False

        if current_length > max_length:
            max_length = current_length

    return max_length

