def alphabeticallyOrderedSubstring(S):
    n = len(S)

    if n == 0:
        return ""

    max_len = 1
    current_len = 1
    max_substring = S[0]
    current_substring = S[0]

    for i in range(1, n):
        if S[i] > S[i - 1]:
            current_len += 1
            current_substring += S[i]
        else:
            if current_len > max_len:
                max_len = current_len
                max_substring = current_substring
            current_len = 1
            current_substring = S[i]

    # Check the last substring
    if current_len > max_len:
        max_substring = current_substring

    return max_substring

