def can_be_arranged(n, heights):
    """
    Determine if the heights can be arranged such that for any three
    consecutive plants (h1, h2, h3), the middle plant's height is between
    the other two's heights. If possible, return one such arrangement; 
    otherwise, return "Impossible".

    :param n: number of plants
    :param heights: list of plant heights
    :return: ("Possible" or "Impossible", arrangement or None)
    """
    if n < 3:
        return ("Possible", sorted(heights))

    heights.sort()

    # Check that no two adjacent are the same after sorting
    for i in range(n - 1):
        if heights[i] == heights[i + 1]:
            return ("Impossible", None)

    # Middle element always lies between the smallest and the largest,
    # hence we can just take pairwise elements from start and end
    left = 0
    right = n - 1
    result = []

    while left <= right:
        if left == right:  # Central element addition
            result.append(heights[left])
        else:
            result.append(heights[left])
            result.append(heights[right])
        left += 1
        right -= 1

    return ('Possible', result)

