def find_pythagorean_triplet(k):
    """
    Given a positive integer k, generate the smallest Pythagorean triplet (a, b, c) such that
    a^2 + b^2 = c^2 and a = k.

    If no such triplet exists, return (-1, -1, -1).
    """
