def min_changes_to_make_symmetric(s):
    """
    Returns the minimum number of changes required to make the string symmetric.
    """
    n = len(s)
    changes = 0

    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            changes += 1

    return changes

def create_garden(rows, columns, num_trees):
    """
    Determines if it's possible to plant the desired number of trees in the garden
    such that no two trees are adjacent to each other both horizontally and vertically.
    Returns the garden grid or "IMPOSSIBLE".
    """
    if num_trees > ((rows + 1) // 2) * ((columns + 1) // 2):
        return "IMPOSSIBLE"

    grid = [['.' for _ in range(columns)] for _ in range(rows)]

    tree_count = 0
    for r in range(0, rows, 2):
        for c in range(0, columns, 2):
            if tree_count < num_trees:
                grid[r][c] = 'T'
                tree_count += 1

    return grid

