def find_unsorted_subarray(arr):
    n = len(arr)
    if n <= 1:
        return 0

    start, end = -1, -1

    max_seen = -float('inf')
    min_seen = float('inf')

    for i in range(n):
        max_seen = max(max_seen, arr[i])
        if arr[i] < max_seen:
            end = i

    for i in range(n-1, -1, -1):
        min_seen = min(min_seen, arr[i])
        if arr[i] > min_seen:
            start = i

    if start == -1 or end == -1:
        return 0

    return end - start + 1

