def find_min_time_to_visit_all_parks(N, E, roads, P, parks):
    # Step 1: Initialize the graph with infinite distances
    INF = float('inf')
    dist = [[INF] * (N + 1) for _ in range(N + 1)]

    for i in range(1, N + 1):
        dist[i][i] = 0

    # Step 2: Fill distances with given roads information
    for u, v, w in roads:
        dist[u][v] = w
        dist[v][u] = w

    # Step 3: Apply Floyd-Warshall algorithm to find all-pairs shortest paths
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Step 4: Calculate minimum time to visit all parks
    min_time = INF
    for start_park in parks:
        time = 0
        for end_park in parks:
            if start_park != end_park:
                time += dist[start_park][end_park]
        min_time = min(min_time, time)

    return min_time

