from typing import List

def find_four_sum(nums: List[int], target: int) -> List[List[int]]:
    """
    Identifies unique 4-tuples in an array that sum up to a specified target.

    Args:
    nums: List[int] - A list of integers.
    target: int - The target sum for the 4-tuples.

    Returns:
    List[List[int]] - A list of unique 4-tuples that sum to the target.
    """
    nums.sort()
    quadruples = []
    n = len(nums)

    for i in range(n - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue
            left, right = j + 1, n - 1
            while left < right:
                quad_sum = nums[i] + nums[j] + nums[left] + nums[right]
                if quad_sum == target:
                    quadruples.append([nums[i], nums[j], nums[left], nums[right]])
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif quad_sum < target:
                    left += 1
                else:
                    right -= 1
    return quadruples

