    if nums[0] > nums[1] and nums[0] > nums[-1]:
        return 0
    if nums[-1] > nums[-2] and nums[-1] > nums[0]:
        return n - 1

    left, right = 1, n - 2
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] > nums[(mid - 1) % n] and nums[mid] > nums[(mid + 1) % n]:
            return mid
        elif nums[mid - 1] > nums[mid]:
            right = mid - 1
        else:
            left = mid + 1

    return -1  # Though this return should not be reached in a valid input case

