def min_water_pipes(n, m, grid):
    """
    Returns the minimum number of water pipes required along the grid boundary
    to ensure all buildings have access to water.
    """
    rows_with_buildings = set()
    cols_with_buildings = set()

    # Iterate through the grid to find rows and columns that contain buildings
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                rows_with_buildings.add(i)
                cols_with_buildings.add(j)

    # The minimum number of water pipes needed will be the maximum of the count
    # of unique rows and columns with buildings
    return max(len(rows_with_buildings), len(cols_with_buildings))

