def min_moves_to_avoid_adjacent_duplicates(s):
    """
    Returns the minimum number of moves required to make no two adjacent characters in the string the same.
    """
    n = len(s)
    if n <= 1:
        return 0

    moves = 0
    for i in range(1, n):
        if s[i] == s[i-1]:
            moves += 1

    return moves

