def count_multiple_category_products(n, m, category_data):
    from collections import defaultdict

    product_count = defaultdict(int)

    for category in category_data:
        k, *products = category
        for product in products:
            product_count[product] += 1

    count = sum(1 for product in product_count if product_count[product] > 1)

    return count

