from collections import deque

def min_jumps(heights, d):
    """
    Returns the minimum number of jumps to reach the last building or -1 if not possible.
    """
    n = len(heights)
    if n <= 1:
        return 0

    queue = deque([(0, 0)]) # (current index, current jumps)
    visited = [False] * n
    visited[0] = True

    while queue:
        cur_index, cur_jumps = queue.popleft()

        if cur_index == n - 1:
            return cur_jumps

        for i in range(1, d + 1):
            if cur_index + i < n and heights[cur_index + i] < heights[cur_index] and not visited[cur_index + i]:
                queue.append((cur_index + i, cur_jumps + 1))
                visited[cur_index + i] = True

    return -1

