def replace_with_greater_neighbors(s):
    """
    Takes in a string of space-separated integers and returns a string where each integer
    is replaced by its immediate greater neighbor's value. If there is no greater neighbor,
    it should be replaced by -1.
    """
    nums = list(map(int, s.split()))
    result = []

    for i in range(len(nums)):
        replaced = False
        for j in range(i + 1, len(nums)):
            if nums[j] > nums[i]:
                result.append(nums[j])
                replaced = True
                break
        if not replaced:
            result.append(-1)

    return ' '.join(map(str, result))

