def get_max_length_word(words):
    """
    Returns the word with the maximum length from the input list of words.
    If multiple words have the maximum length, returns the first one encountered.
    """
    if not words:
        return ""

    max_length_word = words[0]

    for word in words[1:]:
        if len(word) > len(max_length_word):
            max_length_word = word

    return max_length_word

