from typing import List

def find_optimal_order(array: List[int]) -> int:
    n = len(array) - 1
    # Initialize the dp table with infinity
    dp = [[float('inf')] * n for _ in range(n)]

    # Base case: single matrix chains, cost is 0
    for i in range(n):
        dp[i][i] = 0

    # L is chain length
    for L in range(2, n+1):
        for i in range(n - L + 1):
            j = i + L - 1
            dp[i][j] = float('inf')
            # Try different places to split the product
            for k in range(i, j):
                q = dp[i][k] + dp[k + 1][j] + array[i] * array[k + 1] * array[j + 1]
                if q < dp[i][j]:
                    dp[i][j] = q

    return dp[0][n-1]

