def limit_occurrences(lst: List[int], N: int) -> List[int]:
    if N == 0:
        return []

    count = {}
    result = []

    for num in lst:
        if num in count:
            if count[num] < N:
                result.append(num)
                count[num] += 1
        else:
            count[num] = 1
            result.append(num)

    return result

