def smallest_local_minimum(n, a):
    """
    Returns the smallest local minimum from the list of integers `a`
    or -1 if no local minimum exists.

    Parameters:
    n (int): The number of elements in the list.
    a (List[int]): The list of integers.

    Returns:
    int: The smallest local minimum, or -1 if no local minimum exists.
    """
    if n == 1:
        return a[0]

    local_minima = []

    for i in range(n):
        if i == 0 and a[i] < a[i + 1]:
            local_minima.append(a[i])
        elif i == n - 1 and a[i] < a[i - 1]:
            local_minima.append(a[i])
        elif 0 < i < n - 1 and a[i] < a[i - 1] and a[i] < a[i + 1]:
            local_minima.append(a[i])

    if not local_minima:
        return -1
    else:
        return min(local_minima)

