def does_robot_return(moves: str) -> bool:
    """
    Determines whether the robot returns to the origin after executing all its moves.

    Parameters:
    moves (str): A string representing the sequence of moves.

    Returns:
    bool: True if the robot returns to the origin, otherwise False.
    """
    x, y = 0, 0
    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
    return x == 0 and y == 0

