def subarray_sum_exactly_n(t, test_cases):
    """
    This function takes the number of test cases 't' and the list of test cases 'test_cases' which contains the length
    of the array, the array, and the target sum and returns a list of results showing the number of contiguous subarrays
    whose sum equals the target for each test case.
    """
    results = []

    for test in test_cases:
        m, arr, N = test
        count = 0

        # Implementing a prefix sum approach using a dictionary to store the cumulative sum frequencies
        cumulative_sum = 0
        sum_freq = {0: 1}

        for num in arr:
            cumulative_sum += num

            if cumulative_sum - N in sum_freq:
                count += sum_freq[cumulative_sum - N]

            if cumulative_sum in sum_freq:
                sum_freq[cumulative_sum] += 1
            else:
                sum_freq[cumulative_sum] = 1

        results.append(count)

    return results

