def min_effort_path(grid):
    """
    Returns the minimum effort required for RobustBot to reach from the top-left to the bottom-right of the grid.
    """
    m, n = len(grid), len(grid[0])
    effort = [[0 for _ in range(n)] for _ in range(m)]

    effort[0][0] = grid[0][0]

    for i in range(1, m):
        effort[i][0] = effort[i-1][0] + grid[i][0]

    for j in range(1, n):
        effort[0][j] = effort[0][j-1] + grid[0][j]

    for i in range(1, m):
        for j in range(1, n):
            effort[i][j] = min(effort[i-1][j], effort[i][j-1]) + grid[i][j]

    return effort[m-1][n-1]

