def minDifference(A):
    """
    Returns the minimum possible absolute difference between the sum of two subarrays.
    """
    import sys

    total_sum = sum(A)
    n = len(A)
    half_sum = total_sum // 2

    # dp[i][j] will be True if a subset with sum j can be formed using first i elements.
    dp = [[False] * (half_sum + 1) for _ in range(n + 1)]

    # Initialize dp[0][0] = True because sum of 0 can always be formed with 0 elements
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, half_sum + 1):
            dp[i][j] = dp[i - 1][j]
            if A[i - 1] <= j:
                dp[i][j] = dp[i][j] or dp[i - 1][j - A[i - 1]]

    # Find the largest j such that dp[n][j] is True where j is half_sum or less
    for j in range(half_sum, -1, -1):
        if dp[n][j]:
            subset_sum = j
            break

    return abs(total_sum - 2 * subset_sum)

