def min_segments(nums, k):
    """
    Returns the minimum number of segments required to partition the array `nums`
    such that every segment has a sum less than or equal to `k`.
    """
    segments = 0
    current_sum = 0

    for num in nums:
        if current_sum + num <= k:
            current_sum += num
        else:
            segments += 1
            current_sum = num

    if current_sum > 0:
        segments += 1

    return segments

def prepare_solution(V, C):
    """
    Prepare the required solution volume V with concentration C using solutions A, B, and C.
    Solutions have concentrations of 10%, 20%, and 30%, respectively.
    Returns the volumes of A, B, and C used.
    """
    # Simple case where the target concentration matches one of the solution concentrations
    if C == 10.0:
        return V, 0, 0
    elif C == 20.0:
        return 0, V, 0
    elif C == 30.0:
        return 0, 0, V

    # We need to find volumes a, b, and c such that:
    # a + b + c = V
    # 10a + 20b + 30c = C * V

    # Substituting b and c in terms of a:
    for a in range(int(V) + 1):
        for b in range(int(V - a) + 1):
            c = V - a - b
            if (10 * a + 20 * b + 30 * c) == (C * V):
                return a, b, c

    return 0, 0, 0

