def restore_string(s, indices):
    """
    Restores the original string from the jumbled string `s` according to the list of indices `indices`.

    :param s: A jumbled string.
    :param indices: A list of positions representing the correct positions of each character in `s`.
    :return: The original string reordered according to `indices`.
    """
    if len(s) != len(indices):
        raise ValueError("Length of string and indices list must be the same")

    original_string = [''] * len(s)
    for char, index in zip(s, indices):
        original_string[index] = char

    return ''.join(original_string)

