def is_unimodal(nums):
    """
    Determines if a list of integers is unimodal.

    Args:
        nums: A list of integers.

    Returns:
        bool: True if the list is unimodal, False otherwise.
    """
    n = len(nums)
    if n < 3:
        return True

    increasing = True
    peak_found = False

    for i in range(1, n):
        if increasing:
            if nums[i] < nums[i-1]:
                increasing = False
        if not increasing:
            if nums[i] > nums[i-1]:
                return False
    return True

