def minimize_missed_deadlines(n, tasks):
    # Sort tasks by their deadlines first, then by start time
    tasks = sorted(tasks, key=lambda x: (x[2], x[0]))

    current_time = 0
    missed_deadlines = 0

    for start_time, duration, deadline in tasks:
        if start_time > current_time:
            current_time = start_time

        if current_time + duration <= deadline:
            current_time += duration
        else:
            missed_deadlines += 1

