def min_remove_to_make_valid_parentheses(s):
    """
    Returns the minimum number of parentheses to remove to make the string valid.
    """
    open_count = 0
    unmatched_closing = 0

    # Iterate through the string to count mismatched parentheses
    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            if open_count > 0:
                open_count -= 1
            else:
                unmatched_closing += 1

    # The total removals needed will be the sum of unmatched opening and closing parentheses
    return open_count + unmatched_closing

