def count_pairs(s):
    """
    Returns the number of pairs (i, j) such that s[i] is not equal to s[j] for the given string s.
    """
    n = len(s)
    char_count = {}

    # Count the occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Number of pairs (i, j) such that 1 ≤ i < j ≤ |s|
    total_pairs = n * (n - 1) // 2

    # Subtract the pairs where characters are the same
    for count in char_count.values():
        total_pairs -= count * (count - 1) // 2

    return total_pairs

