def find_paths(n, m, k, forbidden):
    forbidden_cells = set(forbidden)
    if (1, 1) in forbidden_cells or (n, m) in forbidden_cells:
        return 0

    dp = [[0 for _ in range(m+1)] for _ in range(n+1)]
    dp[1][1] = 1

    for i in range(1, n+1):
        for j in range(1, m+1):
            if (i, j) in forbidden_cells or (i, j) == (1, 1):
                continue
            if i > 1:
                dp[i][j] += dp[i - 1][j]
            if j > 1:
                dp[i][j] += dp[i][j - 1]

    return dp[n][m]

