def count_peaks(heights: list) -> int:
    """
    :param heights: a list of integers representing building heights.
    :return: an integer count of the number of peaks in the list.

    Raises:
        TypeError: If the input is not a list.
    """

    if not isinstance(heights, list):
        raise TypeError(f"The input value of [heights={heights}] is not a list")

    if len(heights) < 3:
        return 0

    peaks = 0
    for i in range(1, len(heights) - 1):
        if heights[i] > heights[i - 1] and heights[i] > heights[i + 1]:
            peaks += 1

    return peaks

