MOD = 10**9 + 7

def count_unique_sequences(n, k):
    if k == 1:
        return n

    sequences_for_k_minus_1 = n
    sequences_for_k = n * (n - 1)

    for i in range(2, k):
        new_sequences_for_k = sequences_for_k * (n - 1)  
        sequences_for_k = new_sequences_for_k % MOD

    return sequences_for_k % MOD

