def digit_power_sum(n):
    num = 1
    count = 0

    while count < n:
        current_sum = sum(int(digit) ** (idx + 1) for idx, digit in enumerate(str(num)))
        if current_sum == num:
            count += 1
        num += 1

    return num - 1

