from typing import List

def longest_increasing_subsequence(a: List[int]) -> int:
    if not a:
        return 0

    n = len(a)
    # Initialize lengths of longest subsequence ending at each position
    lis_lengths = [1] * n

    for i in range(1, n):
        for j in range(i):
            if a[i] > a[j]:  # We can include a[i] in the subsequence ending at a[j]
                lis_lengths[i] = max(lis_lengths[i], lis_lengths[j] + 1)

    # The length of the longest increasing subsequence is the maximum value in lis_lengths
    return max(lis_lengths)

