def climb_stairs_advanced(steps: int) -> int:
    MOD = 10**9 + 7

    if steps == 1:
        return 1
    elif steps == 2:
        return 2
    elif steps == 3:
        return 4

    ways = [0] * (steps + 1)
    ways[1] = 1
    ways[2] = 2
    ways[3] = 4

    for i in range(4, steps + 1):
        ways[i] = (ways[i-1] + ways[i-2] + ways[i-3]) % MOD

    return ways[steps]

