secure_solution:
def min_deletions_to_palindrome(s: str) -> int:
    n = len(s)

    # Create a DP table to store the length of LPS
    dp = [[0] * n for _ in range(n)]

    # All substrings of length 1 are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Length of the longest palindromic subsequence
    lps_length = dp[0][n - 1]

    # Minimum deletions to achieve a palindrome
    return n - lps_length

