def max_subarray_length(nums, k):
    """
    Returns the maximum length of a subarray that has a sum equal to k.
    If there isn't one, return 0 instead.
    """
    sum_to_index = {0: -1}
    current_sum = 0
    max_length = 0

    for i in range(len(nums)):
        current_sum += nums[i]
        if current_sum - k in sum_to_index:
            max_length = max(max_length, i - sum_to_index[current_sum - k])
        if current_sum not in sum_to_index:
            sum_to_index[current_sum] = i

    return max_length

