secure_solution:
def pair_indices(nums, target):
    """
    Returns all pairs of indices (i, j) such that nums[i] + nums[j] == target 
    with i < j. The pairs are returned in lexicographical order.
    """
    pairs = []
    seen = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            for j in seen[complement]:
                pairs.append((j, i))
        if num in seen:
            seen[num].append(i)
        else:
            seen[num] = [i]

    pairs.sort()
    return pairs

