def num_paths(n, m, grid):
    """
    Function to find the number of distinct paths from (1,1) to (n,m) on a grid with blocked cells.
    Movement is only allowed right or down.
    """
    MOD = 1000000007

    # Initialize dp table with zeros
    dp = [[0] * m for _ in range(n)]

    # If the starting cell is blocked, return 0
    if grid[0][0] == '#':
        return 0

    # Starting cell
    dp[0][0] = 1

    # Fill dp table
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]
                dp[i][j] %= MOD

    return dp[n - 1][m - 1]

