def generate_sensor_grid(n):
    """
    Generates a valid n x n grid of sensors and empty cells.
    Each sensor can communicate directly with at least one other sensor.
    """
    grid = []
    for i in range(n):
        row = []
        for j in range(n):
            if (i + j) % 2 == 0:
                row.append('*')
            else:
                row.append('.')
        grid.append(''.join(row))
    return grid

