def highest_peak(elevations: list[int]) -> int:
    """
    Returns the height of the highest peak in the given list of elevation readings.
    If there are no peaks, return -1.
    """
    if len(elevations) < 3:
        return -1

    highest = -1  # Initialize the highest peak variable with -1

    for i in range(1, len(elevations) - 1):
        if elevations[i] > elevations[i - 1] and elevations[i] > elevations[i + 1]:
            highest = max(highest, elevations[i])

    return highest

