def generate_rna_sequences(sequence):
    """
    Generates all possible valid RNA sequences by replacing each 'N' in the input sequence
    with all possible nucleotides ('A', 'C', 'G', 'U').
    """
    if not sequence:
        return ['']

    nucleotides = ['A', 'C', 'G', 'U']
    result = ['']

    for char in sequence:
        if char == 'N':
            result = [seq + nucleotide for seq in result for nucleotide in nucleotides]
        else:
            result = [seq + char for seq in result]

    return result

