def is_properly_indented(document):
    """
    Checks if a document follows the specified indentation rule.
    """
    blocks = document.split('\n\n')  # Split document by blocks (empty lines)

    for block in blocks:
        lines = block.split('\n')  # Split block by lines
        if not lines:
            continue

        prev_indent = None

        for line in lines:
            current_indent = len(line) - len(line.lstrip())

            if prev_indent is None:
                prev_indent = current_indent
            elif current_indent < prev_indent:
                return "NO"

            prev_indent = current_indent

    return "YES"

