    """
    This function returns the length of the longest contiguous subarray with exactly two different unique elements.
    """
    if not nums:
        return 0

    left, right = 0, 0
    max_length = 0
    freq_map = {}

    while right < len(nums):
        if nums[right] in freq_map:
            freq_map[nums[right]] += 1
        else:
