def longest_subsequence(nums):
    """
    Returns the length of the longest subsequence such that the difference between
    consecutive elements is either -1, 0, or 1.
    """
    if not nums:
        return 0

    subsequences = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if abs(nums[i] - nums[j]) <= 1:
                subsequences[i] = max(subsequences[i], subsequences[j] + 1)

    return max(subsequences)

