import heapq

def network_delay_time(edges, n, start, end):
    """
    Finds the minimum time required to transfer data from the start node to the end node.
    Returns -1 if it is impossible to transfer data between the two nodes.
    """
    # Create an adjacency list representation of the graph
    graph = {i: [] for i in range(n)}
    for u, v, time in edges:
        graph[u].append((v, time))
        graph[v].append((u, time))

    # Use Dijkstra's algorithm to find the shortest path
    pq = [(0, start)]  # Priority queue to store (time, node) pairs
    min_time = {i: float('inf') for i in range(n)}
    min_time[start] = 0

    while pq:
        current_time, node = heapq.heappop(pq)

        if node == end:
            return current_time

        if current_time > min_time[node]:
            continue

        for neighbor, time in graph[node]:
            new_time = current_time + time
            if new_time < min_time[neighbor]:
                min_time[neighbor] = new_time
                heapq.heappush(pq, (new_time, neighbor))

    return -1 if min_time[end] == float('inf') else min_time[end]

