from datetime import datetime

def calculate_fine(return_date, due_date):
    """
    Calculates the fine for overdue books based on the return date and due date.
    Return "Invalid date format." if the input dates are not in the correct format.
    """
    try:
        return_date = datetime.strptime(return_date, "%Y-%m-%d")
        due_date = datetime.strptime(due_date, "%Y-%m-%d")
    except ValueError:
        return "Invalid date format."

    if return_date <= due_date:
        return 0

    days_overdue = (return_date - due_date).days
    if days_overdue <= 7:
        fine = days_overdue * 2
    else:
        fine = 7 * 2 + (days_overdue - 7) * 5

    return fine

