def minimum_calorie_difference(foods, targetCalories):
    """
    Returns the minimum difference between the total calories of the chosen 
    meal plan and targetCalories.

    :param foods: List[int], list of calories of each food item
    :param targetCalories: int, the target calorie intake
    :return: int, the minimum difference
    """
    n = len(foods)
    total_calories = sum(foods)

    dp = [[False] * (total_calories + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(total_calories + 1):
            if dp[i - 1][j]:
                dp[i][j] = True
                if j + foods[i - 1] <= total_calories:
                    dp[i][j + foods[i - 1]] = True

    min_diff = float('inf')
    for s in range(total_calories + 1):
        if dp[n][s]:
            min_diff = min(min_diff, abs(targetCalories - s))

    return min_diff

def longest_equal_subarray(arr):
    """
    Returns the length of the longest contiguous subarray with equal number of 1s and -1s.
    If no such subarray exists, return 0.
    """
    # Convert 1s to 1 and -1s to -1 and ignore 0s
    filtered_arr = [x for x in arr if x != 0]

    # Dictionary to store the first occurrence of count difference
    count_dict = {0: -1}
    count = 0
    max_length = 0

    for i, num in enumerate(filtered_arr):
        if num == 1:
            count += 1
        elif num == -1:
            count -= 1

        if count in count_dict:
            max_length = max(max_length, i - count_dict[count])
        else:
            count_dict[count] = i

    return max_length

