def find_highest_scorer(n, results):
    """
    Returns the index (1-based) of the player with the highest total score.
    If there are multiple players with the same highest score, returns the
    player with the smallest index.
    """
    scores = [0] * n

    # Calculate the total score for each player
    for i in range(n):
        for j in range(n):
            scores[i] += results[i][j]

    # Find the player with the highest score. If there's a tie, choose the player with the smallest index
    max_score = max(scores)
    for index, score in enumerate(scores):
        if score == max_score:
            return index + 1

from collections import deque, defaultdict

def find_order(n, m, dependencies):
    # Create adjacency list and in-degree list
    adj_list = defaultdict(list)
    in_degree = [0] * (n + 1)

    for ai, bi in dependencies:
        adj_list[ai].append(bi)
        in_degree[bi] += 1

    # Use a queue to implement topological sorting
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    order = []
    while queue:
        current = queue.popleft()
        order.append(current)

        for neighbor in adj_list[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if topological sort includes all nodes
    if len(order) == n:
        return order
    else:
        return "IMPOSSIBLE"

