def categorize_words_by_length(N_words):
    """
    Categorizes words by their lengths and returns a dictionary where the keys are word lengths and 
    the values are lists of words sorted in lexicographical order.

    Parameters:
    N_words (str): a single line containing an integer N followed by N words separated by spaces.

    Returns:
    dict: A dictionary where the keys are word lengths and the values are lists of words of that length.
    """
    words = N_words.split()[1:]  # Skip the first integer which is N
    categorized_words = {}

    for word in words:
        length = len(word)
        if length in categorized_words:
            categorized_words[length].append(word)
        else:
            categorized_words[length] = [word]

    for length in categorized_words:
        categorized_words[length].sort()

    return categorized_words

