def square_root(n: int, p: float) -> float:
    """
    Returns the square root of n to within the precision p using binary search.
    """
    if n < 0:
        raise ValueError("The input number should be a positive integer.")

    if n == 0:
        return 0.0

    low, high = 0, n
    mid = (low + high) / 2.0

    while high - low > p:
        if mid * mid < n:
            low = mid
        else:
            high = mid
        mid = (low + high) / 2.0

    return mid

