def minimize_max_skill_difference(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        skill_levels = test_cases[i][1]

        skill_levels.sort()
        max_diff = float('-inf')

        for j in range(N):
            diff = abs(skill_levels[2*j] - skill_levels[2*j + 1])
            if diff > max_diff:
                max_diff = diff

