def reorder_list(lst, k):
    lst_len = len(lst)

    if k == 1 and lst_len > 1:  # If k == 1 and list has more than one item, it's impossible to meet the condition
        return "No Solution"

    # Sort the list to easily compare elements
    lst_sorted = sorted(lst)

    # Try to create a valid reordering
    for i in range(lst_len):
        if lst_sorted[i] == i % k:
            # Swap with the next element if possible
            if i + 1 < lst_len and lst_sorted[i + 1] != (i % k):
                lst_sorted[i], lst_sorted[i + 1] = lst_sorted[i + 1], lst_sorted[i]
            # Swap with the previous element if possible
            elif i - 1 >= 0 and lst_sorted[i - 1] != (i % k):
                lst_sorted[i], lst_sorted[i - 1] = lst_sorted[i - 1], lst_sorted[i]
            else:
                return "No Solution"

    return f"Yes\n{' '.join(map(str, lst_sorted))}"

