def longest_zero_sum_subsequence(arr):
    prefix_sum = 0
    prefix_sum_dict = {}
    max_length = 0

    for i, val in enumerate(arr):
        prefix_sum += val

        if prefix_sum == 0:
            max_length = i + 1

        if prefix_sum in prefix_sum_dict:
            max_length = max(max_length, i - prefix_sum_dict[prefix_sum])
        else:
            prefix_sum_dict[prefix_sum] = i

    return max_length

