def min_swaps_to_alternate(binary_string: str) -> int:
    n = len(binary_string)

    if n <= 1:
        return 0  # A single character string is already alternating.

    count_0 = binary_string.count('0')
    count_1 = binary_string.count('1')

    if abs(count_0 - count_1) > 1:
        return -1

    # Pattern starting with '0'
    pattern_0 = ''.join('0' if i % 2 == 0 else '1' for i in range(n))
    # Pattern starting with '1'
    pattern_1 = ''.join('1' if i % 2 == 0 else '0' for i in range(n))

    mismatch_0 = sum(1 for i in range(n) if binary_string[i] != pattern_0[i])
    mismatch_1 = sum(1 for i in range(n) if binary_string[i] != pattern_1[i])

    if count_0 == count_1:
        return min(mismatch_0 // 2, mismatch_1 // 2)
    elif count_0 > count_1:
        return mismatch_0 // 2
    else:
        return mismatch_1 // 2

