def find_three_sum(nums, target):
    """
    Determine if there exist three integers in nums whose sum is equal to target.
    Return a tuple containing these three integers if such a triplet exists.
    If no such triplet exists, return an empty list.
    """
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                return (nums[i], nums[left], nums[right])
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return []

