def findSubstring(s, words):
    """
    Find the starting indices of all concatenated substrings in s 
    that are formed by combining each word in words exactly once in any order.
    """
    if not s or not words or not words[0]:
        return []

    word_length = len(words[0])
    num_words = len(words)
    total_length = word_length * num_words
    word_count = {}

    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    result = []

    for i in range(word_length):
        left = i
        right = i
        current_count = {}
        while right + word_length <= len(s):
            word = s[right:right + word_length]
            right += word_length

            if word in word_count:
                if word in current_count:
                    current_count[word] += 1
                else:
                    current_count[word] = 1

                while current_count[word] > word_count[word]:
                    left_word = s[left:left + word_length]
                    current_count[left_word] -= 1
                    left += word_length

                if right - left == total_length:
                    result.append(left)
            else:
                current_count.clear()
                left = right

    return sorted(result)

