def is_valid_pattern(m, n, b, blocks):
    """
    Verifies if the pattern of b colored blocks forms a contiguous, non-overlapping rectangle
    within an m x n grid.
    """
    grid = [[0]*n for _ in range(m)]

    for block in blocks:
        x1, y1, x2, y2 = block
        for i in range(x1 - 1, x2):
            for j in range(y1 - 1, y2):
                if grid[i][j] != 0:
                    return "NO"
                grid[i][j] = 1

    # Check if there are any internal holes and all blocks are contiguous
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 1 and (
                grid[i-1][j] == 0 or grid[i][j-1] == 0 or grid[i-1][j-1] == 0
            ):
                return "NO"

    # Check edge continuity
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                if (i > 0 and grid[i-1][j] == 0) or \
                   (j > 0 and grid[i][j-1] == 0) or \
                   (i < m-1 and grid[i+1][j] == 0) or \
                   (j < n-1 and grid[i][j+1] == 0):
                    break
        else:
            continue
        break
    else:
        return "YES"

    return "NO"

