def four_sum(arr, target):
    """
    Determines if there are four elements in the list `arr` that add up to `target`.

    Args:
    arr (list of int): List of integers to analyze.
    target (int): The target sum.

    Returns:
    bool: True if there are four elements that add up to the target, False otherwise.
    """
    arr.sort()
    n = len(arr)

    for i in range(n - 3):
        if i > 0 and arr[i] == arr[i - 1]:
            continue

        for j in range(i + 1, n - 2):
            if j > i + 1 and arr[j] == arr[j - 1]:
                continue

            left = j + 1
            right = n - 1

            while left < right:
                total = arr[i] + arr[j] + arr[left] + arr[right]

                if total == target:
                    return True
                elif total < target:
                    left += 1
                else:
                    right -= 1

    return False

