def three_sum(nums, target):
    """
    Determines if there are three integers in nums whose sum equals target.

    :param nums: List of non-negative integers
    :param target: Integer target for the sum of three numbers
    :return: True if any three numbers sum up to the target, otherwise False
    """
    nums.sort()
    n = len(nums)

    for i in range(n-2):
        if i > 0 and nums[i] == nums[i-1]:
            continue

        left, right = i + 1, n - 1
        while left < right:
            curr_sum = nums[i] + nums[left] + nums[right]
            if curr_sum == target:
                return True
            elif curr_sum < target:
                left += 1
            else:
                right -= 1

    return False

