import re
from typing import Dict

def word_frequencies(text: str) -> Dict[str, int]:
    """
    Processes a string and returns a dictionary with the frequency of each distinct word.
    Words are considered as sequences of characters separated by whitespaces or punctuations.
    """
    words = re.findall(r'\b\w+\b', text.lower())
    frequency = {}
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1
    return frequency

