def substitute_cipher(plaintext, shift):
    """
    Encrypt a text using a simple substitution cipher where each letter is shifted 
    by a fixed number of positions in the alphabet, preserving the case.

    Parameters:
    plaintext (str): The text to be encrypted.
    shift (int): The number of positions each letter should be shifted.

    Returns:
    str: The encrypted text.
    """
    encrypted_text = []

    for char in plaintext:
        if char.isalpha():
            # Shift character within its case range
            if char.islower():
                shifted_char = chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            else:
                shifted_char = chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
            encrypted_text.append(shifted_char)
        else:
            encrypted_text.append(char)

    return ''.join(encrypted_text)

