def max_points(m, D, tasks):
    dp = [[0] * (D + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        points, difficulty = tasks[i - 1]
        for j in range(D + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= difficulty:
                dp[i][j] = max(dp[i][j], dp[i - 1][j - difficulty] + points)

    return dp[m][D]

