def is_anagram_case_insensitive(s: str, t: str) -> bool:
    """
    Determines if t is an anagram of s, considering case insensitivity.
    """
    # Convert both strings to lower case to ensure case insensitivity
    s = s.lower()
    t = t.lower()

    # If lengths are different, they cannot be anagrams
    if len(s) != len(t):
        return False

    # Use dictionaries to count the frequency of each character
    char_count_s = {}
    char_count_t = {}

    for char in s:
        if char in char_count_s:
            char_count_s[char] += 1
        else:
            char_count_s[char] = 1

    for char in t:
        if char in char_count_t:
            char_count_t[char] += 1
        else:
            char_count_t[char] = 1

    # Compare the two dictionaries
    return char_count_s == char_count_t

