def most_frequent_word(text):
    """
    Returns the most frequent word in the given text along with its frequency.
    If multiple words have the same highest frequency, the word that appears first alphabetically is returned.
    """
    words = text.split()
    word_count = {}

    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    max_frequency = max(word_count.values())
    most_frequent_words = [word for word, count in word_count.items() if count == max_frequency]

    most_frequent_words.sort()

    return most_frequent_words[0], max_frequency

