def max_len_subarray_with_sum_zero(arr):
    """
    Returns the length of the longest subarray with sum equal to zero.
    """
    # Dictionary to store the sum up to each index
    sum_index_map = {}
    max_len = 0
    current_sum = 0

    for index, value in enumerate(arr):
        current_sum += value

        # If the current sum is zero, we found a subarray from the beginning
        if current_sum == 0:
            max_len = index + 1

        # If current sum has been seen before, there's a zero-sum subarray
        if current_sum in sum_index_map:
            max_len = max(max_len, index - sum_index_map[current_sum])
        else:
            # Store the index of this sum if it hasn't been seen before
            sum_index_map[current_sum] = index

    return max_len

