MOD = 10**9 + 7

def count_beautiful_permutations(n):
    """
    Returns the number of beautiful permutations of integers from 1 to n
    such that the sum of absolute differences between consecutive elements is even.
    The result is returned modulo 10^9 + 7.
    """
    if n == 1:
        return 1

    factorial = [1] * (n + 1)
    for i in range(2, n + 1):
        factorial[i] = factorial[i - 1] * i % MOD

    if n % 2 == 0:
        return factorial[n] // 2 % MOD
    else:
        return factorial[n]

