def find_majority_candidate(arr):
    """
    Returns the label of the candidate who received strictly more than half of the total votes,
    or -1 if no such candidate exists.
    """
    n = len(arr)
    total_votes = sum(arr)
    half_votes = total_votes / 2

    for i in range(n):
        if arr[i] > half_votes:
            return i + 1  # Candidate labels are 1-based (1 to n)

    return -1

