def count_allowed_substrings(s, banned_substrings):
    """
    Returns the number of substrings of s that are not in the list of banned_substrings.

    :param s: Input string of lowercase alphabetic characters.
    :param banned_substrings: List of banned substrings.
    :return: Number of allowed substrings.
    """
    n = len(s)
    all_substrings = set()

    # Generate all possible substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            all_substrings.add(s[i:j])

    # Subtract the banned substrings
    for banned in banned_substrings:
        if banned in all_substrings:
            all_substrings.remove(banned)

    return len(all_substrings)

