def longest_subsequence_with_diff_limit(n, k, arr):
    """
    Finds the length of the longest subsequence where the difference between consecutive elements is not above k.

    Parameters:
    n (int): The length of the input list arr
    k (int): The maximum allowed difference between consecutive elements
    arr (list of int): The input list of integers

    Returns:
    int: The length of the longest subsequence with the given property
    """
    if n == 0:
        return 0

    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if abs(arr[i] - arr[j]) <= k:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

