def find_pairs(n: int, arr: List[int], t: int) -> List[Tuple[int, int]]:
    seen = {}
    result = []
    for i in range(n):
        complement = t - arr[i]
        if complement in seen:
            for j in seen[complement]:
                result.append((j + 1, i + 1))
        if arr[i] in seen:
            seen[arr[i]].append(i)
        else:
            seen[arr[i]] = [i]
    return sorted(result)

