import heapq

def shortest_transmission_time(n, m, edges, s, d):
    """
    Finds the shortest transmission time from node `s` to node `d` using Dijkstra's algorithm.
    """
    # Create a graph representation
    graph = {i: [] for i in range(1, n+1)}
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Priority queue for Dijkstra's algorithm
    pq = [(0, s)]
    # Distance table, initialized to infinity
    distances = {i: float('inf') for i in range(1, n+1)}
    distances[s] = 0

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node == d:
            return current_dist

        for neighbor, weight in graph[current_node]:
            distance = current_dist + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return -1 if distances[d] == float('inf') else distances[d]

