import math

def min_perfect_squares(num):
    """
    Returns the minimum number of perfect squares that sum up to num.
    """
    if num <= 0:
        raise ValueError("Input must be a positive integer.")

    # Fast solution for perfect squares
    if int(math.sqrt(num)) ** 2 == num:
        return 1

    # Check if the number can be expressed as the sum of two perfect squares
    for i in range(1, int(math.sqrt(num)) + 1):
        remainder = num - i * i
        if int(math.sqrt(remainder)) ** 2 == remainder:
            return 2

    # Check if the number can be expressed as the sum of three perfect squares
    for i in range(1, int(math.sqrt(num)) + 1):
        for j in range(1, int(math.sqrt(num - i * i)) + 1):
            remainder = num - i * i - j * j
            if int(math.sqrt(remainder)) ** 2 == remainder:
                return 3

    # If not, by the 4-square theorem (Lagrange's Four Square Theorem), it must be a sum of four perfect squares
    return 4

