def can_transform_by_one_swap(source: str, target: str) -> str:
    """
    Check if the target word can be formed by performing exactly one swap of any 
    two letters of the source word.
    """
    if len(source) != len(target):
        return "NO"

    # Find the positions where the two words differ
    differences = []
    for i in range(len(source)):
        if source[i] != target[i]:
            differences.append(i)

    # If there are not exactly two differences, return "NO"
    if len(differences) != 2:
        return "NO"

    # Check if swapping the differing characters in source makes it equal to target
    i, j = differences
    if source[i] == target[j] and source[j] == target[i]:
        return "YES"

    return "NO"

