def longest_upward_subsequence(prices: list) -> list:
    n = len(prices)
    if n == 0:
        return []

    # Create an array to store the longest subsequence ending at each position
    dp = [[] for _ in range(n)]
    dp[0] = [prices[0]]

    max_len = 1
    last_index = 0

    for i in range(1, n):
        for j in range(i):
            if prices[i] > prices[j] and prices[i] not in dp[j]:
                if len(dp[j]) + 1 > len(dp[i]):
                    dp[i] = dp[j] + [prices[i]]
                    if len(dp[i]) > max_len:
                        max_len = len(dp[i])
                        last_index = i
        if not dp[i]:  # no better subsequence found in the inner loop
            dp[i] = [prices[i]]

    return dp[last_index]

