def pairSum(arr, target):
    """
    Returns True if there are two distinct numbers in the array that add up to the target sum, else False.
    """
    if len(arr) < 2:
        return False

    seen = set()

    for num in arr:
        complement = target - num
        if complement in seen:
            return True
        seen.add(num)

    return False

