def minPathSum(grid):
    """
    Find the minimum path sum from top-left to bottom-right corner in a grid.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize the first row
    for j in range(1, n):
        grid[0][j] += grid[0][j - 1]

    # Initialize the first column
    for i in range(1, m):
        grid[i][0] += grid[i - 1][0]

    # Update the cost for each cell in the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            grid[i][j] += min(grid[i - 1][j], grid[i][j - 1])

    return grid[m - 1][n - 1]

