def decipher_message(encoded_message: str) -> str:
    """
    Decipher the encoded message by shifting each character back by one position in the alphabet.
    If the character is 'a', it wraps around to 'z'.

    Args:
    encoded_message (str): The encoded message containing only lowercase English letters.

    Returns:
    str: The original message.
    """
    deciphered_message = []
    for char in encoded_message:
        if char == 'a':
            deciphered_message.append('z')
        else:
            deciphered_message.append(chr(ord(char) - 1))
    return ''.join(deciphered_message)

