from heapq import heappop, heappush
from collections import Counter

def rearrange_string(text):
    """
    Rearrange characters in the string so that no two adjacent characters are the same.
    If not possible, return an empty string.
    """
    count = Counter(text)
    max_heap = []
    for char, freq in count.items():
        heappush(max_heap, (-freq, char))

    prev_char, prev_freq = None, 0
    result = []

    while max_heap or prev_freq:
        if prev_freq:
            if not max_heap:
                return ""

        freq, char = heappop(max_heap)
        result.append(char)

        if prev_freq < 0:
            heappush(max_heap, (prev_freq, prev_char))

        prev_char, prev_freq = char, freq + 1

    return ''.join(result)

