def min_operations_to_non_decreasing(arr):
    """
    Returns the minimum number of operations required to make the array non-decreasing.
    """
    if not arr:
        return 0

    operations = 0
    for i in range(1, len(arr)):
        if arr[i] < arr[i - 1]:
            operations += arr[i - 1] - arr[i]
            arr[i] = arr[i - 1]

    return operations

