def smallest_lexicographical_array(n, d, a):
    swaps = 0
    for i in range(n):
        if swaps >= d:
            break
        min_index = i
        for j in range(i + 1, n):
            if a[j] < a[min_index]:
                min_index = j

        if min_index != i:
            a[i], a[min_index] = a[min_index], a[i]
            swaps += 1

    return a

