from collections import defaultdict, Counter

def max_successful_purchases(T, test_cases):
    results = []

    for i in range(T):
        N, U = test_cases[i]['N'], test_cases[i]['U']
        products = test_cases[i]['products']
        user_attempts = test_cases[i]['user_attempts']

        product_availability = {idx + 1: products[idx][1] for idx in range(N)}
        attempt_dict = defaultdict(list)

        for user in user_attempts:
            P_i, T_i = user
            attempt_dict[(P_i, T_i)].append(user)

        successful_purchases = 0

        for key, attempts in attempt_dict.items():
            P_i = key[0]

            if product_availability[P_i] > 0:
                successful_purchases += 1
                product_availability[P_i] -= 1

        results.append(successful_purchases)

    return results

