def longest_balanced_substring(s):
    """
    Returns the length of the longest balanced substring containing
    properly nested parentheses.
    """
    max_length = 0
    stack = [-1]

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

