    results = []

    for i in range(t):
        n, sequence = data[i]
        if n == 0:
            results.append(0)
            continue

        sequence.sort()
        max_length = 1
        current_length = 1

        for j in range(1, n):
            if sequence[j] == sequence[j - 1] + 1:
                current_length += 1
                max_length = max(max_length, current_length)
            elif sequence[j] != sequence[j - 1]: 
                current_length = 1

        results.append(max_length)

    return results

