def count_people_in_front_with_greater_or_equal_height(heights):
    """
    Returns a list where each index contains number of people in front with height >= heights[i]
    """
    result = [0] * len(heights)

    for i in range(1, len(heights)):
        count = 0
        for j in range(i):
            if heights[j] >= heights[i]:
                count += 1
        result[i] = count

    return result

