def longest_subarray_with_two_distinct(nums):
    """
    Returns the length of the longest subarray that contains no more than two distinct numbers.
    """
    n = len(nums)
    if n == 0:
        return 0

    # Dictionary to store count of elements
    counts = {}
    left = 0
    max_length = 0

    for right in range(n):
        # Add the right element to the dictionary
        if nums[right] in counts:
            counts[nums[right]] += 1
        else:
            counts[nums[right]] = 1

        # While we have more than 2 distinct elements, shrink the window
        while len(counts) > 2:
            counts[nums[left]] -= 1
            if counts[nums[left]] == 0:
                del counts[nums[left]]
            left += 1

        # Update the max_length
        max_length = max(max_length, right - left + 1)

    return max_length

