def floyd_warshall(graph):
    """
    Implements the Floyd-Warshall algorithm to find the shortest paths between all pairs of vertices.

    Parameters:
    graph (list of list of int/float): The input adjacency matrix where graph[i][j] is the weight of the edge from i to j.

    Returns:
    list of list of int/float: A matrix where the element at index (i, j) represents the shortest distance from vertex i to vertex j.
    """
    n = len(graph)
    dist = [[graph[i][j] for j in range(n)] for i in range(n)]

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

