def containsNearbySum(nums, target, k):
    """
    Determines if there are two distinct indices i and j in the array such
    that nums[i] + nums[j] = target and the absolute difference between
    i and j is at most k.

    Args:
    nums: List[int] - List of integers.
    target: int - The target sum.
    k: int - The maximum allowed absolute difference between indices.

    Returns:
    bool - True if such elements exist, otherwise False.
    """
    num_dict = {}
    for i, num in enumerate(nums):
        if (target - num) in num_dict:
            for j in num_dict[target - num]:
                if abs(i - j) <= k:
                    return True
        if num in num_dict:
            num_dict[num].append(i)
        else:
            num_dict[num] = [i]
    return False

