    """
    Returns the length of the longest substring that contains at most two different characters.
    """
    n = len(s)
    if n == 0:
        return 0

    # Use a sliding window approach
    left = 0
    right = 0
    max_length = 0
    char_count = {}

    while right < n:
        if len(char_count) <= 2:
            char_count[s[right]] = char_count.get(s[right], 0) + 1
            right += 1

        if len(char_count) > 2:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_length = max(max_length, right - left)

