def min_cost_to_paint_houses(cost):
    if not cost:
        return 0

    n = len(cost)
    k = len(cost[0])

    if k == 1 and n > 1:
        return -1

    for i in range(1, n):
        for j in range(k):
            cost[i][j] += min(cost[i-1][l] for l in range(k) if l != j)

    return min(cost[-1])

# Example
cost = [
    [1, 5, 3],
    [2, 9, 4]
]
print(min_cost_to_paint_houses(cost))  # should output 5

