def plant_flowers(n, d):
    if d > n - 1:
        return "NO"

    # If it's possible to plant the flowers
    flower_types = list(range(1, d + 1))  # Create a list of d different flowers
    result = []

    for i in range(n - 1):
        result.append(flower_types[i % d])

    return f"YES\n{' '.join(map(str, result))}"

