def max_unique_subarrays(arr, k):
    """
    Returns the maximum number of unique subarrays of length k.
    """
    if k > len(arr) or k == 0:
        return 0

    unique_subarrays = set()

    for i in range(len(arr) - k + 1):
        subarray = tuple(arr[i:i + k])
        unique_subarrays.add(subarray)

    return len(unique_subarrays)

