    """
    Returns the number of pairs (i, j) such that i < j and arr[i] + arr[j] == x
    """
    count = 0
    seen = {}

    for i, num in enumerate(arr):
        target = x - num
        if target in seen:
            count += seen[target]

        if num in seen:
            seen[num] += 1
        else:
            seen[num] = 1

    return count

