def min_adjacent_swaps(arr):
    """
    Returns the minimum number of adjacent swaps required to sort the array.
    """
    n = len(arr)
    swaps = 0

    # Bubble Sort implementation
    for i in range(n - 1):
        for j in range(n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j] # swap
                swaps += 1

    return swaps

