def longest_increasing_sequence(arr: list[int]) -> int:
    import bisect

    if not arr:
        return 0

    subsequence = []

    for x in arr:
        pos = bisect.bisect_left(subsequence, x)
        if pos == len(subsequence):
            subsequence.append(x)
        else:
            subsequence[pos] = x

    return len(subsequence)

