def compress_string_length(s):
    """
    Compresses the given string using the specified rule and returns the length of the compressed string if it is 
    shorter than the original string, otherwise returns the length of the original string.
    """
    if not s:
        return 0

    compressed_string = []
    count_consecutive = 0

    for i in range(len(s)):
        count_consecutive += 1

        if i + 1 >= len(s) or s[i] != s[i + 1]:
            compressed_string.append(s[i] + str(count_consecutive))
            count_consecutive = 0

    compressed_string = ''.join(compressed_string)

    if len(compressed_string) >= len(s):
        return len(s)
    else:
        return len(compressed_string)

