def max_height_difference(n, heights):
    # Initialize the maximum difference as -1 (special case value if no valid pair exists)
    max_diff = -1

    # Iterate regions between peaks find potential peaks inbetween and calculate maximum difference
    for i in range(1, n-1):
        if heights[i] > heights[i-1] and heights[i] > heights[i+1]:
            left = min(heights[:i])
            right = min(heights[i+1:])
            max_diff = max(max_diff, heights[i] - left, heights[i] - right)

    return max_diff

