def min_cost_to_buy_pizzas(N, M, deals):
    # Initialize an array to store the minimum cost to buy exactly i pizzas
    dp = [float('inf')] * (N + 1)
    dp[0] = 0  # Base case: it costs nothing to buy 0 pizzas

    # Process each deal from each pizzeria
    for deal in deals:
        k, p = deal  # k is the number of pizzas, p is the cost
        for i in range(k, N + 1):
            dp[i] = min(dp[i], dp[i - k] + p)

    return dp[N] if dp[N] != float('inf') else -1

