def four_sum(nums, target_sum):
    """
    Find all unique quadruples in the nums list that sum up to target_sum.

    :param nums: List[int] - List of integers
    :param target_sum: int - The target sum for the quadruples
    :return: List[List[int]] - List of unique quadruples
    """
    nums.sort()
    res = []
    n = len(nums)

    for i in range(n - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue
            left, right = j + 1, n - 1
            while left < right:
                quad_sum = nums[i] + nums[j] + nums[left] + nums[right]
                if quad_sum == target_sum:
                    res.append([nums[i], nums[j], nums[left], nums[right]])
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif quad_sum < target_sum:
                    left += 1
                else:
                    right -= 1
    return res

