def min_overall_difficulty(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        difficulties = test_cases[i][1]

        min_difficulty = float('inf')

        for perm in permutations(difficulties):
            current_difficulty = 0
            for j in range(1, N):
                current_difficulty += abs(perm[j] - perm[j-1])

            if current_difficulty < min_difficulty:
                min_difficulty = current_difficulty

        results.append(min_difficulty)

    return results

