def longest_palindromic_subsequence(S):
    """
    Returns the length of the longest palindromic subsequence in string S.
    """
    n = len(S)
    dp = [[0] * n for _ in range(n)]

    # Each single letter is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Process substrings of increasing length
    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if S[i] == S[j]:
                dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # The answer is the length of the longest subsequence found from 0 to n-1
    return dp[0][n - 1]

