def remove_duplicate_letters(s):
    """
    Removes duplicate letters from the string s and returns 
    the lexicographically smallest result with all unique letters.
    """
    last_occurrence = {c: i for i, c in enumerate(s)}
    stack = []
    seen = set()

    for i, c in enumerate(s):
        if c not in seen:
            while stack and c < stack[-1] and i < last_occurrence[stack[-1]]:
                seen.remove(stack.pop())
            stack.append(c)
            seen.add(c)

    return ''.join(stack)

