def longest_descending_block(heights):
    """
    Returns the length of the longest block of consecutive buildings where each building
    is strictly shorter than the previous one.
    """
    if not heights:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(heights)):
        if heights[i] < heights[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

