def count_peaks(n, a):
    """
    Returns the number of peak elements in the array.
    """
    if n == 1:
        return 1

    peaks = 0

    for i in range(n):
        if i == 0:
            if a[i] >= a[i + 1]:
                peaks += 1
        elif i == n - 1:
            if a[i] >= a[i - 1]:
                peaks += 1
        else:
            if a[i] >= a[i - 1] and a[i] >= a[i + 1]:
                peaks += 1

    return peaks

