secure_solution:
def rearrange_pearls(n, pearls):
    from collections import Counter
    import heapq

    if n == 1:
        return ("Possible", pearls)

    # Count the frequency of each pearl type
    count = Counter(pearls)
    max_count = max(count.values())

    # If any pearl type appears more than (n + 1) // 2 times, it's impossible to rearrange
    if max_count > (n + 1) // 2:
        return ("No solution",)

    heap = [(-freq, pearl) for pearl, freq in count.items()]
    heapq.heapify(heap)

    result = [0] * n
    index = 0

    while heap:
        freq, pearl = heapq.heappop(heap)
        freq = -freq

        for _ in range(freq):
            if index >= n:
                index = 1
            result[index] = pearl
            index += 2

    return ("Possible", result)

