def minCostPath(costs):
    if not costs or not costs[0]:
        return 0

    m, n = len(costs), len(costs[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = costs[0][0]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + costs[i][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + costs[0][j]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + costs[i][j]

    return dp[m-1][n-1]

