def robot_returns(moves: str) -> bool:
    """
    Determine if the robot returns to the origin after the given sequence of moves.
    """
    x, y = 0, 0
    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
    return x == 0 and y == 0

