from typing import List

def maxViewableBuildings(heights: List[int], L: int) -> int:
    n = len(heights)
    max_count = 0

    for i in range(n):
        count = 1 # start by including the current building itself
        for j in range(1, L+1):
            if i - j >= 0 and heights[i - j] <= heights[i]:
                count += 1
            if i + j < n and heights[i + j] <= heights[i]:
                count += 1
        max_count = max(max_count, count)

    return max_count

