from collections import defaultdict, deque

def find_min_time(tasks):
    """
    Returns the minimum time required to complete all tasks considering dependencies.
    If there's a cyclic dependency, returns -1.
    """
    # Create adjacency list and indegree count
    adj_list = defaultdict(list)
    indegree = {task[0]: 0 for task in tasks}
    duration = {task[0]: task[1] for task in tasks}

    for task in tasks:
        for dep in task[2]:
            adj_list[dep].append(task[0])
            indegree[task[0]] += 1

    # Initialize queue with tasks having no dependencies
    queue = deque()
    for task in tasks:
        if indegree[task[0]] == 0:
            queue.append((task[0], task[1]))

    total_time = 0
    completed = 0
    task_count = len(tasks)
    time_taken = {task[0]: 0 for task in tasks}

    while queue:
        t, current_time = queue.popleft()
        total_time = max(total_time, current_time)
        completed += 1

        for neighbor in adj_list[t]:
            indegree[neighbor] -= 1
            time_taken[neighbor] = max(time_taken[neighbor], current_time + duration[neighbor])
            if indegree[neighbor] == 0:
                queue.append((neighbor, time_taken[neighbor]))

    # Check if all tasks were completed
    if completed == task_count:
        return total_time
    else:
        return -1

