def find_min_difference(weights):
    """
    Returns the minimum possible absolute difference between the sum of the weights of the two groups.
    """
    total_sum = sum(weights)
    n = len(weights)

    # Initialize a boolean DP table where dp[i][j] is True if 
    # a subset with sum j can be formed using the first i elements.
    dp = [[False] * (total_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(total_sum + 1):
            if j >= weights[i-1]:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-weights[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    min_diff = float('inf')
    for j in range(total_sum // 2 + 1):
        if dp[n][j]:
            min_diff = min(min_diff, total_sum - 2 * j)

    return min_diff

