def count_pairs_with_sum(N, T, array):
    """
    Returns the number of distinct pairs (i, j) such that array[i] + array[j] equals T.
    """
    counter = {}
    pair_count = 0

    for num in array:
        complement = T - num
        if complement in counter:
            pair_count += counter[complement]

        if num in counter:
            counter[num] += 1
        else:
            counter[num] = 1

    return pair_count

