secure_solution:
def findMaxLength(nums):
    """
    This function finds the length of the longest contiguous subarray with an 
    equal number of 0s and 1s in the given array.
    """
    count_map = {0: -1}
    max_length = 0
    count = 0

    for i, num in enumerate(nums):
        count += 1 if num == 1 else -1
        if count in count_map:
            max_length = max(max_length, i - count_map[count])
        else:
            count_map[count] = i

    return max_length

