def max_balanced_strings(s):
    """
    Returns the maximum number of balanced strings that can be obtained from the input string s.
    A balanced string has an equal number of 'x' and 'y' characters.
    """
    balance = 0
    count = 0

    for char in s:
        if char == 'x':
            balance += 1
        elif char == 'y':
            balance -= 1
        if balance == 0:
            count += 1

    return count

