secure_solution:
def text_editor(commands: list) -> list:
    result = []
    current_text = ""
    history = []

    for command in commands:
        if command.startswith("APPEND"):
            to_append = command.split()[1]
            history.append(current_text)
            current_text += to_append
        elif command.startswith("DELETE"):
            k = int(command.split()[1])
            history.append(current_text)
            current_text = current_text[:-k]
        elif command.startswith("PRINT"):
            k = int(command.split()[1])
            result.append(current_text[k-1])
        elif command == "UNDO":
            current_text = history.pop()

    return result

