def subset_sum_exists(arr, target):
    """
    Determines if there exists a subset of the array `arr` whose sum is exactly `target`.
    """
    n = len(arr)

    # Using dynamic programming to solve the subset sum problem
    dp = [False] * (target + 1)
    dp[0] = True  # There's always a subset with sum 0 (the empty subset)

    for num in arr:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    return "YES" if dp[target] else "NO"

