def evaluate_expression(expression):
    """
    Evaluates a mathematical expression involving non-negative integers and the operators + and *.
    :param expression: str, a string representation of the expression
    :return: int, the result of the evaluation
    """
    if not expression:
        return 0

    tokens = []
    num = 0
    operation = '+'

    for i in range(len(expression)):
        if expression[i].isdigit():
            num = num * 10 + int(expression[i])

        if not expression[i].isdigit() or i == len(expression) - 1:
            if operation == '+':
                tokens.append(num)
            elif operation == '*':
                tokens.append(tokens.pop() * num)

            num = 0
            operation = expression[i]

    return sum(tokens)

