def compute_final_price(base_price, rules):
    """
    Computes the final price of a product based on base price and adjustment rules.
    """
    final_price = base_price

    for lower_bound, upper_bound, adjustment in rules:
        if lower_bound <= final_price <= upper_bound:
            final_price += adjustment

    return final_price

def can_convert_in_one_operation(s, t):
    m, n = len(s), len(t)

    # Case 1: Length difference is more than 1
    if abs(m - n) > 1:
        return "NO"

    # Case 2: Lengths are equal, check for one replacement
    if m == n:
        differences = sum(1 for a, b in zip(s, t) if a != b)
        return "YES" if differences == 1 else "NO"

    # Case 3: One character insertion or removal
    if m > n:
        # Check if t can be obtained by removing one character from s
        for i in range(m):
            if s[:i] + s[i+1:] == t:
                return "YES"
    elif n > m:
        # Check if s can be obtained by removing one character from t
        for i in range(n):
            if t[:i] + t[i+1:] == s:
                return "YES"

    return "NO"

