def longest_distinct_subarray(views):
    """
    Returns the length of the longest contiguous subarray that contains only distinct elements.
    """
    start = 0
    max_length = 0
    seen = {}

    for end in range(len(views)):
        if views[end] in seen:
            start = max(start, seen[views[end]] + 1)
        seen[views[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

