def determine_winner(S):
    """
    Determine whether Pia or Tony will win the game given the initial string.
    """

    # Count frequencies of each character in the string
    counts = {}
    for char in S:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1

    # Count the number of characters with odd frequencies
    odd_count = sum(1 for count in counts.values() if count % 2 == 1)

    # If the number of odd frequency characters is even or zero, Pia wins. Otherwise, Tony wins.
    if odd_count % 2 == 0:
        return "Pia"
    else:
        return "Tony"

