def minSubsetSumDifference(nums):
    """
    Given a list of integers, partition the list into two subsets such that the difference
    between the sums of the subsets is minimized, and return the minimum possible difference.
    """
    total_sum = sum(nums)
    n = len(nums)
    target = total_sum // 2

    dp = [False] * (target + 1)
    dp[0] = True

    for num in nums:
        for j in range(target, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]

    for i in range(target, -1, -1):
        if dp[i]:
            subset_sum1 = i
            break

    subset_sum2 = total_sum - subset_sum1
    return abs(subset_sum2 - subset_sum1)

