def length_of_shortest_substring(s):
    distinct_chars = set(s)
    distinct_count = len(distinct_chars)
    n = len(s)

    min_length = n

    for i in range(n):
        seen_chars = set()
        for j in range(i, n):
            seen_chars.add(s[j])
            if len(seen_chars) == distinct_count:
                min_length = min(min_length, j - i + 1)
                break

    return min_length

def robot_path(n, m, commands, dangers):
    """
    Determines if the robot can safely complete a sequence of commands in a grid.

    :param n: Number of rows in the grid.
    :param m: Number of columns in the grid.
    :param commands: List of single-character strings representing the robot's movements.
    :param dangers: List of tuples representing the dangerous cells on the grid.
    :return: A tuple: (can_complete_safely, final_position).
    """
    # Starting position
    current_position = [0, 0]

    # Convert dangers list to a set for O(1) lookups
    danger_set = set(dangers)

    # Define movements for each command
    movements = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

    # Traverse the commands
    for command in commands:
        if command in movements:
            current_position[0] += movements[command][0]
            current_position[1] += movements[command][1]

        # Check if the new position is outside the grid
        if not (0 <= current_position[0] < n and 0 <= current_position[1] < m):
            return (False, tuple(current_position))

        # Check if the new position is in the danger set
        if tuple(current_position) in danger_set:
            return (False, tuple(current_position))

    return (True, tuple(current_position))

