def final_position(x, y, commands):
    """
    Returns the final coordinates of the robot after executing the sequence of commands.

    Parameters:
    x (int): starting x-coordinate
    y (int): starting y-coordinate
    commands (str): sequence of commands

    Returns:
    Tuple[int, int]: final (x, y) coordinates
    """
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1
    return x, y

