def minutes_before_battery_runs_out(b, m, app_sequence):
    """
    Calculate the number of minutes the battery will last.

    :param b: initial battery percentage (1 ≤ b ≤ 100)
    :param m: number of minutes to consider (1 ≤ m ≤ 1000)
    :param app_sequence: list of applications running each minute (1 ≤ ai ≤ 100)
    :return: the number of minutes battery will last
    """
    for minute in range(m):
        apps_running = app_sequence[minute]
        if apps_running == 1:
            consumption_rate = 1
        elif apps_running == 2:
            consumption_rate = 2
        elif apps_running == 3:
            consumption_rate = 4
        elif apps_running == 4:
            consumption_rate = 8
        elif apps_running == 5:
            consumption_rate = 16
        else:
            consumption_rate = 16 * (2 ** (apps_running - 5))

        b -= consumption_rate
        if b <= 0:
            return minute + 1

    return m

