def distribute_food(test_cases):
    results = []
    for case in test_cases:
        Y, VIPs, Regulars, Newcomers = case
        required_vips = VIPs * 150
        required_regulars = Regulars * 80
        required_newcomers = Newcomers * 40

        total_required = required_vips + required_regulars + required_newcomers

        if total_required <= Y:
            results.append(f"{required_vips} {required_regulars} {required_newcomers}")
        else:
            results.append("Not Possible")

    return results

