MOD = 10**9 + 7

def unique_paths(N, M, grid):
    # Initialize a DP array with 0s.
    dp = [[0] * M for _ in range(N)]

    # If the start or end cell is blocked, return 0.
    if grid[0][0] == '#' or grid[N-1][M-1] == '#':
        return 0

    # Starting point
    dp[0][0] = 1

    # Fill the DP array
    for i in range(N):
        for j in range(M):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD

    return dp[-1][-1]

