    """
    Reduces the string based on the given rules until one character remains.
    """
    while len(s) > 1:
        new_s = []
        i = 0
        while i < len(s):
            if i < len(s) - 1:
                if s[i] == s[i + 1]: 
                    new_s.append(s[i])
                else:
                    new_s.append('a' if s[i] == 'a' else 'b')
                i += 2
