def max_presentations(m, books):
    history = []
    science = []
    literature = []

    for i in range(m):
        if books[i] == 1:
            history.append(i + 1)
        elif books[i] == 2:
            science.append(i + 1)
        elif books[i] == 3:
            literature.append(i + 1)

    p = min(len(history), len(science), len(literature))
    presentations = {}

    for i in range(p):
        presentations[i] = (history[i], science[i], literature[i])

    return p, presentations

