def longest_substring_with_one_distinct_char(S, K):
    n = len(S)
    max_len = 0

    for i in range(26):
        char_to_try = chr(i + ord('a'))
        left = 0
        changes = 0

        for right in range(n):
            if S[right] != char_to_try:
                changes += 1

            while changes > K:
                if S[left] != char_to_try:
                    changes -= 1
                left += 1

            max_len = max(max_len, right - left + 1)

    return max_len

