def longest_increasing_substring_length(s):
    """
    Given a string s, returns the length of the longest substring where all the letters appear in increasing alphabetical order.
    """
    if not s:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(s)):
        if s[i] > s[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

