def max_distance(heights):
    """
    Returns the maximum distance the ball can travel when placed on any building.
    """
    max_dist = 1  # At least one building is always there

    for i in range(len(heights)):
        dist = 1
        for j in range(i + 1, len(heights)):
            if heights[j] < heights[j - 1]:
                dist += 1
            else:
                break
        max_dist = max(max_dist, dist)

    return max_dist

