def longest_subarray_with_sum(nums, k):
    """
    Returns the length of the longest subarray whose sum is equal to k.
    """
    prefix_sum_map = {}
    current_sum = 0
    max_length = 0

    for i, num in enumerate(nums):
        current_sum += num

        if current_sum == k:
            max_length = i + 1

        if (current_sum - k) in prefix_sum_map:
            max_length = max(max_length, i - prefix_sum_map[current_sum - k])

        if current_sum not in prefix_sum_map:
            prefix_sum_map[current_sum] = i

    return max_length

