import heapq

def max_cities_visited(n, m, f, roads):
    graph = [[] for _ in range(n + 1)]

    for u, v, d in roads:
        graph[u].append((v, d))
        graph[v].append((u, d))

    # Dijkstra-like approach to find maximum number of cities that can be visited
    pq = [(0, 1)]  # (cost, start)
    visited = set()
    max_fuel = [float('inf')] * (n + 1)
    max_fuel[1] = 0

    while pq:
        current_fuel, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)

        for neighbor, weight in graph[node]:
            next_fuel = current_fuel + weight
            if next_fuel <= f and next_fuel < max_fuel[neighbor]:
                max_fuel[neighbor] = next_fuel
                heapq.heappush(pq, (next_fuel, neighbor))

    return sum(1 for fuel in max_fuel if fuel <= f)

