def evaluate_expression(expression):
    """
    Evaluates a given expression string consisting of non-negative integers and 
    the operators +, -, *, and /. The integer division should truncate toward zero.
    """
    # Split the expression into tokens
    tokens = expression.split()
    # Stack for numbers
    stack = []
    # Variable to keep track of the current operator, default is '+'
    current_op = '+'

    for token in tokens:
        if token.isdigit():
            num = int(token)
            # Perform the operation based on the current operator
            if current_op == '+':
                stack.append(num)
            elif current_op == '-':
                stack.append(-num)
            elif current_op == '*':
                stack.append(stack.pop() * num)
            elif current_op == '/':
                # Integer division should truncate toward zero
                stack.append(int(stack.pop() / num))
        else:
            # Update the current operator
            current_op = token

    # Return the sum of the stack
    return sum(stack)

