def max_non_adjacent_sum(arr):
    if not arr:
        return 0
    if len(arr) == 1:
        return arr[0]
    prev = 0
    curr = 0
    for num in arr:
        new_curr = max(curr, prev + num)
        prev = curr
        curr = new_curr
    return curr

from collections import Counter

def longest_even_palindrome(T, cases):
    if not (1 <= T <= 20):
        return ["Invalid Input"]

    result = []
    for S in cases:
        if not (1 <= len(S) <= 200) or not S.islower():
            result.append("Invalid Input")
            continue

        char_count = Counter(S)
        length = 0

        for count in char_count.values():
            length += (count // 2) * 2

        result.append(str(length))

    return result

