secure_solution:
def equivalent_resistance(resistances, combination):
    """
    Calculate the equivalent resistance for a list of resistances in either series or parallel combination.

    Parameters:
    resistances (list of float or int): List of resistance values.
    combination (str): Either "series" or "parallel" indicating the type of connection.

    Returns:
    float: The equivalent resistance rounded to 2 decimal places.
    """
    if combination == "series":
        return round(sum(resistances), 2)
    elif combination == "parallel":
        return round(1 / sum(1 / r for r in resistances), 2)
    else:
        raise ValueError("Invalid combination type; choose either 'series' or 'parallel'")

