def max_treasures(m, n, grid):
    """
    Returns the maximum number of treasures that can be collected
    by moving from the top-left to the bottom-right of the grid.
    """
    if grid[0][0] == 'O' or grid[m-1][n-1] == 'O':
        return -1

    # DP table to store the maximum treasures collected up to each cell
    dp = [[-1] * n for _ in range(m)]
    dp[0][0] = 1 if grid[0][0] == 'T' else 0

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] != 'O' and dp[0][j-1] != -1:
            dp[0][j] = dp[0][j-1] + (1 if grid[0][j] == 'T' else 0)
        else:
            dp[0][j] = -1

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] != 'O' and dp[i-1][0] != -1:
            dp[i][0] = dp[i-1][0] + (1 if grid[i][0] == 'T' else 0)
        else:
            dp[i][0] = -1

    # Fill the rest of the dp table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 'O':
                dp[i][j] = -1
            else:
                max_treasure = max(dp[i-1][j], dp[i][j-1])
                if max_treasure != -1:
                    dp[i][j] = max_treasure + (1 if grid[i][j] == 'T' else 0)
                else:
                    dp[i][j] = -1

    return dp[m-1][n-1]

# Example
