def longest_valid_parentheses(s):
    """
    Finds the length of the longest valid parentheses substring.

    Parameters:
    s (str): A string consisting of '(' and ')'.

    Returns:
    int: The length of the longest valid parentheses substring.
    """
    max_len = 0
    stack = []
    start = -1

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            if stack:
                stack.pop()
                if stack:
                    max_len = max(max_len, i - stack[-1])
                else:
                    max_len = max(max_len, i - start)
            else:
                start = i

    return max_len

