from datetime import datetime

def parse_work_log(work_log: List[dict]) -> Dict[str, float]:
    employee_hours = {}

    for entry in work_log:
        employee_id = entry["employee_id"]
        start_time = datetime.strptime(entry["date"] + " " + entry["start_time"], "%Y-%m-%d %H:%M")
        end_time = datetime.strptime(entry["date"] + " " + entry["end_time"], "%Y-%m-%d %H:%M")

        time_diff = (end_time - start_time).total_seconds() / 3600  # convert to hours

        if employee_id in employee_hours:
            employee_hours[employee_id] += time_diff
        else:
            employee_hours[employee_id] = time_diff

    # Round to 2 decimal places
    for employee in employee_hours:
        employee_hours[employee] = round(employee_hours[employee], 2)

    return employee_hours

