def count_unique_elements(N, M, array, queries):
    element_count = {}

    for num in array:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    for query in queries:
        q, x, k = query
        if x in element_count:
            count_x = element_count[x]
            del element_count[x]
            if q == 1:
                x_new = x + k
            else:
                x_new = x - k

            if x_new in element_count:
                element_count[x_new] += count_x
            else:
                element_count[x_new] = count_x

    return len(element_count)

