def shortest_substring_length(s):
    """
    Returns the length of the shortest substring that contains at least one 'a', one 'b', and one 'c'.
    """
    n = len(s)
    if n < 3:
        return 0

    min_len = float('inf')
    char_count = {'a': 0, 'b': 0, 'c': 0}
    start = 0

    for end in range(n):
        if s[end] in char_count:
            char_count[s[end]] += 1

        while all(char_count.values()):
            min_len = min(min_len, end - start + 1)
            if s[start] in char_count:
                char_count[s[start]] -= 1
            start += 1

    if min_len == float('inf'):
        return 0
    return min_len

