def longest_special_sequence(n, notes):
    if n == 0:
        return 0

    max_len = 1  # to store the length of the longest special sequence
    current_len = 1

    # Check for the longest rising sequence
    for i in range(1, n):
        if notes[i] > notes[i - 1]:
            current_len += 1
        else:
            max_len = max(max_len, current_len)
            current_len = 1
    max_len = max(max_len, current_len)

    current_len = 1
    # Check for the longest falling sequence
    for i in range(1, n):
        if notes[i] < notes[i - 1]:
            current_len += 1
        else:
            max_len = max(max_len, current_len)
            current_len = 1
    max_len = max(max_len, current_len)

    return max_len

