def min_energy_cost(matrix):
    """
    Returns the minimum total energy cost to travel from the top-left
    corner to the bottom-right corner of a given MxN matrix where you
    can only move down or right.
    """
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])
    dp = [[0 for _ in range(n)] for _ in range(m)]

    dp[0][0] = matrix[0][0]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + matrix[i][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + matrix[0][j]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = matrix[i][j] + min(dp[i-1][j], dp[i][j-1])

    return dp[m-1][n-1]

