def detect_negative_cycle(graph, source):
    """
    Determine if the graph contains a negative-weight cycle reachable from the source.

    Args:
    graph (dict): A graph represented as an adjacency list with edge weights.
    source (str): The starting vertex.

    Returns:
    bool: True if a negative weight cycle exists reachable from the source, False otherwise.
    """
    # Initialize distances from source to all other vertices as infinite
    # and distance to the source itself as 0.
    distances = {vertex: float('inf') for vertex in graph}
    distances[source] = 0

    # Number of vertices
    V = len(graph)

    # Relax all edges V-1 times
    for _ in range(V - 1):
        for u in graph:
            for v in graph[u]:
                if distances[u] != float('inf') and distances[u] + graph[u][v] < distances[v]:
                    distances[v] = distances[u] + graph[u][v]

    # Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if distances[u] != float('inf') and distances[u] + graph[u][v] < distances[v]:
                return True  # Found a negative cycle

    return False

