def can_merge_strings(s, part1, part2):
    """
    Determines if the string `s` can be formed by interleaving characters from `part1` and `part2`
    while maintaining the relative order of characters in both `part1` and `part2`.
    """
    n, m, k = len(s), len(part1), len(part2)

    if n != m + k:
        return False

    dp = [[False] * (k + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(m + 1):
        for j in range(k + 1):
            if i > 0 and s[i + j - 1] == part1[i - 1]:
                dp[i][j] = dp[i][j] or dp[i - 1][j]
            if j > 0 and s[i + j - 1] == part2[j - 1]:
                dp[i][j] = dp[i][j] or dp[i][j - 1]

    return dp[m][k]

