def count_pairs(heights):
    """
    Returns the number of pairs (i, j) with i < j 
    such that the student at index i is taller than the student at index j.
    """
    n = len(heights)
    count = 0

    for i in range(n):
        for j in range(i + 1, n):
            if heights[i] > heights[j]:
                count += 1

    return count

