secure_solution:
def is_one_edit_distance(s, t):
    """
    Check if it's possible to transform one string into another string by inserting, deleting, 
    or replacing at most one character.
    """
    m, n = len(s), len(t)

    if abs(m - n) > 1:
        return False

    if m > n:
        return is_one_edit_distance(t, s)

    i, shift = 0, n - m
    while i < m and s[i] == t[i]:
        i += 1
    if i == m:
        return shift != 0
    if shift == 0:
        i += 1
    while i < m and s[i] == t[i + shift]:
        i += 1

    return i == m

# Example usage:
S = "pale"
T = "ple"
print("true" if is_one_edit_distance(S, T) else "false")

