def can_distribute_tokens(m, aA, aB, bA, bB):
    total_tokens = aA + aB + bA + bB
    if total_tokens < m:
        return "NO", None

    for x in range(max(0, m - aB - bA - bB), min(aA, m) + 1):
        for y in range(max(0, m - x - bA - bB), min(aB, m - x) + 1):
            remaining = m - x - y
            if remaining >= 0 and remaining <= bA + bB:
                for p in range(max(0, remaining - bB), min(bA, remaining) + 1):
                    q = remaining - p
                    if q >= 0 and q <= bB:
                        return "YES", (x, y, p, q)

    return "NO", None

