from typing import List

def count_paths_with_obstacles(grid: List[List[int]]) -> int:
    n = len(grid)

    # If the starting or ending point is obstructed, there's no valid path
    if grid[0][0] == 1 or grid[n-1][n-1] == 1:
        return 0

    # Create a dp array
    dp = [[0] * n for _ in range(n)]

    # Initialize the starting point
    dp[0][0] = 1

    # Fill the dp array
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    # The answer is in the bottom-right corner of the dp array
    return dp[n-1][n-1]

