    # Fill the dp array
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    # The answer is in the bottom-right corner of the dp array
    return dp[n-1][n-1]

