from collections import Counter

def find_winner(votes):
    """
    Returns the candidate with the most votes, or a list of candidates sorted 
    alphabetically in case of a tie. If no votes are cast, returns "No votes".
    """
    if not votes:
        return "No votes"

    vote_count = Counter(votes)
    max_votes = max(vote_count.values())
    winners = [candidate for candidate, count in vote_count.items() if count == max_votes]

    if len(winners) == 1:
        return winners[0]
    else:
        return sorted(winners)

