def length_of_longest_substring(s):
    """
    Returns the length of the longest substring containing only distinct characters.
    """
    n = len(s)
    if n == 0:
        return 0

    max_len = 0
    start = 0
    char_index_map = {}

    for end in range(n):
        if s[end] in char_index_map:
            start = max(start, char_index_map[s[end]] + 1)
        char_index_map[s[end]] = end
        max_len = max(max_len, end - start + 1)

    return max_len

