def can_be_sorted(n, k, array, multipliers):
    import itertools

    # Check every possible combination of applying one multiplier to each element
    for combination in itertools.product(multipliers, repeat=n):
        # Apply the combination of multipliers to the array
        modified_array = [array[i] * combination[i] for i in range(n)]

        # Check if the modified array is sorted
        if all(modified_array[i] <= modified_array[i+1] for i in range(n-1)):
            return "YES"

    return "NO"

