def min_moves_to_remove_stars(s):
    """
    Returns the minimum number of moves to make `s` consist only of lowercase English letters.
    """
    if not s:
        return 0

    moves = 0
    i = 0

    while i < len(s):
        if s[i] == '*':
            moves += 1
            i += 2
        else:
            i += 1

    return moves

