def harmonic_sum(n: int) -> float:
    """
    Returns the sum of the first n terms of the harmonic series.
    """
    if n <= 0:
        raise ValueError('n must be a positive integer')

    total = 0.0
    for i in range(1, n + 1):
        total += 1 / i

    return total

