def lexicographically_smallest_string(s, k):
    """
    Returns the lexicographically smallest string that can be obtained
    by choosing from the first k characters and appending them to the end.
    """
    if k == 1:
        smallest_string = s
        for i in range(1, len(s)):
            rotated = s[i:] + s[:i]
            if rotated < smallest_string:
                smallest_string = rotated
        return smallest_string
    else:
        return ''.join(sorted(s))

