secure_solution:
def time_complexity(code_snippet):
    """
    Analyzes nested loops in the given pseudo-code and returns the overall time complexity in Big-O notation.

    Parameters:
    code_snippet (str): A string representing the pseudo-code to analyze.

    Returns:
    str: The overall time complexity in Big-O notation.
    """
    # Split the code into lines
    lines = code_snippet.strip().split('\n')

    # Initialize a dictionary to count loop variables
    loop_count = {}

    # Iterate over each line of code
    for line in lines:
        line = line.strip()

        # Only consider lines that start with "for"
        if line.startswith("for"):
            # Determine the loop variable and bounds
            if "1..N" in line:
                variable = 'N'
            elif "1..M" in line:
                variable = 'M'

            # Count the nested loops for each variable
            if variable in loop_count:
                loop_count[variable] += 1
            else:
                loop_count[variable] = 1

    # Construct the time complexity string
    complexity_terms = []
    for variable, count in loop_count.items():
        if count == 1:
            complexity_terms.append(f"O({variable})")
        else:
            complexity_terms.append(f"O({variable}^{count})")

    # Join the terms with multiplication
    if len(complexity_terms) == 1:
        return complexity_terms[0]
    else:
        return "O(" + " * ".join(term[2:-1] for term in complexity_terms) + ")"

