def final_position(commands):
    """
    Given a string of commands, returns the final coordinates of the robot.

    Args:
    commands (str): A string of commands consisting of 'U', 'D', 'L', 'R'.

    Returns:
    tuple: A tuple of two integers representing the final coordinates (x, y).
    """
    x, y = 0, 0

    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return x, y

