def longest_zigzag_sequence(nums):
    if not nums:
        return 0

    n = len(nums)

    if n == 1:
        return 1

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        if nums[i] > nums[i-1]:
            up[i] = down[i-1] + 1
            down[i] = down[i-1]
        elif nums[i] < nums[i-1]:
            down[i] = up[i-1] + 1
            up[i] = up[i-1]
        else:
            up[i] = up[i-1]
            down[i] = down[i-1]

    return max(up[-1], down[-1])

