def first_non_repeated_char(s: str) -> str:
    """
    Returns the first non-repeated character in the given string s. 
    If all characters are repeated or the string is empty, returns an empty string.
    """
    char_count = {}

    # First pass: Count occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass: Find the first character that has a count of 1
    for char in s:
        if char_count[char] == 1:
            return char

    return ""

