def longest_unique_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_index_map = {}
    max_length = 0
    start_index = 0

    for i, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start_index:
            start_index = char_index_map[char] + 1
        char_index_map[char] = i
        max_length = max(max_length, i - start_index + 1)

    return max_length

import heapq

def palace_builder(n, m, corridors, entrance, throne, locked_rooms):
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in corridors:
        if u not in locked_rooms and v not in locked_rooms:
            graph[u].append((w, v))
            graph[v].append((w, u))

    if entrance in locked_rooms or throne in locked_rooms:
        return "No path"

    # Dijkstra's algorithm initialization
    pq = [(0, entrance)]
    distances = {i: float('inf') for i in range(1, n + 1)}
    distances[entrance] = 0
    visited = set()

    # Dijkstra's algorithm
    while pq:
        current_distance, current_room = heapq.heappop(pq)

        if current_room in visited:
            continue

        visited.add(current_room)

        if current_room == throne:
            return current_distance

        for weight, neighbor in graph[current_room]:
            if neighbor not in visited:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(pq, (distance, neighbor))

    return "No path"

