import re
from collections import defaultdict

def word_frequency(document: str) -> dict:
    frequency = defaultdict(int)
    # Use re.findall to extract words as sequences of alphabetical characters
    words = re.findall(r'[a-zA-Z]+', document)
    for word in words:
        # Convert each word to lowercase and increment its frequency.
        frequency[word.lower()] += 1
    return dict(frequency)

