def max_candies(nums):
    """
    Returns the maximum number of candies that can be collected from the given jars
    without selecting adjacent jars.
    """
    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]

    include = nums[0]
    exclude = 0

    for i in range(1, len(nums)):
        new_exclude = max(include, exclude)

        include = exclude + nums[i]
        exclude = new_exclude

    return max(include, exclude)

