def bookstore_operations(test_cases):
    results = []

    for case in test_cases:
        books = {}
        N, books_data, M, updates, price_range, discount, Q, queries = case

        # Add new books
        for book in books_data:
            ID, price = book
            books[ID] = price

        # Update prices
        for update in updates:
            ID, new_price = update
            if ID in books:
                books[ID] = new_price

        # Apply discount
        L, H = price_range
        discount_factor = (100 - discount) / 100
        for ID in books:
            if L <= books[ID] <= H:
                books[ID] = int(books[ID] * discount_factor)

        # Query total cost
        total_cost = 0
        for query in queries:
            ID = query
            if ID in books:
                total_cost += books[ID]

        results.append(total_cost)

    return results

