def allocate_storage(s1, s2, shipments):
    """
    Allocate storage units to Area A and Area B based on given policy. 

    Parameters:
    s1 (int): Capacity of Area A.
    s2 (int): Capacity of Area B.
    shipments (List[int]): List of integers where each element represents the number of units in each incoming shipment.

    Returns:
    (int, int): A tuple representing the number of units in Area A and Area B respectively after all shipments are processed.
    """
    units_in_A = 0
    units_in_B = 0

    for shipment in shipments:
        if units_in_A < s1:
            if shipment + units_in_A <= s1:
                units_in_A += shipment
                shipment = 0
            else:
                shipment -= (s1 - units_in_A)
                units_in_A = s1

        if shipment > 0 and units_in_B < s2:
            if shipment + units_in_B <= s2:
                units_in_B += shipment
                shipment = 0
            else:
                shipment -= (s2 - units_in_B)
                units_in_B = s2

        if shipment > 0:
            # Remaining shipments are rejected as both areas are full.
            break

    return (units_in_A, units_in_B)

