def find_pairs(lst, k):
    """
    Returns all unique pairs of elements from the list that add up to k.
    Each pair is represented as a tuple (a, b) where a <= b.
    """
    seen = set()
    pairs = set()

    for number in lst:
        target = k - number
        if target in seen:
            pairs.add(tuple(sorted((number, target))))
        seen.add(number)

    return list(pairs)

