def longest_skyline(arr):
    """
    Returns the length of the longest possible skyline that can be formed from the elements of arr
    where each building (height in arr) is greater than the height of the building immediately to its left.
    """
    if not arr:
        return 0

    # This will store the lengths of the longest increasing subsequence ending at each index
    lis = [1] * len(arr)

    for i in range(1, len(arr)):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    return max(lis)

