def longest_distinct_subarray_length(n, arr):
    """
    Returns the length of the longest contiguous subarray with all distinct elements.
    """
    if n == 0:
        return 0

    left = 0
    max_length = 0
    seen = {}

    for right in range(n):
        if arr[right] in seen:
            left = max(left, seen[arr[right]] + 1)
        seen[arr[right]] = right
        max_length = max(max_length, right - left + 1)

    return max_length

