def three_sum(nums, target):
    """
    Returns all unique combinations of three numbers in nums that sum up to target,
    sorted in non-decreasing order. If no such combinations found, returns "No combinations found".
    """
    nums.sort()
    n = len(nums)
    result = set()

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]: 
            continue
        left, right = int(i + 1), int(n - 1)
        while left < right:
            sum_three = nums[i] + nums[left] + nums[right]
            if sum_three == target:
                result.add((nums[i], nums[left], nums[right]))
                while left < right and nums[left] == nums[left + 1]: 
                    left += 1
                while left < right and nums[right] == nums[right - 1]: 
                    right -= 1
                left += 1
                right -= 1
            elif sum_three < target:
                left += 1
            else:
                right -= 1

    if result:
        return sorted(result)
    else:
        return "No combinations found"

