def decode_caesar_cipher(encoded_message: str, shift: int) -> str:
    """
    Decodes an encoded string using the given shift value.
    Handles both uppercase and lowercase letters while leaving non-alphabetic characters unchanged.
    """
    decoded_message = []
    for char in encoded_message:
        if 'a' <= char <= 'z':
            decoded_char = chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
        elif 'A' <= char <= 'Z':
            decoded_char = chr((ord(char) - ord('A') - shift) % 26 + ord('A'))
        else:
            decoded_char = char
        decoded_message.append(decoded_char)
    return ''.join(decoded_message)

