def find_lexicographically_largest_subarray(n, arr):
    """
    Finds the starting and ending indices of the subarray such that reversing it
    makes the array lexicographically larger. If no such subarray exists, returns -1 -1.

    :param n: Length of the array
    :param arr: List of integers
    :return: Tuple of two integers
    """
    start, end = -1, -1
    best_start, best_end = -1, -1

    # Traverse the array to find potential subarray which when reversed makes it lexicographically larger
    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            if start == -1:
                start = i - 1
            end = i
        elif start != -1:
            if best_start == -1 or arr[start:end + 1][::-1] > arr[best_start:best_end + 1][::-1]:
                best_start, best_end = start, end
            start, end = -1, -1

    if start != -1:
        if best_start == -1 or arr[start:end + 1][::-1] > arr[best_start:best_end + 1][::-1]:
            best_start, best_end = start, end

    if best_start == -1:
        return (-1, -1)

    return (best_start + 1, best_end + 1)

