from typing import List

def unique_paths_with_obstacles(grid: List[List[int]]) -> int:
    m = len(grid)
    n = len(grid[0])

    # If the start or end point is an obstacle, return 0 as there is no valid path
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    # Create a DP table to store the number of unique paths to each cell
    dp = [[0] * n for _ in range(m)]

    # Initialize the starting point
    dp[0][0] = 1

    # Fill in the values for the first column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]

    # Fill in the values for the first row
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]

    # Fill in the DP table by checking from top to bottom, left to right
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

