def longest_increasing_subsequence(n, difficulties):
    """
    Returns the length of the longest strictly increasing subsequence of trails.

    :param n: Number of trails (integer)
    :param difficulties: List of integers representing difficulty levels of trails
    :return: Length of longest strictly increasing subsequence (integer)
    """
    if n == 0:
        return 0

    # Initialize the list to store the length of the longest subsequence up to each trail
    lis = [1] * n

    # Compute the LIS values in a bottom-up manner
    for i in range(1, n):
        for j in range(i):
            if difficulties[i] > difficulties[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # The length of the longest increasing subsequence is the maximum value in lis
    return max(lis)

