    recharge_set = set(recharge_points)
    battery = C
    count = 0

    for i, power in enumerate(battery_powers):
        if battery >= power:
            battery -= power
            count += 1
        else:
            break

        if (i + 1) in recharge_set:
            battery = C  # Recharge to full battery

    return count

