from typing import Dict, List

def evaluate_expressions(variables: Dict[str, int], expressions: List[str]) -> List[float]:
    results = []
    for expression in expressions:
        # Create a local environment to evaluate the expression
        local_env = {var: value for var, value in variables.items()}
        try:
            result = eval(expression, {}, local_env)
            results.append(float(result))
        except Exception as e:
            raise ValueError(f"Error evaluating expression '{expression}': {e}")
    return results

