import re

def analyze_log_file(file_path: str) -> dict:
    """
    Analyze a log file to count occurrences of each unique IP address.

    Parameters:
    - file_path (str): Path to the log file

    Returns:
    - dict: A dictionary with IP addresses as keys and their count of occurrences as values
    """
    ip_counts = {}
    try:
        with open(file_path, 'r') as file:
            for line in file:
                match = re.match(r'(\d+\.\d+\.\d+\.\d+)', line)
                if match:
                    ip_address = match.group(1)
                    if ip_address in ip_counts:
                        ip_counts[ip_address] += 1
                    else:
                        ip_counts[ip_address] = 1
    except (FileNotFoundError, PermissionError) as e:
        print(f"Error: {str(e)}")
        raise Exception("File read error") from e

    return ip_counts

