def decrypt(message, shift):
    """
    Decrypts the coded message using the given shift.

    Args:
    message (str): The encoded message.
    shift (int): The amount by which each letter in the message was shifted.

    Returns:
    str: The decoded message.
    """

    decoded_message = []

    for char in message:
        if char.isalpha():
            if char.isupper():
                start = ord('A')
            else:
                start = ord('a')

            original_pos = (ord(char) - start - shift) % 26
            new_char = chr(start + original_pos)
            decoded_message.append(new_char)
        else:
            decoded_message.append(char)

    return ''.join(decoded_message)

