def longest_arith_seq_length(arr):
    from collections import defaultdict

    if not arr:
        return 0

    dp = [defaultdict(int) for _ in range(len(arr))]
    max_length = 1

    for i in range(1, len(arr)):
        for j in range(i):
            diff = arr[i] - arr[j]
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2  # Start a new sequence
            max_length = max(max_length, dp[i][diff])

    return max_length

