def text_editor(commands):
    S = ""
    history = []
    output = []

    for command in commands:
        parts = command.split()
        if parts[0] == "APPEND":
            history.append(S)
            S += parts[1]
        elif parts[0] == "DELETE":
            history.append(S)
            k = int(parts[1])
            S = S[:-k] if k <= len(S) else ""
        elif parts[0] == "PRINT":
            k = int(parts[1])
            if 1 <= k <= len(S):
                output.append(S[k-1])
        elif parts[0] == "UNDO":
            if history:
                S = history.pop()

    return output

