def count_subsets_with_sum(arr, k):
    MOD = 10**9 + 7
    n = len(arr)

    # Initialize dp array
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]
            if arr[i - 1] <= j:
                dp[i][j] += dp[i - 1][j - arr[i - 1]]
                dp[i][j] %= MOD

    return dp[n][k]

