def num_paths(grid):
    """
    Returns the number of different paths from top-left to bottom-right corner
    in a grid, considering blocked cells.
    """
    n = len(grid)
    if n == 0 or grid[0][0] == 0 or grid[n-1][n-1] == 0:
        return 0

    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][n-1]

