def pair_with_target_sum(nums: List[int], target: int) -> bool:
    """
    Determine if there are two distinct integers in the sorted list `nums` whose sum equals the target integer.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]

        if current_sum == target:
            return True
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return False

