def trap(heights):
    """
    Calculate the total amount of water that can be trapped between the buildings.

    :param heights: List of integers representing the heights of the buildings
    :type heights: list[int]
    :return: Maximum amount of trapped water
    :rtype: int
    """
    if not heights:
        return 0

    n = len(heights)
    left, right = 0, n - 1
    left_max, right_max = heights[left], heights[right]
    water_trapped = 0

    while left < right:
