def longest_subsequence_length(grades):
    """
    Returns the length of the longest subsequence where each grade differs by exactly 1 from the previous grade.
    """
    if len(grades) < 2:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(grades)):
        if abs(grades[i] - grades[i-1]) == 1:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

