def suggest_promotion(user_transactions, product_id):
    from collections import Counter

    # Counter to store the count of products bought together with the given product_id
    co_purchase_counter = Counter()

    # Iterate through each user's transactions
    for transactions in user_transactions.values():
        # Iterate through each transaction
        for transaction in transactions:
            if product_id in transaction:
                # Add products to the counter that are bought together with product_id
                for prod in transaction:
                    if prod != product_id:
                        co_purchase_counter[prod] += 1

    # Find the product with the highest frequency, smallest ID in case of tie
    most_common_product = min(co_purchase_counter.items(), key=lambda x: (-x[1], x[0]))

    return most_common_product[0]

