def min_transformations(s: str, t: str, transformations: list) -> int:
    if len(s) != len(t):
        return -1

    # Create mapping from each character in transformations
    transformation_map = {}
    for a, b in transformations:
        if a in transformation_map and transformation_map[a] != b:
            return -1  # Conflicting transformations make the task impossible
        transformation_map[a] = b

    moves = 0
    for char_s, char_t in zip(s, t):
        if char_s == char_t:
            continue # No transformation needed

        current_char = char_s
        transformations = 0
        visited = set()
        while current_char != char_t:
            if current_char in visited:
                return -1  # Loop detected, transformation is impossible
            visited.add(current_char)

            if current_char not in transformation_map:
                return -1  # No way to transform char_s into char_t

            current_char = transformation_map[current_char]
            transformations += 1

        moves += transformations

    return moves

