import heapq
from typing import List, Tuple

def prims_algorithm(graph: List[List[int]]) -> List[Tuple[int, int, int]]:
    n = len(graph)
    if n == 0:
        return []

    visited = [False] * n
    min_heap = [(0, 0, 0)]  # (weight, start_vertex, end_vertex)
    mst_edges = []
    heapq.heapify(min_heap)

    while min_heap and len(mst_edges) < n - 1:
        weight, u, v = heapq.heappop(min_heap)
        if visited[v]:
            continue
        visited[v] = True
        if u != v:
            mst_edges.append((min(u, v), max(u, v), weight))
        for to, w in enumerate(graph[v]):
            if not visited[to] and w > 0:
                heapq.heappush(min_heap, (w, v, to))

    return mst_edges

