def check_tic_tac_toe(moves):
    """
    Determines the outcome of a Tic-Tac-Toe game.

    Args:
    - moves: List of tuples. Each tuple contains a play ('X' or 'O'), and two integers indicating
             the row index (0, 1, or 2) and the column index (0, 1, or 2).

    Returns:
    - A string representing the game's outcome: "X wins", "O wins", "Draw", or "Pending".
    """
    grid = [['' for _ in range(3)] for _ in range(3)]

    for move in moves:
        player, row, col = move
        grid[row][col] = player

    # Check rows
    for row in grid:
        if row[0] == row[1] == row[2] and row[0] != '':
            return f"{row[0]} wins"

    # Check columns
    for col in range(3):
        if grid[0][col] == grid[1][col] == grid[2][col] and grid[0][col] != '':
            return f"{grid[0][col]} wins"

    # Check diagonals
    if grid[0][0] == grid[1][1] == grid[2][2] and grid[0][0] != '':
        return f"{grid[0][0]} wins"
    if grid[0][2] == grid[1][1] == grid[2][0] and grid[0][2] != '':
        return f"{grid[0][2]} wins"

    # Check for pending moves
    for row in grid:
        if '' in row:
            return "Pending"

    # If no winner and no pending moves, it's a draw
    return "Draw"

