def rearrange_string(s):
    """
    Rearranges the input string so that all digits come first, followed by uppercase letters,
    and the parentheses come at the end.

    :param s: str, input string containing digits, uppercase letters, and parentheses.
    :return: str, rearranged string.
    """
    digits = []
    letters = []
    parentheses = []

    for char in s:
        if char.isdigit():
            digits.append(char)
        elif char.isalpha():
            letters.append(char)
        elif char == '(' or char == ')':
            parentheses.append(char)

