def longestSegmentWithTwoColors(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        colors = test_cases[i][1]
        if N == 0:
            results.append(0)
            continue
        left = 0
        right = 0
        color_count = {}
        max_len = 1
        while right < N:
            if colors[right] in color_count:
                color_count[colors[right]] += 1
            else:
                color_count[colors[right]] = 1

            while len(color_count) > 2:
                color_count[colors[left]] -= 1
                if color_count[colors[left]] == 0:
                    del color_count[colors[left]]
                left += 1

            max_len = max(max_len, right - left + 1)
            right += 1
        results.append(max_len)
    return results

