def num_steps_to_reduce_to_one(s):
    """
    Returns the number of steps to reduce a binary number represented by string s to 1.
    """
    steps = 0
    num = int(s, 2)  # Convert binary number to integer

    while num > 1:
        if num % 2 == 0:
            num //= 2
        else:
            num -= 1
        steps += 1

    return steps

