def longest_same_diff_subseq_length(n, arr):
    if n == 2:
        return n

    max_len = 2
    current_len = 2
    current_diff = abs(arr[1] - arr[0])

    for i in range(2, n):
        diff = abs(arr[i] - arr[i-1])
        if diff == current_diff:
            current_len += 1
        else:
            current_diff = diff
            current_len = 2
        if current_len > max_len:
            max_len = current_len

    return max_len

