from typing import List

def distribute_products(weights: List[float], max_capacity: float) -> int:
    if not weights:
        raise ValueError("Products list must not be empty")
    if max_capacity <= 0:
        raise ValueError("Max capacity must be > 0")
    if any(weight <= 0 for weight in weights):
        raise ValueError("Weight of products must be > 0")

    weights.sort(reverse=True)
    bins = 0
    while weights:
        current_bin = 0
        i = 0
        while i < len(weights):
            if current_bin + weights[i] <= max_capacity:
                current_bin += weights[i]
                weights.pop(i)
            else:
                i += 1
        bins += 1
    return bins

