def partition_labels(s):
    """
    Returns an array representing the lengths of parts divided by the rule
    that each letter appears in at most one part.
    """
    last_index = {ch: idx for idx, ch in enumerate(s)}
    partitions = []
    start, end = 0, 0

    for idx, ch in enumerate(s):
        end = max(end, last_index[ch])
        if idx == end:
            partitions.append(end - start + 1)
            start = idx + 1

    return partitions

