def longest_equal_positive_negative_subarray(arr):
    """
    Returns the length of the longest contiguous subarray containing an equal number of positive and negative integers.
    """
    max_len = 0
    sum_index_map = {0: -1}
    sum_val = 0

    for i, value in enumerate(arr):
        if value > 0:
            sum_val += 1
        elif value < 0:
            sum_val -= 1

        if sum_val in sum_index_map:
            max_len = max(max_len, i - sum_index_map[sum_val])
        else:
            sum_index_map[sum_val] = i

    return max_len

