def first_non_repeated_character(s: str) -> Optional[str]:
    """
    Returns the first non-repeated character in the string s.
    If all characters are repeated or the string is empty, returns None.
    Raises TypeError if the input is not a string.
    """
    if not isinstance(s, str):
        raise TypeError("input must be a string")

    char_count = {}

    # First pass to count each character
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Second pass to find the first non-repeated character
    for char in s:
        if char_count[char] == 1:
            return char

    return None

