        if current_sum == query:
            result.append("YES")
            continue

        for i in range(1, n - k + 1):
            current_sum = current_sum - arr[i - 1] + arr[i + k - 1]
            if current_sum == query:
                found = True
                break

        if found:
            result.append("YES")
        else:
            result.append("NO")

