def smallest_lexicographical_order(n, lst):
    """
    Returns the smallest lexicographical order of the list
    after at most one swap operation.
    """
    sorted_lst = sorted(lst)
    if lst == sorted_lst:
        return lst

    for i in range(n):
        if lst[i] != sorted_lst[i]:
            break

    min_pos = i
    for j in range(i + 1, n):
        if lst[j] <= sorted_lst[i] and (j == n - 1 or lst[j] < sorted_lst[i + 1]):
            min_pos = j

    lst[i], lst[min_pos] = lst[min_pos], lst[i]
    return lst

