from collections import deque

def find_shortest_path(m, n, grid):
    # Define possible movements (up, down, left, right)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Locate the start and end positions
    start = None
    end = None
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Set up a queue for BFS and a set to track visited nodes
    queue = deque([(start, 0)])  # (current_position, current_distance)
    visited = set(start)

    while queue:
        (x, y), dist = queue.popleft()
        # If we reached the end position
        if (x, y) == end:
            return dist

        # Explore the neighbors
        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            # Check if the new position is within bounds and valid (not visited, not an obstacle or zombie)
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] not in {'#', 'Z'} and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), dist + 1))

    # If no path found
    return "NO WAY OUT"

