def generate_cryptographic_keys(p: int) -> tuple:
    # Check if p is a prime number
    if not isprime(p):
        return (-1, -1, -1, -1, -1)

    # Find a primitive root for p
    try:
        g = primitive_root(p)
    except ValueError:
        return (-1, -1, -1, -1, -1)

    # Generate private keys for Alice and Bob
    private_key_alice = random.randint(2, p-2)
    private_key_bob = random.randint(2, p-2)

    # Compute public keys
    public_key_alice = pow(g, private_key_alice, p)
    public_key_bob = pow(g, private_key_bob, p)

    # Compute the shared secret key
    shared_secret_key_alice = pow(public_key_bob, private_key_alice, p)
    shared_secret_key_bob = pow(public_key_alice, private_key_bob, p)

    if shared_secret_key_alice != shared_secret_key_bob:
        return (-1, -1, -1, -1, -1)

    return (private_key_alice, public_key_alice, private_key_bob, public_key_bob, shared_secret_key_alice)

