from typing import List

def can_reach_end(matrix: List[List[int]]) -> bool:
    if not matrix or not matrix[0]:
        return False
    m, n = len(matrix), len(matrix[0])
    if matrix[0][0] == 0 or matrix[m-1][n-1] == 0:
        return False

    # BFS to find the path
    from collections import deque
    queue = deque([(0, 0)])
    visited = set((0, 0))

    directions = [(1, 0), (0, 1)]  # down, right

    while queue:
        i, j = queue.popleft()

        if i == m - 1 and j == n - 1:
            return True

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] == 1 and (ni, nj) not in visited:
                queue.append((ni, nj))
                visited.add((ni, nj))

    return False

