def find_pair(numbers, target):
    """
    Determines if there are two distinct elements in the array that add up to the target sum.

    Args:
    numbers (list): A list of integers.
    target (int): The target sum.

    Returns:
    tuple: A tuple containing the indices of the two numbers that add up to the target sum, or None if no such pair exists.
    """
    num_to_index = {}
    for index, num in enumerate(numbers):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], index)
        num_to_index[num] = index
    return None

