from typing import List

def longest_subarray_sum_k(nums: List[int], k: int) -> int:
    """
    Finds the length of the longest subarray with sum equal to k.
    """
    sum_indices = {}
    curr_sum = 0
    max_length = 0

    for i in range(len(nums)):
        curr_sum += nums[i]

        if curr_sum == k:
            max_length = i + 1

        if (curr_sum - k) in sum_indices:
            max_length = max(max_length, i - sum_indices[curr_sum - k])

        if curr_sum not in sum_indices:
            sum_indices[curr_sum] = i

    return max_length

