def kth_smallest_element(arr1, arr2, k):
    """
    Finds the k-th smallest element in the combined sorted array of arr1 and arr2.
    """
    if len(arr1) > len(arr2):
        return kth_smallest_element(arr2, arr1, k)

    if not arr1:
        return arr2[k-1]

    if k == 1:
        return min(arr1[0], arr2[0])

    i = min(len(arr1), k // 2)
    j = min(len(arr2), k // 2)

    if arr1[i - 1] > arr2[j - 1]:
        return kth_smallest_element(arr1, arr2[j:], k - j)
    else:
        return kth_smallest_element(arr1[i:], arr2, k - i)

