def maxPathSum(grid):
    n = len(grid)
    dp = [[0] * n for _ in range(n)]

    dp[0][0] = grid[0][0]

    for i in range(1, n):
        dp[i][0] = dp[i - 1][0] + grid[i][0]
        dp[0][i] = dp[0][i - 1] + grid[0][i]

    for i in range(1, n):
