def count_special_pairs(nums, k):
    """
    Returns the number of special pairs from the given list
    nums, such that the sum of these pairs is a multiple of k.
    """
    count = 0
    n = len(nums)

    # Iterate over all pairs and check if their sum is a multiple of k
    for i in range(n):
        for j in range(i + 1, n):
            if (nums[i] + nums[j]) % k == 0:
                count += 1
    return count

