def partition_labels(s):
    """
    Given a string s consisting of lower-case English letters, 
    divide it into as few parts as possible so that each letter
    appears in at most one part. Return a list of integers 
    representing the size of these parts in order of their appearance.
    """
    last_occurrence = {ch: idx for idx, ch in enumerate(s)}
    partitions = []
    start = end = 0

    for idx, ch in enumerate(s):
        end = max(end, last_occurrence[ch])
        if idx == end:
            partitions.append(end - start + 1)
            start = end + 1

    return partitions

