def is_match(s: str, p: str) -> bool:
    """
    Returns True if string s matches the pattern p where
    '?' matches any single character and '*' matches any
    sequence of characters (including an empty sequence).
    """
    m, n = len(s), len(p)

    # DP table
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Empty string and empty pattern match
    dp[0][0] = True

    # Only '*' can match an empty string
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
            elif p[j - 1] == '?' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]

