def evaluate_expression(s):
    """
    Evaluates a simple mathematical expression containing non-negative integers
    and the operators +, -, *, and /.
    """
    s = s.replace(" ", "")
    stack = []
    num = 0
    operator = '+'

    for i, char in enumerate(s):
        if char.isdigit():
            num = num * 10 + int(char)
        if char in "+-*/" or i == len(s) - 1:
            if operator == '+':
                stack.append(num)
            elif operator == '-':
                stack.append(-num)
            elif operator == '*':
                stack[-1] = stack[-1] * num
            elif operator == '/':
                stack[-1] = int(stack[-1] / num)  # Truncating towards zero
            operator = char
            num = 0

    return sum(stack)

