def min_replacements_to_non_decreasing_sequence(n, growth_rates, x):
    replacements = 0
    i = 0

    while i < n - 1:
        if growth_rates[i] > growth_rates[i + 1]:
            replacements += 1
            growth_rates[i + 1] = x
        i += 1

    return replacements

