def longest_subarray_with_at_most_two_distinct_values(n, arr):
    """
    Returns the length of the longest contiguous subarray containing at most two distinct integer values.
    """
    left, right = 0, 0
    count = {}
    max_length = 0

    while right < n:
        if arr[right] not in count:
            count[arr[right]] = 0
        count[arr[right]] += 1

        while len(count) > 2:
            count[arr[left]] -= 1
            if count[arr[left]] == 0:
                del count[arr[left]]
            left += 1

        max_length = max(max_length, right - left + 1)
        right += 1

    return max_length

