def max_substring_length_with_k_operations(s: str, k: int) -> int:
    n = len(s)
    max_len = 0

    for start in range(n):
        frequency = {}
        unique_count = 0
        max_possible_len = 0

        for end in range(start, n):
            if s[end] not in frequency:
                frequency[s[end]] = 0
            frequency[s[end]] += 1

            if frequency[s[end]] == 1:
                unique_count += 1

            while unique_count + k < (end - start + 1):
                frequency[s[start]] -= 1
                if frequency[s[start]] == 0:
                    unique_count -= 1
                start += 1

            max_possible_len = end - start + 1

            max_len = max(max_len, min(max_possible_len, unique_count + k))

    return max_len

