def determine_hierarchy(n, r, relationships, ceo):
    from collections import defaultdict, deque

    # Build the adjacency list for the graph and count incoming edges
    graph = defaultdict(list)
    in_degree = {ceo: 0}

    for a, b in relationships:
        graph[b].append(a)
        if a not in in_degree:
            in_degree[a] = 0
        in_degree[a] += 1

    # Initialize queue for topological sort and levels dictionary
    queue = deque([ceo])
    levels = {ceo: 0}

    # Traverse the graph using BFS to determine the level of each employee
    while queue:
        current = queue.popleft()
        current_level = levels[current]

        for report in graph[current]:
            levels[report] = current_level + 1
            in_degree[report] -= 1
            if in_degree[report] == 0:
                queue.append(report)

    # Check for invalid hierarchy
    for employee, deg in in_degree.items():
        if deg != 0:
            return "invalid"

    # Format the result
    result = [(employee, levels[employee]) for employee in sorted(levels)]

    return result

