def max_non_adjacent_sum(arr):
    """
    Returns the maximum sum of non-adjacent integers in the array.
    """
    if not arr:
        return 0
    elif len(arr) == 1:
        return arr[0]

    incl = arr[0]  # Max sum including the previous element.
    excl = 0       # Max sum excluding the previous element.

    for i in arr[1:]:
        new_excl = max(incl, excl)  # Current max excluding i
        incl = excl + i             # Current max including i
        excl = new_excl             # Update excl to new_excl

    return max(incl, excl)

