def maximizeBCount(s):
    """
    Maximizes the count of 'b' in the given string s by changing at most one
    contiguous substring of 'a' into 'b'.

    :param s: string consisting of characters 'a' and 'b'
    :return: maximum possible count of 'b' in the transformed string
    """
    current_max = 0
    max_b = 0
    total_b = 0

    for char in s:
        if char == 'b':
            total_b += 1

    for i in range(len(s)):
        if s[i] == 'a':
            current_max += 1
        else:
            current_max = 0

        max_b = max(max_b, total_b + current_max)

    return min(max_b, len(s))  # we cannot have more 'b's than the total length of the string

