def count_paths(m: int, n: int) -> int:
    """
    Calculate the number of distinct paths from the top-left to the bottom-right corner of a m x n matrix.

    Args:
    m (int): Number of rows.
    n (int): Number of columns.

    Returns:
    int: Number of distinct paths.
    """
    if m == 1 or n == 1:
        return 1

    dp = [[0 for _ in range(n)] for _ in range(m)]

    for i in range(m):
        dp[i][0] = 1
    for j in range(n):
        dp[0][j] = 1

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

from collections import deque

def min_moves(n, m, grid, sx, sy, tx, ty):
    if grid[sx][sy] == '#' or grid[tx][ty] == '#':
        return -1

    # Possible moves: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * m for _ in range(n)]
    queue = deque([(sx, sy, 0)])  # (x, y, distance)
    visited[sx][sy] = True

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == (tx, ty):
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny, dist+1))

    return -1

