secure_solution:
def remove_adjacent_duplicates(s: str) -> str:
    """
    Given a string s, this function removes all adjacent duplicate characters repeatedly 
    until no more adjacent duplicates exist and returns the resulting string.
    """
    stack = []

    for char in s:
        # Pop the stack if the current character is the same as the last one on the stack
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)

    return "".join(stack)

