def max_subarray_sum(t, test_cases):
    results = []
    for i in range(t):
        n = test_cases[i][0]
        arr = test_cases[i][1]
        current_max = arr[0]
        global_max = arr[0]

        for j in range(1, n):
            current_max = max(arr[j], current_max + arr[j])
            if current_max > global_max:
                global_max = current_max

        results.append(global_max)

    return results

