def can_make_rows_equals_with_one_change(grid, n, m):
    # Calculate initial row sums
    row_sums = [sum(row) for row in grid]

    # Find the target row sum and its frequency
    sum_freq = {}
    for rs in row_sums:
        if rs in sum_freq:
            sum_freq[rs] += 1
        else:
            sum_freq[rs] = 1

    # If all row sums are already the same
    if len(sum_freq) == 1:
        return "YES"

    # Variant frequency map to hold possible corrected sums
    variant_freq = {}
    for i, rs in enumerate(row_sums):
        for j in range(m):
            if grid[i][j] != 7:  # Change non-7 elements to 7 and recalculate sum
                corrected_sum = rs - grid[i][j] + 7
                if corrected_sum in variant_freq:
                    variant_freq[corrected_sum] += 1
                else:
                    variant_freq[corrected_sum] = 1

    # Check if any corrected row sum appears in all but one original rows
    for corrected_sum in variant_freq:
        if variant_freq[corrected_sum] == n - 1:  
            return "YES"

    return "NO"

