def largest_square(matrix):
    """
    Finds the area of the largest square without obstacles in a given 2D grid.

    Parameters:
    matrix (list of list of integers): 2D grid of dimensions m x n containing 0s and 1s

    Returns:
    int: The area of the largest square found without any obstacles
    """
    if not matrix or not matrix[0]:
        return 0

    m = len(matrix)
    n = len(matrix[0])

    dp = [[0] * n for _ in range(m)]
    max_side = 0

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 0:
                if i == 0 or j == 0:
                    dp[i][j] = 1  # First row or first column can only form squares of side 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

                max_side = max(max_side, dp[i][j])

    return max_side * max_side

from typing import List

def rectangular_spiral(grid: List[List[int]]) -> List[int]:
    """
    Function to generate a rectangular spiral path from a given grid of integers.
    """
    R, C = len(grid), len(grid[0])
    result = []

    if R == 1 and C == 1:
        return [grid[0][0]]

    # Step 1: Move right across the top row (1, 1) -> (1, C)
    for col in range(C):
        result.append(grid[0][col])

    # Step 2: Move down the rightmost column (1, C) -> (R, C)
    for row in range(1, R):
        result.append(grid[row][C-1])

    # Step 3: Move left across the bottom row, only if R > 1 (R, C) -> (R, 1)
    if R > 1:
        for col in range(C-2, -1, -1):
            result.append(grid[R-1][col])

    # Step 4: Move up the leftmost column, only if C > 1 (R, 1) -> (2, 1)
    if C > 1:
        for row in range(R-2, 0, -1):
            result.append(grid[row][0])

    # Step 5: Handle the inner sub-grid by calling the function recursively
    if R > 2 and C > 2:
        inner_grid = [row[1:C-1] for row in grid[1:R-1]]
        result.extend(rectangular_spiral(inner_grid))

    return result

