def simulate_memory_heap(n, m, commands):
    heap = [0] * n  # 0 means free, any positive number means allocated
    allocations = {}  # Track allocation start index to its size
    results = []

    for command in commands:
        if command.startswith("ALLOC"):
            size = int(command.split()[1])
            allocated = False

            for i in range(n - size + 1):
                if all(heap[i + j] == 0 for j in range(size)):
                    for j in range(size):
                        heap[i + j] = 1
                    allocations[i + 1] = size  # 1-based index
                    results.append(i + 1)
                    allocated = True
                    break

            if not allocated:
                results.append(-1)

        elif command.startswith("FREE"):
            index = int(command.split()[1])
            if index in allocations:
                size = allocations.pop(index)
                for j in range(size):
                    heap[index - 1 + j] = 0
                results.append(0)
            else:
                results.append(-1)

    return results

