def count_ladders(n, d, rods):
    """
    Calculate the number of distinct ways to build ladders using given rods 
    such that the total height is exactly d units.
    """
    from itertools import combinations

    count = 0
    # Iterate over all possible lengths of combinations
    for r in range(1, n + 1):
        for combo in combinations(rods, r):
            if sum(combo) == d:
                count += 1
    return count

