def min_deletions_to_palindrome(s: str) -> int:
    """
    Returns the minimum number of deletions needed to make the string a palindrome.
    """
    n = len(s)

    # Create a table to calculate the lengths of longest palindromic subsequences
    dp = [[0] * n for _ in range(n)]

    # Fill the table
    for i in range(n):
        dp[i][i] = 1

    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    # The result is the number of deletions required to make the string a palindrome
    return n - dp[0][n - 1]

