def min_operations_to_zero(n, arr):
    operations = 0
    i = 0

    while i < n:
        # if we encounter a zero, move to the next element
        if arr[i] == 0:
            i += 1
        else:
            # Start of new non-zero subarray
            max_in_subarray = arr[i]
            # Move through the continuous non-zero subarray to find the maximum in that subarray
            while i < n and arr[i] != 0:
                max_in_subarray = max(max_in_subarray, arr[i])
                i += 1
            operations += max_in_subarray

    return operations

