def find_zero_sum_subarray(n, arr):
    """
    Returns the starting and ending indices of the first subarray with sum equal to zero.
    If no such subarray exists, returns -1.
    """
    sum_indices = {}
    current_sum = 0

    for i in range(n):
        current_sum += arr[i]

        if current_sum == 0:
            return (0, i)

        if current_sum in sum_indices:
            return (sum_indices[current_sum] + 1, i)

        sum_indices[current_sum] = i

    return -1

