def min_cuts_to_increasing_sequence(N, heights):
    """
    Returns the minimum number of cuts required to make the sequence of tree heights strictly increasing.
    """
    if N == 0:
        return 0

    # Longest increasing subsequence (LIS) using dynamic programming
    dp = [1] * N

    for i in range(1, N):
        for j in range(i):
            if heights[i] > heights[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The number of cuts required is the total number of trees minus the length of the LIS
    return N - max(dp)

