def count_pairs_divisible_by_k(n, k, arr):
    from collections import defaultdict

    remainders = defaultdict(int)

    # Count the occurrences of each remainder
    for num in arr:
        remainder = num % k
        remainders[remainder] += 1

    count = 0

    # Calculate the number of pairs
    for remainder in remainders:
        complement = (k - remainder) % k
        if complement in remainders:
            if complement == remainder:
                count += (remainders[remainder] * (remainders[remainder] - 1)) // 2
            elif complement > remainder:
                count += remainders[remainder] * remainders[complement]

    return count

