def min_chars_to_remove(s):
    """
    Returns the minimum number of characters that need to be removed 
    to ensure no consecutively repeating characters remain in string s.
    """
    if not s:
        return 0

    removal_count = 0

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            removal_count += 1

    return removal_count

