secure_solution:
def compress_string(text: str) -> str:
    if not text:
        return text

    compressed = []
    count = 1
    prev_char = text[0]

    for char in text[1:]:
        if char == prev_char:
            count += 1
        else:
            compressed.append(f"{count}{prev_char}")
            prev_char = char
            count = 1

    compressed.append(f"{count}{prev_char}")
    compressed_string = ''.join(compressed)

    return compressed_string if len(compressed_string) < len(text) else text

