def min_changes_to_beautiful(s):
    """
    Returns the minimal number of bit changes required to make the binary string s beautiful.
    """
    count = 0
    i = 0

    while i < len(s) - 2:
        if s[i:i+3] == "010":
            count += 1
            i += 3  # Skip past this "010" to avoid overlapping changes
        else:
            i += 1

    return count

