def longest_subarray_with_sum(arr, m):
    """
    Returns the length of the longest contiguous subarray whose sum is exactly m.
    If no such subarray exists, returns -1.
    """
    sum_indices = {0: -1}
    curr_sum = 0
    max_len = -1

    for i, num in enumerate(arr):
        curr_sum += num

        if (curr_sum - m) in sum_indices:
            max_len = max(max_len, i - sum_indices[curr_sum - m])

        if curr_sum not in sum_indices:
            sum_indices[curr_sum] = i

    return max_len

