def find_pair_with_sum(arr, S):
    """
    Given an integer array `arr` and a target sum `S`,
    determine if there are two distinct elements in the array such
    that their sum is equal to `S`. If a pair is found, return the pair,
    otherwise return "No pair found".
    """
    seen = {}

    for number in arr:
        complement = S - number
        if complement in seen:
            return (complement, number)
        seen[number] = True

    return "No pair found"

