def shortest_path(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return -1

    n = len(grid)
    if grid[0][0] == 1 or grid[n-1][n-1] == 1:
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0)])
