def min_jumps_to_end(arr, jumps):
    n = len(arr)
    if n == 0 or jumps[0] == 0:
        return -1

    max_reach = 0
    step = 0
    end = 0
    jumps_count = 0

    for i in range(n):
        if i > max_reach:
            return -1
        max_reach = max(max_reach, i + jumps[i])
        if i == end:
            if i == n - 1:
                break
            end = max_reach
            jumps_count += 1
            if end >= n - 1:
                break

    return jumps_count if max_reach >= n - 1 else -1

