def unique_paths(n, k, blocked_cells):
    # Initialize a 2D list with zeroes 
    dp = [[0] * n for _ in range(n)]

    # Mark blocked cells
    for x, y in blocked_cells:
        dp[x-1][y-1] = -1  # Using -1 to denote blocked cells

    # Starting point
    if dp[0][0] == -1:
        return 0

    dp[0][0] = 1

    # Fill the first row
    for j in range(1, n):
        if dp[0][j] == -1:
            break
        dp[0][j] = 1

    # Fill the first column
    for i in range(1, n):
        if dp[i][0] == -1:
            break
        dp[i][0] = 1

    # Compute number of unique paths for each cell
    for i in range(1, n):
        for j in range(1, n):
            if dp[i][j] == -1:
                continue
            if dp[i-1][j] != -1:
                dp[i][j] += dp[i-1][j]
            if dp[i][j-1] != -1:
                dp[i][j] += dp[i][j-1]

    # The number of unique paths to the bottom-right corner
    return dp[-1][-1]

